  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "When life suddenly changes",
  "crisis_lead": "A sudden change doesn't undo the progress you've made. Pick whichever is closest to your situation — each plan starts with the one or two things that matter most today, then how to steady the ground under you.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Draft a letter to your creditor",
  "crisis_act_support": "Find verified help where you are",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "This is general guidance, not legal or medical advice. For anything specific to your situation, lean on the free services in Support and, where it matters, a qualified professional.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "Losing an income is frightening, but you have more room to move than it feels like right now. Nothing has to be solved today — only started.",
  "crisis_jobloss_i1": "Protect the essentials first. Before any unsecured debt, make sure housing, food, utilities and the transport you need to find work are covered. These come before card or loan payments.",
  "crisis_jobloss_i2": "Tell your creditors before you miss a payment. A short, honest message that your income has changed opens the door to a pause or a lower payment — and it's far easier to arrange before an arrears letter arrives.",
  "crisis_jobloss_i3": "Check what you're entitled to. There may be support you can claim while you're between jobs. The verified services in your country can tell you exactly what applies to you.",
  "crisis_jobloss_s1": "Rebuild the budget around your new, lower income — essentials only for now, everything else paused until things settle.",
  "crisis_jobloss_s2": "Get any temporary arrangement with a creditor in writing, so a hard month doesn't quietly turn into a default.",
  "crisis_jobloss_s3": "Don't take on new debt to cover old debt. Borrowing to pay a lender only deepens the hole — the plans and tools here are built to work without it.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "When your health needs your attention, money worries make everything heavier. Your recovery comes first — this plan keeps the financial side from adding to the load.",
  "crisis_illness_i1": "Protect the essentials first. Housing, food, utilities and whatever you need for your care come before any unsecured debt payment.",
  "crisis_illness_i2": "Let creditors know your situation has changed. You don't owe anyone your medical details — only that your income or capacity has changed, and that you're asking for a temporary hardship arrangement.",
  "crisis_illness_i3": "Claim what you're entitled to. There may be sick pay or support you qualify for. The verified services in your country will point you to the right place — and please lean on medical professionals for the health side.",
  "crisis_illness_s1": "Trim the budget to essentials while your income is reduced, and revisit it as your situation changes.",
  "crisis_illness_s2": "Put any creditor arrangement in writing and keep a copy — one less thing to hold in your head.",
  "crisis_illness_s3": "Don't borrow to cover existing debt. Ask for time instead; most creditors would far rather wait than push you further.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Untangling a shared life is hard enough without the money fog. Take it one clear step at a time — you don't need every answer this week.",
  "crisis_sep_i1": "Protect the essentials first, for you and anyone who depends on you. Housing, food and utilities come before unsecured debt.",
  "crisis_sep_i2": "Contact creditors early about any joint debts. Ask what your options are and get every change in writing. Where a debt is in both names, keep a record of what's agreed.",
  "crisis_sep_i3": "Check what support you can claim as your household changes. The verified services in your country can tell you what applies — and for the legal side of shared debts, national free debt-help or a qualified adviser is the right place to turn.",
  "crisis_sep_s1": "Rebuild the budget around your own income and costs as a single household.",
  "crisis_sep_s2": "Where you can, separate finances step by step, keeping written records of every arrangement.",
  "crisis_sep_s3": "Don't take on new debt to smooth the transition. Steady, honest arrangements protect you far better than borrowing.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "An unexpected cost or shock can knock the plan sideways. It doesn't erase the progress you've made — it just needs a calm pause and one clear next step.",
  "crisis_emerg_i1": "Cover the true essentials first — safety, housing, food, utilities. A one-off emergency is not the moment to put a card payment ahead of keeping the lights on.",
  "crisis_emerg_i2": "If the emergency means you'll miss a payment, tell that creditor now and ask for a short payment holiday. A planned pause is always better than a silent miss.",
  "crisis_emerg_i3": "Check for any emergency support you can draw on. The verified services in your country can point you to help you may not know exists.",
  "crisis_emerg_s1": "Once the immediate shock is handled, rebuild your buffer slowly — even a small amount each week counts.",
  "crisis_emerg_s2": "Re-check the budget and adjust the plan for the coming weeks, not the whole year at once.",
  "crisis_emerg_s3": "Avoid high-cost borrowing to bridge the gap. A short arrangement with a creditor you already have almost always costs you less.",
