  "h_eco_p5_tag": "Coming 2029",
  "h_pf_eyebrow": "90-DAY PLAN · 0€ forever",
  "h_pf_title": "Your complete starting point.",
  "h_pf_lead": "Most people spend months guessing what to do about debt — avoiding letters, avoiding numbers, avoiding the whole subject. This replaces guessing with certainty, in about two minutes, at no cost.",
  "h_pf_li1_feat": "A personalised plan built from your real numbers",
  "h_pf_li1_mean": "— not advice that could apply to anyone",
