  "h_pf_feat1": "Ready-made creditor letter templates",
  "h_pf_feat3": "Real support through setbacks",
  "h_pf_link": "See how the 90-Day Companion works →",
  "h_sales_title": "Stop carrying this alone. Get a clear plan today.",
  "h_sales_p": "You do not need financial training or a high income to begin — just your real numbers and two minutes. Entirely free, with nothing to risk.",
  "h_sales_btn": "Generate my plan now",
  "h_sales_fine": "No subscription. No hidden fees. Just clarity.",
  "h_proof_title": "In their own words — soon",
  "h_proof_body": "We're new, and we would rather show you nothing than show you reviews we wrote ourselves. When real people share how this went for them, their words will live here — with only as much of their name as they choose to give. Until then, the plan we build for you is the only proof we offer.",
  "h_faq_label": "Common questions",
  "h_faq_q1": "Is it really free?",
  "h_faq_a1": "Yes. The 90-day debt plan and all 90-Day Plan tools are free — no payment card, no hidden costs, no time limit. The 90-Day Companion (19€, one-time) is an optional upgrade.",
  "h_faq_q2": "Do I need a payment card?",
  "h_faq_a2": "No. Free plan requires no payment card. Only The 90-Day Companion (19€ one-time) requires payment — via Stripe, secure checkout.",
  "h_faq_q3": "Will anyone call me?",
  "h_faq_a3": "No. We never call. Your plan is delivered by email. All contact is on your terms.",
  "h_faq_q4": "How do you use my information?",
