  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Kriisisuunnitelmat",
  "crisis_title": "Kun elämä yhtäkkiä muuttuu",
  "crisis_lead": "Äkillinen muutos ei pyyhi pois jo saavuttamaasi. Valitse tilannettasi lähinnä oleva — jokainen suunnitelma alkaa niistä yhdestä tai kahdesta asiasta, jotka ovat juuri nyt tärkeimpiä, ja etenee siihen, miten saat jalat taas maahan.",
  "crisis_immediate": "Juuri nyt",
  "crisis_stabilise": "Vakauta tilanne",
  "crisis_act_letter": "Laadi kirje velkojalle",
  "crisis_act_support": "Etsi vahvistettua apua läheltäsi",
  "crisis_act_budget": "Avaa budjettityökalu",
  "crisis_safe_note": "Tämä on yleistä ohjeistusta, ei oikeudellista tai lääketieteellistä neuvontaa. Omaan tilanteeseesi liittyvissä asioissa nojaa Tuki-osion ilmaisiin palveluihin ja tarvittaessa pätevään ammattilaiseen.",
  "crisis_jobloss_t": "Työn menetys",
  "crisis_jobloss_intro": "Tulojen menetys pelottaa, mutta liikkumavaraa on enemmän kuin juuri nyt tuntuu. Mitään ei tarvitse ratkaista tänään — vain aloittaa.",
  "crisis_jobloss_i1": "Suojaa välttämättömät ensin. Ennen mitään vakuudetonta velkaa varmista, että asuminen, ruoka, sähkö ja vesi sekä työnhakuun tarvitsemasi liikkuminen on turvattu. Nämä menevät kortti- ja lainamaksujen edelle.",
  "crisis_jobloss_i2": "Kerro velkojille ennen kuin maksu myöhästyy. Lyhyt, rehellinen viesti tulojesi muutoksesta avaa oven maksutauolle tai pienemmälle erälle — ja sen järjestäminen on paljon helpompaa ennen kuin perintäkirje saapuu.",
  "crisis_jobloss_i3": "Selvitä, mihin olet oikeutettu. Työttömyyden aikana voi olla tukea, jota voit hakea. Maasi vahvistetut palvelut kertovat tarkalleen, mikä koskee sinua.",
  "crisis_jobloss_s1": "Rakenna budjetti uudelleen uuden, pienemmän tulon ympärille — toistaiseksi vain välttämättömät, muu tauolle kunnes tilanne tasaantuu.",
  "crisis_jobloss_s2": "Ota kaikki väliaikaiset järjestelyt velkojan kanssa kirjallisena, jottei vaikea kuukausi muutu hiljaa maksuhäiriöksi.",
  "crisis_jobloss_s3": "Älä ota uutta velkaa vanhan kattamiseksi. Lainaaminen velan maksuun vain syventää kuoppaa — täkäläiset suunnitelmat ja työkalut on tehty toimimaan ilman sitä.",
  "crisis_illness_t": "Sairaus tai sairausloma",
  "crisis_illness_intro": "Kun terveys vaatii huomiosi, rahahuolet painavat kaikkea entistä enemmän. Toipumisesi tulee ensin — tämä suunnitelma pitää talouspuolen pois taakan päältä.",
  "crisis_illness_i1": "Suojaa välttämättömät ensin. Asuminen, ruoka, sähkö ja vesi sekä hoitoosi tarvitsemasi menevät vakuudettomien velkojen maksun edelle.",
  "crisis_illness_i2": "Kerro velkojille, että tilanteesi on muuttunut. Et ole kenellekään velkaa terveystietojasi — vain sen, että tulosi tai jaksamisesi on muuttunut ja että pyydät väliaikaista maksujärjestelyä.",
  "crisis_illness_i3": "Hae se, mihin olet oikeutettu. Sinulla voi olla oikeus sairauspäivärahaan tai muuhun tukeen. Maasi vahvistetut palvelut ohjaavat oikeaan paikkaan — ja terveyden osalta nojaa terveydenhuollon ammattilaisiin.",
  "crisis_illness_s1": "Karsi budjetti välttämättömiin, kun tulot ovat pienemmät, ja tarkista se uudelleen tilanteen muuttuessa.",
  "crisis_illness_s2": "Ota jokainen järjestely velkojan kanssa kirjallisena ja säilytä kopio — yksi asia vähemmän pidettävänä mielessä.",
  "crisis_illness_s3": "Älä lainaa kattaaksesi olemassa olevaa velkaa. Pyydä sen sijaan aikaa; useimmat velkojat mieluummin odottavat kuin ajavat sinut ahtaammalle.",
  "crisis_sep_t": "Ero tai avioero",
  "crisis_sep_intro": "Yhteisen elämän purkaminen on jo tarpeeksi raskasta ilman rahasumua. Etene yksi selkeä askel kerrallaan — sinun ei tarvitse tietää kaikkia vastauksia tällä viikolla.",
  "crisis_sep_i1": "Suojaa välttämättömät ensin — itsellesi ja niille, jotka ovat sinusta riippuvaisia. Asuminen, ruoka, sähkö ja vesi menevät vakuudettoman velan edelle.",
  "crisis_sep_i2": "Ota yhteyttä velkojiin ajoissa yhteisistä veloista. Kysy vaihtoehdoistasi ja ota jokainen muutos kirjallisena. Kun velka on molempien nimissä, pidä kirjaa siitä, mistä on sovittu.",
  "crisis_sep_i3": "Selvitä, mitä tukea voit hakea kotitalouden muuttuessa. Maasi vahvistetut palvelut kertovat, mikä koskee sinua — ja yhteisten velkojen oikeudellisessa puolessa oikea paikka on kansallinen ilmainen velka-apu tai pätevä neuvoja.",
  "crisis_sep_s1": "Rakenna budjetti uudelleen omien tulojesi ja menojesi ympärille yhden hengen taloutena.",
  "crisis_sep_s2": "Erottele taloudet askel kerrallaan siellä missä voit, ja pidä kirjalliset merkinnät jokaisesta järjestelystä.",
  "crisis_sep_s3": "Älä ota uutta velkaa pehmentääksesi siirtymää. Vakaat, rehelliset järjestelyt suojaavat sinua paljon paremmin kuin lainaaminen.",
  "crisis_emerg_t": "Äkillinen hätätilanne",
  "crisis_emerg_intro": "Yllättävä kulu tai shokki voi kaataa suunnitelman hetkeksi. Se ei pyyhi pois edistystäsi — se vaatii vain rauhallisen tauon ja yhden selkeän seuraavan askeleen.",
  "crisis_emerg_i1": "Kata todelliset välttämättömät ensin — turvallisuus, asuminen, ruoka, sähkö ja vesi. Kertaluontoinen hätä ei ole hetki asettaa korttimaksua valojen palamisen edelle.",
  "crisis_emerg_i2": "Jos hätä tarkoittaa, että maksu myöhästyy, kerro siitä velkojalle nyt ja pyydä lyhyttä maksutaukoa. Suunniteltu tauko on aina parempi kuin hiljainen myöhästyminen.",
  "crisis_emerg_i3": "Selvitä, onko sinulla käytettävissä hätäapua. Maasi vahvistetut palvelut voivat ohjata sinut avun luo, jota et ehkä tiennyt olevan.",
  "crisis_emerg_s1": "Kun välitön shokki on hoidettu, rakenna puskuria takaisin hitaasti — pienikin summa joka viikko merkitsee.",
  "crisis_emerg_s2": "Tarkista budjetti uudelleen ja säädä suunnitelmaa tuleville viikoille, ei koko vuodelle kerralla.",
  "crisis_emerg_s3": "Vältä kallista lainaa aukon paikkaamiseen. Lyhyt järjestely jo olemassa olevan velkojan kanssa maksaa lähes aina vähemmän.",
  "ci_trend_title": "Puskurisi viikko viikolta",
  "ci_trend_empty": "Trendisi rakentuu tähän. Kirjaa pari viikkoa, niin näet sen alkavan muotoutua.",
  "ci_title": "Miten tämä viikko sujui?",
  "ci_lead": "Nopea kirjaus — ei arvostelua, ei putkea rikottavana. Vain merkki siitä, missä olet tällä viikolla.",
