  "mf_dl_btn": "Ladda ner min plan",
  "mf_dl_ok": "Sparad. Den är din nu.",
  "mf_dl_err": "Vi kunde inte skapa din fil just nu. Försök igen om en stund — inget är förlorat.",
  "mf_x_created": "Skapad",
  "mf_x_plan_h": "Din plan",
  "mf_x_repeat": "Vi ersätter inte dessa tjänster. Vi är byggda för att användas vid sidan av dem.",
  "mf_x_del90": "På dag 90 raderar vi din plan, dina svar, dina dokument och allt personligt i dem. Ingenting av ditt blir kvar i vår tjänst. Din plan är din och fungerar utan oss.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Krisplaner",
  "crisis_title": "När livet plötsligt förändras",
  "crisis_lead": "En plötslig förändring suddar inte ut framstegen du gjort. Välj det som ligger närmast din situation — varje plan börjar med de en eller två saker som betyder mest idag, och sedan hur du får stadig mark under fötterna.",
  "crisis_immediate": "Just nu",
  "crisis_stabilise": "Få stadig mark",
  "crisis_act_letter": "Skriv ett brevutkast till din borgenär",
  "crisis_act_support": "Hitta verifierad hjälp där du är",
  "crisis_act_budget": "Öppna budgetplaneraren",
  "crisis_safe_note": "Detta är allmän vägledning, inte juridisk eller medicinsk rådgivning. I allt som rör just din situation, luta dig mot de kostnadsfria tjänsterna under Stöd och, när det behövs, en kvalificerad fackperson.",
  "crisis_jobloss_t": "Förlorat jobb",
  "crisis_jobloss_intro": "Att förlora en inkomst är skrämmande, men du har mer handlingsutrymme än det känns just nu. Ingenting måste lösas idag — bara påbörjas.",
  "crisis_jobloss_i1": "Skydda det nödvändiga först. Före all skuld utan säkerhet, se till att boende, mat, el och vatten och den transport du behöver för att hitta jobb är täckta. Detta går före kort- och lånebetalningar.",
  "crisis_jobloss_i2": "Berätta för dina borgenärer innan en betalning uteblir. Ett kort, ärligt meddelande om att din inkomst har ändrats öppnar dörren för en paus eller en lägre betalning — och det är mycket lättare att ordna innan ett kravbrev kommer.",
  "crisis_jobloss_i3": "Ta reda på vad du har rätt till. Det kan finnas stöd du kan söka medan du är mellan jobb. De verifierade tjänsterna i ditt land kan säga exakt vad som gäller för dig.",
  "crisis_jobloss_s1": "Bygg om budgeten runt din nya, lägre inkomst — bara det nödvändiga för nu, allt annat pausat tills läget stabiliserats.",
  "crisis_jobloss_s2": "Få varje tillfällig överenskommelse med en borgenär skriftligt, så att en tuff månad inte tyst blir en betalningsförsummelse.",
  "crisis_jobloss_s3": "Ta inte ny skuld för att täcka gammal skuld. Att låna för att betala en långivare gräver bara hålet djupare — planerna och verktygen här är byggda för att fungera utan det.",
  "crisis_illness_t": "Sjukdom eller sjukskrivning",
  "crisis_illness_intro": "När hälsan behöver din uppmärksamhet gör pengabekymmer allt tyngre. Din återhämtning kommer först — den här planen ser till att ekonomin inte lägger mer på bördan.",
  "crisis_illness_i1": "Skydda det nödvändiga först. Boende, mat, el och vatten och allt du behöver för din vård går före varje betalning av skuld utan säkerhet.",
  "crisis_illness_i2": "Låt borgenärerna veta att din situation har ändrats. Du är inte skyldig någon dina medicinska uppgifter — bara att din inkomst eller ork har ändrats, och att du ber om en tillfällig lättnad.",
  "crisis_illness_i3": "Sök det du har rätt till. Det kan finnas sjukersättning eller stöd du kvalificerar dig för. De verifierade tjänsterna i ditt land pekar dig åt rätt håll — och luta dig mot vårdpersonal för hälsodelen.",
  "crisis_illness_s1": "Skala ner budgeten till det nödvändiga medan inkomsten är lägre, och se över den när din situation ändras.",
  "crisis_illness_s2": "Få varje överenskommelse med en borgenär skriftligt och spara en kopia — en sak mindre att hålla i huvudet.",
  "crisis_illness_s3": "Låna inte för att täcka befintlig skuld. Be om tid i stället; de flesta borgenärer väntar hellre än pressar dig ytterligare.",
  "crisis_sep_t": "Separation eller skilsmässa",
  "crisis_sep_intro": "Att reda ut ett delat liv är svårt nog utan penningdimman. Ta ett tydligt steg i taget — du behöver inte ha alla svar den här veckan.",
  "crisis_sep_i1": "Skydda det nödvändiga först, för dig och alla som är beroende av dig. Boende, mat och el och vatten går före skuld utan säkerhet.",
  "crisis_sep_i2": "Kontakta borgenärer tidigt om alla gemensamma skulder. Fråga vilka alternativ du har och få varje ändring skriftligt. När en skuld står i båda namnen, för anteckningar om det som överenskoms.",
  "crisis_sep_i3": "Ta reda på vilket stöd du kan söka när ditt hushåll förändras. De verifierade tjänsterna i ditt land kan säga vad som gäller — och för den juridiska sidan av gemensamma skulder är kostnadsfri nationell skuldhjälp eller en kvalificerad rådgivare rätt ställe att vända sig till.",
  "crisis_sep_s1": "Bygg om budgeten runt din egen inkomst och dina kostnader som ett enpersonshushåll.",
  "crisis_sep_s2": "Där du kan, separera ekonomin steg för steg och för skriftliga anteckningar om varje överenskommelse.",
  "crisis_sep_s3": "Ta inte ny skuld för att jämna ut övergången. Stadiga, ärliga överenskommelser skyddar dig långt bättre än att låna.",
  "crisis_emerg_t": "En plötslig nödsituation",
  "crisis_emerg_intro": "En oväntad utgift eller chock kan slå planen ur kurs. Den suddar inte ut framstegen du gjort — den kräver bara en lugn paus och ett tydligt nästa steg.",
  "crisis_emerg_i1": "Täck det verkligt nödvändiga först — trygghet, boende, mat, el och vatten. En engångskris är inte stunden att sätta en kortbetalning före att hålla lamporna tända.",
  "crisis_emerg_i2": "Om krisen gör att en betalning uteblir, säg det till den borgenären nu och be om en kort betalningspaus. En planerad paus är alltid bättre än en tyst utebliven betalning.",
  "crisis_emerg_i3": "Se om det finns krisstöd du kan använda. De verifierade tjänsterna i ditt land kan visa dig hjälp du kanske inte visste fanns.",
  "crisis_emerg_s1": "När den akuta chocken är hanterad, bygg upp din buffert långsamt — även en liten summa varje vecka räknas.",
  "crisis_emerg_s2": "Se över budgeten igen och justera planen för de kommande veckorna, inte hela året på en gång.",
  "crisis_emerg_s3": "Undvik dyra lån för att överbrygga glappet. En kort överenskommelse med en borgenär du redan har kostar dig nästan alltid mindre.",
  "ci_trend_title": "Din buffert, vecka för vecka",
  "ci_trend_empty": "Din trend byggs upp här. Logga ett par veckor så ser du den ta form.",
