  "sf_email_label": "Deine E-Mail-Adresse",
  "sf_err_email": "Bitte gib eine gültige E-Mail-Adresse ein.",
  "sf_privacy": "Ich habe die <a href=\"/legal#privacy\" target=\"_blank\">Datenschutzerklärung</a> gelesen und akzeptiere sie. Meine Daten werden nur genutzt, um meinen persönlichen Plan zu erstellen.",
  "sf_err_privacy": "Bitte akzeptiere die Datenschutzerklärung, um fortzufahren.",
  "sf_cta_note": "Keine Zahlungskarte. Kein Abo. Keine Testphase. Der Plan ist kostenlos, immer.",
  "sf_retention": "Dein Konto und dein Plan werden 90 Tage ab dem Tag ihrer Erstellung aufbewahrt. Du kannst deinen Plan jederzeit herunterladen, und wir erinnern dich, bevor er verschwindet.",
