  "sf_inbox_t": "Sieh in deinem Posteingang nach.",
  "sf_inbox_s1": "Wir haben deinen Zugangslink gesendet an",
  "sf_inbox_s2": "Klick auf den Link in dieser E-Mail, um deinen Plan direkt zu öffnen.",
  "sf_resend_q": "Nach 2 Minuten keine E-Mail? Sieh im Spam-Ordner nach, oder",
  "sf_resend_btn": "schick sie erneut",
