  "sf_foot_legal": "Datenschutz & AGB",
  "mf_dl_h": "Behalte deinen Plan",
  "mf_dl_note": "Eine Datei mit deinem Plan, dem Datum seiner Erstellung und den kostenlosen Angeboten in deinem Land. Die Datei öffnet sich auf jedem Gerät, funktioniert ohne Internet und gehört dir.",
  "mf_dl_btn": "Meinen Plan herunterladen",
  "mf_dl_ok": "Gespeichert. Er gehört jetzt dir.",
  "mf_dl_err": "Wir konnten deine Datei gerade nicht erstellen. Versuch es gleich noch einmal — nichts ist verloren.",
  "mf_x_created": "Erstellt am",
  "mf_x_plan_h": "Dein Plan",
  "mf_x_repeat": "Wir ersetzen diese Angebote nicht. Wir sind dafür gemacht, neben ihnen genutzt zu werden.",
  "mf_x_del90": "An Tag 90 löschen wir deinen Plan, deine Antworten, deine Dokumente und alles Persönliche darin. In unserem Dienst bleibt nichts von dir. Dein Plan gehört dir und funktioniert ohne uns.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Krisenpläne",
  "crisis_title": "Wenn sich das Leben plötzlich ändert",
  "crisis_lead": "Eine plötzliche Veränderung macht deinen Fortschritt nicht zunichte. Wähle, was deiner Situation am nächsten kommt — jeder Plan beginnt mit den ein, zwei Dingen, die heute am meisten zählen, und dann damit, wie du wieder festen Boden gewinnst.",
  "crisis_immediate": "Gerade jetzt",
  "crisis_stabilise": "Festen Boden gewinnen",
  "crisis_act_letter": "Entwirf einen Brief an deinen Gläubiger",
  "crisis_act_support": "Finde geprüfte Hilfe dort, wo du bist",
  "crisis_act_budget": "Öffne den Budgetplaner",
  "crisis_safe_note": "Dies ist eine allgemeine Orientierung, keine Rechts- oder medizinische Beratung. Für alles, was deine konkrete Situation betrifft, stütze dich auf die kostenlosen Angebote unter Unterstützung und, wo es zählt, auf eine qualifizierte Fachperson.",
  "crisis_jobloss_t": "Jobverlust",
  "crisis_jobloss_intro": "Ein Einkommen zu verlieren macht Angst, aber du hast mehr Spielraum, als es sich gerade anfühlt. Nichts muss heute gelöst werden — nur begonnen.",
  "crisis_jobloss_i1": "Schütze zuerst das Lebensnotwendige. Vor jeder unbesicherten Schuld sollten Wohnen, Essen, Strom und Wasser und der Weg zur Jobsuche gedeckt sein. Das kommt vor Karten- oder Kreditraten.",
  "crisis_jobloss_i2": "Sag deinen Gläubigern Bescheid, bevor eine Zahlung ausfällt. Eine kurze, ehrliche Nachricht, dass sich dein Einkommen geändert hat, öffnet die Tür für eine Pause oder eine niedrigere Rate — und das lässt sich weit leichter regeln, bevor ein Mahnschreiben kommt.",
  "crisis_jobloss_i3": "Finde heraus, worauf du Anspruch hast. Vielleicht gibt es Unterstützung, die du zwischen zwei Jobs beantragen kannst. Die geprüften Stellen in deinem Land sagen dir genau, was für dich gilt.",
  "crisis_jobloss_s1": "Baue das Budget um dein neues, niedrigeres Einkommen herum neu auf — vorerst nur das Nötigste, alles andere pausiert, bis sich die Lage beruhigt.",
  "crisis_jobloss_s2": "Halte jede vorübergehende Vereinbarung mit einem Gläubiger schriftlich fest, damit ein harter Monat nicht still zu einem Zahlungsausfall wird.",
  "crisis_jobloss_s3": "Nimm keine neuen Schulden auf, um alte zu decken. Kredit aufzunehmen, um einen Gläubiger zu bezahlen, gräbt das Loch nur tiefer — die Pläne und Werkzeuge hier funktionieren ohne das.",
  "crisis_illness_t": "Krankheit oder Krankschreibung",
  "crisis_illness_intro": "Wenn deine Gesundheit deine Aufmerksamkeit braucht, machen Geldsorgen alles schwerer. Deine Genesung kommt zuerst — dieser Plan sorgt dafür, dass die Finanzen die Last nicht noch vergrößern.",
  "crisis_illness_i1": "Schütze zuerst das Lebensnotwendige. Wohnen, Essen, Strom und Wasser und alles, was du für deine Versorgung brauchst, kommen vor jeder Zahlung unbesicherter Schulden.",
  "crisis_illness_i2": "Lass die Gläubiger wissen, dass sich deine Situation geändert hat. Du schuldest niemandem deine medizinischen Angaben — nur dass sich dein Einkommen oder deine Kraft geändert hat und dass du um eine vorübergehende Härtefallregelung bittest.",
  "crisis_illness_i3": "Beantrage, worauf du Anspruch hast. Vielleicht gibt es Krankengeld oder Unterstützung, die dir zusteht. Die geprüften Stellen in deinem Land weisen dir den richtigen Weg — und stütze dich für das Gesundheitliche auf medizinische Fachleute.",
  "crisis_illness_s1": "Kürze das Budget auf das Nötigste, solange dein Einkommen geringer ist, und sieh es dir erneut an, wenn sich deine Lage ändert.",
  "crisis_illness_s2": "Halte jede Vereinbarung mit einem Gläubiger schriftlich fest und behalte eine Kopie — eine Sorge weniger im Kopf.",
  "crisis_illness_s3": "Nimm keinen Kredit auf, um bestehende Schulden zu decken. Bitte stattdessen um Zeit; die meisten Gläubiger warten lieber, als dich weiter zu bedrängen.",
  "crisis_sep_t": "Trennung oder Scheidung",
  "crisis_sep_intro": "Ein gemeinsames Leben zu entwirren ist schwer genug ohne den Geldnebel. Geh einen klaren Schritt nach dem anderen — du brauchst nicht diese Woche jede Antwort.",
  "crisis_sep_i1": "Schütze zuerst das Lebensnotwendige, für dich und alle, die von dir abhängen. Wohnen, Essen sowie Strom und Wasser kommen vor unbesicherten Schulden.",
  "crisis_sep_i2": "Wende dich früh an Gläubiger, wenn es gemeinsame Schulden gibt. Frag nach deinen Möglichkeiten und lass dir jede Änderung schriftlich geben. Steht eine Schuld auf beiden Namen, halte fest, was vereinbart wird.",
  "crisis_sep_i3": "Finde heraus, welche Unterstützung du beantragen kannst, wenn sich dein Haushalt ändert. Die geprüften Stellen in deinem Land sagen dir, was gilt — und für die rechtliche Seite gemeinsamer Schulden sind die kostenlose staatliche Schuldnerberatung oder eine qualifizierte Beratung die richtige Anlaufstelle.",
  "crisis_sep_s1": "Baue das Budget um dein eigenes Einkommen und deine Kosten als Einpersonenhaushalt neu auf.",
  "crisis_sep_s2": "Wo möglich, trenne die Finanzen Schritt für Schritt und halte jede Vereinbarung schriftlich fest.",
  "crisis_sep_s3": "Nimm keine neuen Schulden auf, um den Übergang abzufedern. Verlässliche, ehrliche Vereinbarungen schützen dich weit besser als ein Kredit.",
  "crisis_emerg_t": "Ein plötzlicher Notfall",
  "crisis_emerg_intro": "Eine unerwartete Ausgabe oder ein Schock kann den Plan aus der Bahn werfen. Er löscht deinen Fortschritt nicht — er braucht nur eine ruhige Pause und einen klaren nächsten Schritt.",
  "crisis_emerg_i1": "Deck zuerst das wirklich Nötige — Sicherheit, Wohnen, Essen, Strom und Wasser. Ein einmaliger Notfall ist nicht der Moment, eine Kartenzahlung über das Licht im Haus zu stellen.",
  "crisis_emerg_i2": "Wenn der Notfall bedeutet, dass eine Zahlung ausfällt, sag es diesem Gläubiger jetzt und bitte um eine kurze Zahlpause. Eine geplante Pause ist immer besser als ein stiller Ausfall.",
  "crisis_emerg_i3": "Prüfe, ob es Nothilfe gibt, die du nutzen kannst. Die geprüften Stellen in deinem Land können dir Hilfe zeigen, von der du vielleicht nichts weißt.",
  "crisis_emerg_s1": "Wenn der akute Schock bewältigt ist, baue deinen Puffer langsam wieder auf — schon ein kleiner Betrag pro Woche zählt.",
  "crisis_emerg_s2": "Sieh dir das Budget erneut an und passe den Plan für die kommenden Wochen an, nicht gleich fürs ganze Jahr.",
  "crisis_emerg_s3": "Vermeide teure Kredite, um die Lücke zu überbrücken. Eine kurze Vereinbarung mit einem Gläubiger, den du schon hast, kostet dich fast immer weniger.",
  "ci_trend_title": "Dein Puffer, Woche für Woche",
  "ci_trend_empty": "Dein Verlauf entsteht hier. Trag ein paar Wochen ein, und du siehst ihn Gestalt annehmen.",
  "ci_title": "Wie ist diese Woche gelaufen?",
  "ci_lead": "Ein kurzer Check-in — keine Bewertung, keine Serie zu brechen. Nur ein Punkt, wo du diese Woche stehst.",
  "ci_buffer_lbl": "Geld, das dir diese Woche übrig blieb",
  "ci_note_lbl": "Etwas, das du dir zu dieser Woche merken willst? (optional)",
  "ci_note_ph": "z. B. Bank angerufen, niedrigere Rate vereinbart",
