  "sup_lead": "Kostenlose und vertrauenswürdige Angebote in deinem Land. Du musst das nicht allein schaffen.",
  "disclaimer_independent": "debt-free.world ist ein unabhängiger Dienst von Amliv Oy (Finnland). Wir sind keine Behörde und mit keiner verbunden. Die staatlichen Stellen, auf die wir dich verweisen, sind offiziell und immer kostenlos.",
