  "sup_disclaimer": "Das sind unabhängige Organisationen, gelistet, weil sie vertrauenswürdig und kostenlos sind. Debt-Free.World steht mit ihnen in keiner Verbindung und teilt deine Daten nicht mit ihnen.",
