  "dfd_result_k": "Voraussichtliches Schuldenfrei-Datum",
  "dfd_months": "etwa {m} Monate",
  "dfd_extra": "Zusätzliche Zahlung pro Monat",
  "dfd_note": "Mit {monthly}/Monat tilgst du {total} an Schulden. Schon ein bisschen mehr pro Monat holt dieses Datum näher.",
  "dfd_saved": "Das sind etwa {amt} weniger an Zinsen",
  "dfd_saved_floor": "Mindestens {amt} weniger an Zinsen — wahrscheinlich mehr, sobald jeder Satz eingetragen ist",
  "dfd_date_approx": "Ohne Zinsen gerechnet — dein echtes Datum liegt wohl später",
  "dfd_rate_why": "Dieses Datum lässt Zinsen aus, weil noch kein Zinssatz gespeichert ist. Meist sind es die Zinsen, die etwas mehr Zahlung so wirksam machen — trag deinen Satz ein, um das echte Datum zu sehen und wie viel Zinsen jede Extrazahlung tilgt.",
  "dfd_rate_partial": "Für manche Schulden ist kein Zinssatz gespeichert, daher zählen sie hier als 0 %. Die echten Zahlen sind besser als angezeigt — trag die fehlenden Sätze ein, um sie zu sehen.",
  "dfd_rate_cta": "Plan bearbeiten",
  "dfd_stabilise": "Deine Kosten übersteigen derzeit deine Einnahmen, daher gibt es noch kein Rückzahlungsdatum. Das erste Ziel ist Luft zum Atmen — beginn mit dem Krisenbudget-Planer.",
  "dfd_buffer_first": "Bevor Extrageld in Schulden fließt: ein Polster von {gap} verhindert, dass eine Überraschungsrechnung zu neuer Schuld wird.",
  "strat_snow": "Schneeball",
  "strat_aval": "Lawine",
  "strat_first": "Diese zuerst tilgen",
  "strat_snow_note": "Kleinster Saldo zuerst. Schnelle Erfolge bauen Schwung auf — stark, wenn der Anfang das Schwerste ist.",
  "strat_aval_note": "Höchster Zins zuerst. Auf Dauer am günstigsten — stark, wenn teure Schulden dich auslaugen.",
  "strat_empty": "Füge deine Schulden im Onboarding hinzu, um die Strategien nebeneinander zu vergleichen.",
  "strat_unknown": "Zins unbekannt",
  "strat_snow_why": "Für dich beginnt das mit {target} — deinem kleinsten Saldo.",
  "strat_aval_why": "Für dich beginnt das mit deiner {target}-Schuld — dem höchsten Zinssatz, den du trägst.",
  "tool_intro_dfd": "Das macht aus deinen echten Zahlen ein Datum — den Tag, an dem deine Schulden getilgt sind. Dann zeigt es, wie viel früher schon eine kleine Extrazahlung ihn bringen würde.",
  "tool_intro_strat": "Es gibt nicht den einen 'richtigen' Weg, Schulden loszuwerden — es gibt ein paar bewährte. Dies zeigt dir zwei nebeneinander und welcher zu deiner Situation passt. Kein Fachjargon, nur deine Zahlen.",
  "tool_intro_budget": "Bevor etwas in Schulden fließt, kommt dein Leben zuerst. Dies legt dar, was nötig ist, und zeigt dir dann ehrlich, was übrig bleibt für das, was du schuldest.",
  "tool_intro_income": "Du musst dein Einkommen nicht verdoppeln, um deinen Zeitplan zu ändern. Dies zeigt, wie viel früher deine Schulden getilgt wären für jedes bisschen, das du zusätzlich hereinholst.",
  "tool_intro_collect": "Nicht jede Schuld ist gleich dringend, und alle gleich zu behandeln ist zermürbend. Dies sortiert deine danach, was jetzt wirklich Aufmerksamkeit braucht — damit du durchatmen kannst.",
  "tool_intro_legal": "Du hast mehr Rechte, als man dir wahrscheinlich gesagt hat. Dies legt die Schutzrechte dort, wo du lebst, in klarer Sprache dar, damit niemand dich mit Unwahrem unter Druck setzen kann.",
  "nav_g_debtfree_sub": "Alles, was du brauchst, um deine Situation klar zu sehen und deinen Weg hinaus zu planen.",
  "nav_g_tools_sub": "Sechs Rechner. Jeder beantwortet eine echte Frage zu deinem Geld.",
  "nav_g_learn_sub": "Kurze, ehrliche Texte — kein Füllwerk, nichts zu kaufen.",
  "nav_g_recovery_sub": "Wenn du bereit bist, tiefere Werkzeuge, um dich zu wehren und neu aufzubauen.",
  "strat_cmp_title": "Deine zwei Wege, nebeneinander",
