  "strat_cmp_first": "Erste Schuld weg in {m} Monaten",
  "strat_cmp_verdict_aval": "Mit deinen Zahlen spart dir Lawine etwa {save} und tilgt alles rund {months} Monate früher. Wenn es dich antreibt, die Gesamtkosten sinken zu sehen, beginne hier.",
  "strat_cmp_verdict_snow": "Mit deinen Zahlen enden diese beiden dicht beieinander. Schneeball tilgt deine erste Schuld in {first} Monaten — dieser frühe Erfolg kostet insgesamt nur etwa {extra} mehr. Wenn dich der Schwung antreibt, beginne hier.",
  "strat_cmp_approx": "Richtungsweisende Schätzung: Sie nimmt an, dass jeder freie Rest deines Budgets der Reihe nach in deine Schulden fließt. Deine echte Zahlungsreihenfolge und etwaige Mindestzahlungen können sie verschieben.",
  "strat_cmp_needsurplus": "Sobald jeden Monat Geld übrig bleibt, zeigt dies beide Wege und welcher dich früher frei macht. Bis dahin ist die Reihenfolge unten trotzdem der clevere Anfang.",
  "budget_in": "Geld rein",
