  "budget_shortfall": "Monatliche Unterdeckung",
  "budget_note": "In einer Krise kommt das Nötigste zuerst — Wohnen, Essen, Strom, Verkehr. Was übrig bleibt, ist deine Rückzahlungskraft. Ist sie negativ, ist das kein Versagen: Es ist das Signal, die kostenlose Hilfe in deinem Plan zu nutzen.",
