  "h_hero_eyebrow": "90-DAY PLAN · Immer kostenlos",
  "h_hero_h1": "Du verdienst es, genau zu sehen, wo du mit deinen Schulden stehst — eine Klarheit, die dir sonst niemand <span class=\"g\">kostenlos</span> gibt.",
  "h_promise": "Das hier ist kein Plan von der Stange. Er ist auf deine Situation und deine genauen Zahlen gebaut — und niemand hier urteilt darüber, wie du hierhergekommen bist.",
  "h_cta_build": "Meinen 90-Day Plan erstellen",
