  "h_trust_4_l": "Länder abgedeckt.",
  "h_eco_label": "Der ganze Weg",
  "h_eco_title": "Echte finanzielle Erholung ist mehr als ein einzelner Plan.",
  "h_eco_q1": "Es ist ein Weg — vom Verstehen, wo du heute stehst, über die aktive Erholung, bis hin dazu, irgendwann mehr zu verdienen und etwas Beständiges aufzubauen.",
  "h_eco_q2": "<strong>Du wirst nie gebeten, die ganze Treppe zu sehen.</strong> Debt-Free.World geht den Weg mit dir, eine Stufe nach der anderen — beginnend mit der, die nichts kostet.",
