  "mf_dl_h": "Behold planen din",
  "mf_dl_note": "Én fil med planen din, datoen du laget den, og de gratis tjenestene i landet ditt. Den åpnes på hvilken som helst enhet, fungerer uten internett og tilhører deg.",
