  "mf_x_created": "Opprettet",
  "mf_x_plan_h": "Planen din",
  "mf_x_repeat": "Vi erstatter ikke disse tjenestene. Vi er laget for å brukes ved siden av dem.",
  "mf_x_del90": "På dag 90 sletter vi planen din, svarene dine, dokumentene dine og alt personlig i dem. Ingenting av ditt blir igjen i tjenesten vår. Planen din er din og fungerer uten oss.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Kriseplaner",
  "crisis_title": "Når livet plutselig endrer seg",
  "crisis_lead": "En plutselig endring visker ikke ut fremgangen du har gjort. Velg det som ligger nærmest situasjonen din — hver plan starter med de én eller to tingene som betyr mest i dag, og så hvordan du får stø grunn under føttene.",
  "crisis_immediate": "Akkurat nå",
  "crisis_stabilise": "Få stø grunn",
  "crisis_act_letter": "Skriv et brevutkast til kreditoren din",
  "crisis_act_support": "Finn verifisert hjelp der du er",
  "crisis_act_budget": "Åpne budsjettplanleggeren",
  "crisis_safe_note": "Dette er generell veiledning, ikke juridisk eller medisinsk rådgivning. I alt som gjelder akkurat din situasjon, len deg på de gratis tjenestene under Støtte og, når det betyr noe, en kvalifisert fagperson.",
  "crisis_jobloss_t": "Jobbtap",
  "crisis_jobloss_intro": "Å miste en inntekt er skremmende, men du har mer handlingsrom enn det føles akkurat nå. Ingenting må løses i dag — bare påbegynnes.",
  "crisis_jobloss_i1": "Beskytt det nødvendige først. Før all usikret gjeld, sørg for at bolig, mat, strøm og vann og transporten du trenger for å finne jobb er dekket. Dette går foran kort- og lånebetalinger.",
  "crisis_jobloss_i2": "Si fra til kreditorene dine før en betaling uteblir. En kort, ærlig beskjed om at inntekten din har endret seg, åpner døren for en pause eller en lavere betaling — og det er mye lettere å ordne før et purrebrev kommer.",
  "crisis_jobloss_i3": "Finn ut hva du har rett til. Det kan finnes støtte du kan søke mens du er mellom jobber. De verifiserte tjenestene i landet ditt kan si nøyaktig hva som gjelder for deg.",
  "crisis_jobloss_s1": "Bygg opp budsjettet på nytt rundt din nye, lavere inntekt — bare det nødvendige nå, alt annet på pause til ting roer seg.",
  "crisis_jobloss_s2": "Få enhver midlertidig avtale med en kreditor skriftlig, så en tung måned ikke stille blir til et betalingsmislighold.",
  "crisis_jobloss_s3": "Ikke ta opp ny gjeld for å dekke gammel gjeld. Å låne for å betale en långiver graver bare hullet dypere — planene og verktøyene her er laget for å fungere uten det.",
  "crisis_illness_t": "Sykdom eller sykemelding",
  "crisis_illness_intro": "Når helsen trenger oppmerksomheten din, gjør pengebekymringer alt tyngre. Bedringen din kommer først — denne planen sørger for at økonomien ikke legger mer til børen.",
  "crisis_illness_i1": "Beskytt det nødvendige først. Bolig, mat, strøm og vann og alt du trenger for pleien din, går foran enhver betaling av usikret gjeld.",
  "crisis_illness_i2": "La kreditorene vite at situasjonen din har endret seg. Du skylder ingen helseopplysningene dine — bare at inntekten eller kapasiteten din har endret seg, og at du ber om en midlertidig ordning ved betalingsvansker.",
  "crisis_illness_i3": "Søk det du har rett til. Det kan finnes sykepenger eller støtte du kvalifiserer for. De verifiserte tjenestene i landet ditt viser deg til rett sted — og len deg på helsepersonell for helsedelen.",
  "crisis_illness_s1": "Skjær budsjettet ned til det nødvendige mens inntekten er lavere, og se på det igjen når situasjonen din endrer seg.",
  "crisis_illness_s2": "Få enhver avtale med en kreditor skriftlig og ta vare på en kopi — én ting mindre å holde i hodet.",
  "crisis_illness_s3": "Ikke lån for å dekke eksisterende gjeld. Be om tid i stedet; de fleste kreditorer venter heller enn å presse deg mer.",
  "crisis_sep_t": "Samlivsbrudd eller skilsmisse",
  "crisis_sep_intro": "Å nøste opp et delt liv er vanskelig nok uten pengetåka. Ta ett tydelig steg av gangen — du trenger ikke alle svarene denne uka.",
  "crisis_sep_i1": "Beskytt det nødvendige først, for deg og alle som er avhengige av deg. Bolig, mat og strøm og vann går foran usikret gjeld.",
  "crisis_sep_i2": "Kontakt kreditorer tidlig om all felles gjeld. Spør hvilke muligheter du har, og få hver endring skriftlig. Når en gjeld står i begge navn, noter det som avtales.",
  "crisis_sep_i3": "Finn ut hvilken støtte du kan søke når husholdningen din endrer seg. De verifiserte tjenestene i landet ditt kan si hva som gjelder — og for den juridiske siden av felles gjeld er gratis nasjonal gjeldshjelp eller en kvalifisert rådgiver rett sted å gå.",
  "crisis_sep_s1": "Bygg opp budsjettet på nytt rundt din egen inntekt og dine kostnader som en enpersonshusholdning.",
  "crisis_sep_s2": "Der du kan, skill økonomien steg for steg, og hold skriftlige notater om hver avtale.",
  "crisis_sep_s3": "Ikke ta opp ny gjeld for å jevne ut overgangen. Stø, ærlige avtaler beskytter deg langt bedre enn å låne.",
  "crisis_emerg_t": "En plutselig krise",
  "crisis_emerg_intro": "En uventet kostnad eller et sjokk kan slå planen ut av kurs. Det visker ikke ut fremgangen du har gjort — det trenger bare en rolig pause og ett tydelig neste steg.",
  "crisis_emerg_i1": "Dekk det virkelig nødvendige først — trygghet, bolig, mat, strøm og vann. En engangskrise er ikke tiden for å sette en kortbetaling foran å holde lyset på.",
  "crisis_emerg_i2": "Hvis krisen gjør at en betaling uteblir, si det til den kreditoren nå og be om en kort betalingspause. En planlagt pause er alltid bedre enn en stille uteblivelse.",
  "crisis_emerg_i3": "Sjekk om det finnes krisestøtte du kan bruke. De verifiserte tjenestene i landet ditt kan vise deg hjelp du kanskje ikke visste fantes.",
  "crisis_emerg_s1": "Når det akutte sjokket er håndtert, bygg opp bufferen din sakte — selv en liten sum hver uke teller.",
  "crisis_emerg_s2": "Se over budsjettet på nytt og juster planen for de kommende ukene, ikke hele året på én gang.",
  "crisis_emerg_s3": "Unngå dyre lån for å tette gapet. En kort avtale med en kreditor du allerede har, koster deg nesten alltid mindre.",
  "ci_trend_title": "Bufferen din, uke for uke",
  "ci_trend_empty": "Trenden din bygges opp her. Logg et par uker, så ser du den ta form.",
