  "tool_intro_dfd": "Dette gjør de virkelige tallene dine om til én dato — dagen gjelden din er betalt. Så viser det hvor mye tidligere selv en liten ekstra betaling ville føre den.",
  "tool_intro_strat": "Det finnes ikke én 'riktig' måte å bli kvitt gjeld på — det finnes noen utprøvde. Dette viser deg to, side om side, og hvilken som passer situasjonen din. Ingen sjargong, bare tallene dine.",
  "tool_intro_budget": "Før noe går til gjeld, kommer livet ditt først. Dette setter opp hva som er nødvendig, og viser deg så ærlig hva som er igjen å legge på det du skylder.",
