  "h_proof_title": "Med deres egne ord — snart",
  "h_proof_body": "Vi er nye, og vi viser deg heller ingenting enn omtaler vi har skrevet selv. Når ekte mennesker forteller hvordan det gikk for dem, kommer ordene deres til å stå her — med bare så mye av navnet sitt som de selv velger å gi. Inntil da er planen vi bygger for deg det eneste beviset vi tilbyr.",
  "h_faq_label": "Vanlige spørsmål",
  "h_faq_q1": "Er den virkelig gratis?",
  "h_faq_a1": "Ja. 90-dagers gjeldsplanen og alle 90-Day Plan-verktøyene er gratis — ingen betalingskort, ingen skjulte kostnader, ingen tidsgrense. 90-Day Companion (19€, engangsbetaling) er en valgfri oppgradering.",
