  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Kriseplaner",
  "crisis_title": "Når livet pludselig ændrer sig",
  "crisis_lead": "En pludselig ændring visker ikke fremskridtet ud, som du har gjort. Vælg det, der ligger tættest på din situation — hver plan starter med de en eller to ting, der betyder mest i dag, og så hvordan du får fast grund under fødderne.",
  "crisis_immediate": "Lige nu",
  "crisis_stabilise": "Få fast grund under fødderne",
  "crisis_act_letter": "Skriv et brevudkast til din kreditor",
  "crisis_act_support": "Find verificeret hjælp, hvor du er",
  "crisis_act_budget": "Åbn budgetplanlæggeren",
  "crisis_safe_note": "Dette er generel vejledning, ikke juridisk eller medicinsk rådgivning. I alt, der handler om lige netop din situation, læn dig op ad de gratis tjenester under Støtte og, hvor det er vigtigt, en kvalificeret fagperson.",
  "crisis_jobloss_t": "Jobtab",
  "crisis_jobloss_intro": "At miste en indkomst er skræmmende, men du har mere spillerum, end det føles lige nu. Intet skal løses i dag — kun begyndes.",
  "crisis_jobloss_i1": "Beskyt det nødvendige først. Før al usikret gæld, sørg for at bolig, mad, el og vand og den transport, du har brug for at finde arbejde, er dækket. Det går forud for kort- og lånebetalinger.",
  "crisis_jobloss_i2": "Sig det til dine kreditorer, før en betaling udebliver. En kort, ærlig besked om, at din indkomst har ændret sig, åbner døren for en pause eller en lavere betaling — og det er langt lettere at ordne, før et rykkerbrev lander.",
  "crisis_jobloss_i3": "Find ud af, hvad du har ret til. Der kan være støtte, du kan søge, mens du er mellem job. De verificerede tjenester i dit land kan sige præcis, hvad der gælder for dig.",
  "crisis_jobloss_s1": "Byg budgettet op igen omkring din nye, lavere indkomst — kun det nødvendige nu, alt andet på pause, til tingene falder til ro.",
  "crisis_jobloss_s2": "Få enhver midlertidig aftale med en kreditor skriftligt, så en hård måned ikke stille bliver til misligholdelse.",
  "crisis_jobloss_s3": "Tag ikke ny gæld for at dække gammel gæld. At låne for at betale en långiver graver bare hullet dybere — planerne og værktøjerne her er bygget til at virke uden det.",
  "crisis_illness_t": "Sygdom eller sygemelding",
  "crisis_illness_intro": "Når helbredet har brug for din opmærksomhed, gør pengebekymringer alt tungere. Din bedring kommer først — denne plan sørger for, at økonomien ikke lægger mere til byrden.",
  "crisis_illness_i1": "Beskyt det nødvendige først. Bolig, mad, el og vand og alt, hvad du har brug for til din pleje, går forud for enhver betaling af usikret gæld.",
  "crisis_illness_i2": "Lad kreditorerne vide, at din situation har ændret sig. Du skylder ingen dine helbredsoplysninger — kun at din indkomst eller formåen har ændret sig, og at du beder om en midlertidig ordning.",
  "crisis_illness_i3": "Søg det, du har ret til. Der kan være sygedagpenge eller støtte, du er berettiget til. De verificerede tjenester i dit land peger dig i den rigtige retning — og læn dig op ad sundhedspersonale for helbredsdelen.",
  "crisis_illness_s1": "Skær budgettet ned til det nødvendige, mens indkomsten er lavere, og se på det igen, når din situation ændrer sig.",
  "crisis_illness_s2": "Få enhver aftale med en kreditor skriftligt og gem en kopi — én ting mindre at holde styr på i hovedet.",
  "crisis_illness_s3": "Lån ikke for at dække eksisterende gæld. Bed om tid i stedet; de fleste kreditorer venter hellere end at presse dig yderligere.",
  "crisis_sep_t": "Separation eller skilsmisse",
  "crisis_sep_intro": "At rede et delt liv ud er svært nok uden pengetågen. Tag ét tydeligt skridt ad gangen — du behøver ikke alle svar i denne uge.",
  "crisis_sep_i1": "Beskyt det nødvendige først, for dig og alle, der er afhængige af dig. Bolig, mad og el og vand går forud for usikret gæld.",
  "crisis_sep_i2": "Kontakt kreditorer tidligt om al fælles gæld. Spørg, hvilke muligheder du har, og få hver ændring skriftligt. Når en gæld står i begge navne, så notér det, der aftales.",
  "crisis_sep_i3": "Find ud af, hvilken støtte du kan søge, når din husstand ændrer sig. De verificerede tjenester i dit land kan sige, hvad der gælder — og for den juridiske side af fælles gæld er gratis national gældsrådgivning eller en kvalificeret rådgiver det rette sted.",
  "crisis_sep_s1": "Byg budgettet op igen omkring din egen indkomst og dine udgifter som en enlig husstand.",
  "crisis_sep_s2": "Hvor du kan, adskil økonomien skridt for skridt, og hold skriftlige notater om hver aftale.",
  "crisis_sep_s3": "Tag ikke ny gæld for at udjævne overgangen. Stabile, ærlige aftaler beskytter dig langt bedre end at låne.",
  "crisis_emerg_t": "En pludselig nødsituation",
  "crisis_emerg_intro": "En uventet udgift eller et chok kan slå planen ud af kurs. Det visker ikke fremskridtet ud, du har gjort — det kræver bare en rolig pause og ét tydeligt næste skridt.",
  "crisis_emerg_i1": "Dæk det virkelig nødvendige først — tryghed, bolig, mad, el og vand. En engangskrise er ikke tidspunktet til at sætte en kortbetaling over at holde lyset tændt.",
  "crisis_emerg_i2": "Hvis krisen betyder, at en betaling udebliver, så sig det til den kreditor nu og bed om en kort betalingspause. En planlagt pause er altid bedre end en tavs udeblivelse.",
  "crisis_emerg_i3": "Tjek, om der er krisehjælp, du kan trække på. De verificerede tjenester i dit land kan vise dig hjælp, du måske ikke vidste fandtes.",
  "crisis_emerg_s1": "Når det akutte chok er håndteret, så byg din buffer op langsomt — selv et lille beløb hver uge tæller.",
  "crisis_emerg_s2": "Se budgettet efter igen og justér planen for de kommende uger, ikke hele året på én gang.",
  "crisis_emerg_s3": "Undgå dyre lån for at bygge bro over hullet. En kort aftale med en kreditor, du allerede har, koster dig næsten altid mindre.",
  "ci_trend_title": "Din buffer, uge for uge",
  "ci_trend_empty": "Din trend bygges op her. Log et par uger, så ser du den tage form.",
