  "tool_intro_dfd": "Dette gør dine virkelige tal til én dato — dagen, din gæld er betalt. Så viser det, hvor meget tidligere selv en lille ekstra betaling ville flytte den.",
  "tool_intro_strat": "Der findes ikke én 'rigtig' måde at betale gæld af på — der er nogle gennemprøvede. Dette viser dig to, side om side, og hvilken der passer til din situation. Ingen jargon, bare dine tal.",
  "tool_intro_budget": "Før noget går til gæld, kommer dit liv først. Dette opstiller, hvad der er nødvendigt, og viser dig så ærligt, hvad der er tilbage at lægge på det, du skylder.",
  "tool_intro_income": "Du behøver ikke fordoble din indkomst for at ændre din tidslinje. Dette viser, hvor meget tidligere din gæld vil være betalt for hver ekstra krone, du kan skaffe.",
  "tool_intro_collect": "Ikke al gæld er lige presserende, og at behandle det hele ens er udmattende. Dette sorterer dine efter, hvad der virkelig kræver opmærksomhed nu — så du kan trække vejret.",
  "tool_intro_legal": "Du har flere rettigheder, end du sikkert har fået at vide. Dette opstiller beskyttelsen, der hvor du bor, i et enkelt sprog, så ingen kan presse dig med noget, der ikke er sandt.",
