  "strat_cmp_verdict_snow": "Med dine tal ender de to tæt på hinanden. Snebold betaler din første gæld af på {first} måneder — den tidlige sejr koster kun omkring {extra} mere i alt. Hvis det er fremdriften, der holder dig i gang, så start her.",
  "strat_cmp_approx": "Retningsgivende skøn: det antager, at hver krone, du har til overs i budgettet, går til din gæld i rækkefølge. Din virkelige betalingsrækkefølge og eventuelle minimumsbetalinger kan ændre det.",
