  "mf_dl_h": "Bewaar je plan",
  "mf_dl_note": "Één bestand met je plan, de datum waarop je het maakte, en de gratis diensten in jouw land. Het opent op elk apparaat, werkt zonder internet en is van jou.",
  "mf_dl_btn": "Mijn plan downloaden",
