  "mf_dl_err": "We konden je bestand nu niet maken. Probeer het zo meteen opnieuw — er gaat niets verloren.",
  "mf_x_created": "Gemaakt op",
  "mf_x_plan_h": "Je plan",
  "mf_x_repeat": "Wij vervangen deze diensten niet. We zijn gemaakt om naast hen te worden gebruikt.",
  "mf_x_del90": "Op dag 90 verwijderen we je plan, je antwoorden, je documenten en alles persoonlijks daarin. In onze dienst blijft niets van jou achter. Je plan is van jou en werkt zonder ons.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisisplannen",
  "crisis_title": "Als het leven plotseling verandert",
  "crisis_lead": "Een plotselinge verandering wist de vooruitgang die je hebt geboekt niet uit. Kies wat het dichtst bij jouw situatie ligt — elk plan begint met de een of twee dingen die vandaag het zwaarst wegen, en daarna hoe je weer vaste grond onder je voeten krijgt.",
  "crisis_immediate": "Nu meteen",
  "crisis_stabilise": "Weer vaste grond",
  "crisis_act_letter": "Stel een brief op aan je schuldeiser",
  "crisis_act_support": "Vind geverifieerde hulp waar je bent",
  "crisis_act_budget": "Open de budgetplanner",
  "crisis_safe_note": "Dit is algemene informatie, geen juridisch of medisch advies. Voor alles wat specifiek jouw situatie betreft, leun op de gratis diensten onder Hulp en, waar het ertoe doet, op een gekwalificeerde professional.",
  "crisis_jobloss_t": "Baanverlies",
  "crisis_jobloss_intro": "Je inkomen verliezen is beangstigend, maar je hebt meer speelruimte dan het nu voelt. Niets hoeft vandaag opgelost te worden — alleen begonnen.",
  "crisis_jobloss_i1": "Bescherm eerst het noodzakelijke. Vóór elke schuld zonder onderpand: zorg dat wonen, eten, energie en water en het vervoer dat je nodig hebt om werk te vinden gedekt zijn. Dat gaat vóór kaart- of leningbetalingen.",
  "crisis_jobloss_i2": "Laat je schuldeisers het weten vóórdat je een betaling mist. Een kort, eerlijk bericht dat je inkomen is veranderd opent de deur naar een pauze of een lagere betaling — en dat regel je veel makkelijker vóór er een aanmaning komt.",
  "crisis_jobloss_i3": "Zoek uit waar je recht op hebt. Er kan steun zijn die je kunt aanvragen terwijl je tussen twee banen zit. De geverifieerde diensten in jouw land kunnen je precies zeggen wat voor jou geldt.",
  "crisis_jobloss_s1": "Bouw de begroting opnieuw op rond je nieuwe, lagere inkomen — voorlopig alleen het noodzakelijke, de rest op pauze tot het rustiger wordt.",
  "crisis_jobloss_s2": "Leg elke tijdelijke afspraak met een schuldeiser schriftelijk vast, zodat een zware maand niet stilletjes een betalingsachterstand wordt.",
  "crisis_jobloss_s3": "Neem geen nieuwe schuld om oude schuld te dekken. Lenen om een geldverstrekker te betalen graaft het gat alleen dieper — de plannen en tools hier werken zonder dat.",
  "crisis_illness_t": "Ziekte of ziekteverlof",
  "crisis_illness_intro": "Als je gezondheid je aandacht vraagt, maken geldzorgen alles zwaarder. Je herstel komt eerst — dit plan zorgt dat de financiën de last niet groter maken.",
  "crisis_illness_i1": "Bescherm eerst het noodzakelijke. Wonen, eten, energie en water en alles wat je voor je zorg nodig hebt, gaan vóór elke betaling van schuld zonder onderpand.",
  "crisis_illness_i2": "Laat schuldeisers weten dat je situatie is veranderd. Je bent niemand je medische gegevens verschuldigd — alleen dat je inkomen of draagkracht is veranderd en dat je om een tijdelijke regeling bij betaalproblemen vraagt.",
  "crisis_illness_i3": "Vraag aan waar je recht op hebt. Er kan ziektegeld of steun zijn waarvoor je in aanmerking komt. De geverifieerde diensten in jouw land wijzen je de goede kant op — en leun voor het gezondheidsdeel op medische professionals.",
  "crisis_illness_s1": "Snoei de begroting terug tot het noodzakelijke zolang je inkomen lager is, en kijk er opnieuw naar als je situatie verandert.",
  "crisis_illness_s2": "Leg elke afspraak met een schuldeiser schriftelijk vast en bewaar een kopie — één ding minder om te onthouden.",
  "crisis_illness_s3": "Leen niet om bestaande schuld te dekken. Vraag in plaats daarvan om tijd; de meeste schuldeisers wachten liever dan je verder te drijven.",
  "crisis_sep_t": "Scheiding of echtscheiding",
  "crisis_sep_intro": "Een gedeeld leven ontwarren is al zwaar genoeg zonder de geldmist. Neem het één heldere stap tegelijk — je hoeft deze week niet elk antwoord te hebben.",
  "crisis_sep_i1": "Bescherm eerst het noodzakelijke, voor jou en iedereen die van je afhankelijk is. Wonen, eten en energie en water gaan vóór schuld zonder onderpand.",
  "crisis_sep_i2": "Neem vroeg contact op met schuldeisers over gezamenlijke schulden. Vraag welke opties je hebt en laat elke wijziging schriftelijk vastleggen. Staat een schuld op beide namen, houd dan bij wat is afgesproken.",
  "crisis_sep_i3": "Zoek uit welke steun je kunt aanvragen als je huishouden verandert. De geverifieerde diensten in jouw land kunnen je zeggen wat geldt — en voor de juridische kant van gezamenlijke schulden is gratis nationale schuldhulp of een gekwalificeerde adviseur het juiste adres.",
  "crisis_sep_s1": "Bouw de begroting opnieuw op rond je eigen inkomen en kosten als eenpersoonshuishouden.",
  "crisis_sep_s2": "Waar het kan, scheid de financiën stap voor stap en houd van elke afspraak schriftelijk vast.",
  "crisis_sep_s3": "Neem geen nieuwe schuld om de overgang te verzachten. Stabiele, eerlijke afspraken beschermen je veel beter dan lenen.",
  "crisis_emerg_t": "Een plotselinge noodsituatie",
  "crisis_emerg_intro": "Een onverwachte kost of schok kan het plan uit koers slaan. Het wist je vooruitgang niet uit — het vraagt alleen een rustige pauze en één duidelijke volgende stap.",
  "crisis_emerg_i1": "Dek eerst het echt noodzakelijke — veiligheid, wonen, eten, energie en water. Een eenmalige noodsituatie is niet het moment om een kaartbetaling boven het licht aan houden te zetten.",
  "crisis_emerg_i2": "Als de noodsituatie betekent dat je een betaling mist, zeg dat dan nu tegen die schuldeiser en vraag om een korte betaalpauze. Een geplande pauze is altijd beter dan stilzwijgend missen.",
  "crisis_emerg_i3": "Kijk of er noodhulp is waarop je kunt terugvallen. De geverifieerde diensten in jouw land kunnen je wijzen op hulp waarvan je misschien niet wist dat die bestond.",
  "crisis_emerg_s1": "Als de acute schok is opgevangen, bouw je buffer dan langzaam op — zelfs een klein bedrag per week telt.",
  "crisis_emerg_s2": "Bekijk de begroting opnieuw en pas het plan aan voor de komende weken, niet meteen voor het hele jaar.",
  "crisis_emerg_s3": "Vermijd dure leningen om het gat te overbruggen. Een korte afspraak met een schuldeiser die je al hebt, kost je bijna altijd minder.",
  "ci_trend_title": "Je buffer, week voor week",
  "ci_trend_empty": "Je trend bouwt zich hier op. Leg een paar weken vast en je ziet hem vorm krijgen.",
