  "dfd_saved_floor": "Minstens {amt} minder aan rente — waarschijnlijk meer als elke rente is ingevuld",
  "dfd_date_approx": "Zonder rente gerekend — je echte datum ligt waarschijnlijk later",
  "dfd_rate_why": "Deze datum laat rente buiten beschouwing, omdat er nog geen rente is opgeslagen. Meestal is het de rente die een beetje extra betalen zo krachtig maakt — vul je rente in om de echte datum te zien en hoeveel rente elke extra betaling wegwerkt.",
  "dfd_rate_partial": "Voor sommige schulden is geen rente opgeslagen, dus tellen ze hier als 0 %. De echte cijfers zijn beter dan getoond — vul de ontbrekende rentes in om ze te zien.",
  "dfd_rate_cta": "Je plan bewerken",
  "dfd_stabilise": "Je kosten zijn op dit moment hoger dan je inkomsten, dus er is nog geen aflossingsdatum. Het eerste doel is ademruimte — begin met de Crisisbudgetplanner.",
