  "strat_aval": "Lawine",
  "strat_first": "Los deze eerst af",
  "strat_snow_note": "Kleinste saldo eerst. Snelle successen geven vaart — krachtig wanneer beginnen het moeilijkst is.",
  "strat_aval_note": "Hoogste rente eerst. Op termijn het goedkoopst — krachtig wanneer dure schuld je uitput.",
  "strat_empty": "Voeg je schulden toe tijdens de onboarding om de strategieën naast elkaar te vergelijken.",
