  "strat_snow_why": "Voor jou begint dat bij {target} — je kleinste saldo.",
  "strat_aval_why": "Voor jou begint dat bij je {target}-schuld — de hoogste rente die je draagt.",
  "tool_intro_dfd": "Dit maakt van je echte cijfers één datum — de dag dat je schuld is afbetaald. Daarna laat het zien hoeveel eerder zelfs een kleine extra betaling die zou brengen.",
  "tool_intro_strat": "Er is niet één 'juiste' manier om schuld af te lossen — er zijn er een paar beproefde. Dit toont je er twee, naast elkaar, en welke bij jouw situatie past. Geen jargon, alleen je cijfers.",
  "tool_intro_budget": "Voordat er iets naar schuld gaat, komt jouw leven eerst. Dit zet uiteen wat noodzakelijk is en laat je dan eerlijk zien wat er overblijft voor wat je schuldig bent.",
  "tool_intro_income": "Je hoeft je inkomen niet te verdubbelen om je tijdlijn te veranderen. Dit laat zien hoeveel eerder je schuld afbetaald zou zijn voor elk beetje extra dat je binnenbrengt.",
  "tool_intro_collect": "Niet elke schuld is even dringend, en ze allemaal hetzelfde behandelen is uitputtend. Dit sorteert die van jou op wat nu echt aandacht nodig heeft — zodat je kunt ademen.",
  "tool_intro_legal": "Je hebt meer rechten dan je waarschijnlijk is verteld. Dit zet de bescherming waar je woont in gewone taal uiteen, zodat niemand je onder druk kan zetten met dingen die niet waar zijn.",
  "nav_g_debtfree_sub": "Alles wat je nodig hebt om je situatie helder te zien en je weg naar buiten te plannen.",
  "nav_g_tools_sub": "Zes rekenhulpen. Elk beantwoordt één echte vraag over je geld.",
  "nav_g_learn_sub": "Korte, eerlijke teksten — geen opvulling, niets te koop.",
  "nav_g_recovery_sub": "Als je er klaar voor bent, diepere tools om terug te vechten en op te bouwen.",
  "strat_cmp_title": "Je twee paden, naast elkaar",
