  "strat_cmp_verdict_snow": "Met jouw cijfers eindigen deze twee dicht bij elkaar. Sneeuwbal lost je eerste schuld af in {first} maanden — die vroege winst kost in totaal maar zo'n {extra} meer. Als vaart je op gang houdt, begin hier.",
  "strat_cmp_approx": "Indicatieve schatting: die gaat ervan uit dat elk restje van je budget op volgorde naar je schulden gaat. Je echte betaalvolgorde en eventuele minimumbetalingen kunnen die verschuiven.",
  "strat_cmp_needsurplus": "Zodra er elke maand geld overblijft, laat dit beide paden zien en welke je eerder vrij maakt. Voorlopig is de volgorde hieronder toch de slimme plek om te beginnen.",
