  "mf_dl_h": "Guarda tu plan",
  "mf_dl_note": "Un solo archivo con tu plan, la fecha en que lo hiciste y los servicios gratuitos de tu país. Se abre en cualquier dispositivo, funciona sin internet y es tuyo.",
  "mf_dl_btn": "Descargar mi plan",
