  "mf_x_created": "Creado el",
  "mf_x_plan_h": "Tu plan",
  "mf_x_repeat": "No sustituimos estos servicios. Estamos hechos para usarse junto a ellos.",
  "mf_x_del90": "El día 90 eliminamos tu plan, tus respuestas, tus documentos y todo lo personal que contienen. Nada tuyo se queda en nuestro servicio. Tu plan es tuyo y funciona sin nosotros.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Planes de crisis",
  "crisis_title": "Cuando la vida cambia de golpe",
  "crisis_lead": "Un cambio repentino no borra lo que ya has avanzado. Elige lo más cercano a tu situación — cada plan empieza por la una o dos cosas que más importan hoy, y luego por cómo volver a pisar terreno firme.",
  "crisis_immediate": "Ahora mismo",
  "crisis_stabilise": "Recupera terreno firme",
  "crisis_act_letter": "Redacta una carta a tu acreedor",
  "crisis_act_support": "Encuentra ayuda verificada cerca de ti",
  "crisis_act_budget": "Abre el planificador de presupuesto",
  "crisis_safe_note": "Esto es orientación general, no asesoramiento legal ni médico. Para lo que sea propio de tu situación, apóyate en los servicios gratuitos de Apoyo y, cuando importe, en un profesional cualificado.",
  "crisis_jobloss_t": "Pérdida de empleo",
  "crisis_jobloss_intro": "Perder un ingreso asusta, pero tienes más margen de movimiento del que parece ahora mismo. Nada tiene que resolverse hoy — solo empezar.",
  "crisis_jobloss_i1": "Protege primero lo esencial. Antes que cualquier deuda sin garantía, asegúrate de tener cubiertos la vivienda, la comida, los suministros y el transporte que necesitas para buscar trabajo. Van por delante de los pagos de tarjetas o préstamos.",
  "crisis_jobloss_i2": "Avisa a tus acreedores antes de que se te pase un pago. Un mensaje breve y honesto de que tus ingresos han cambiado abre la puerta a una pausa o a una cuota menor — y es mucho más fácil de gestionar antes de que llegue una carta de impago.",
  "crisis_jobloss_i3": "Comprueba a qué tienes derecho. Puede haber ayudas que puedas solicitar mientras estás sin trabajo. Los servicios verificados de tu país pueden decirte con exactitud qué te corresponde.",
  "crisis_jobloss_s1": "Rehaz el presupuesto en torno a tu nuevo ingreso, más bajo — por ahora solo lo esencial, todo lo demás en pausa hasta que las cosas se estabilicen.",
  "crisis_jobloss_s2": "Consigue por escrito cualquier acuerdo temporal con un acreedor, para que un mes difícil no se convierta en silencio en un impago.",
  "crisis_jobloss_s3": "No tomes deuda nueva para cubrir la vieja. Pedir prestado para pagar a un prestamista solo ahonda el pozo — los planes y las herramientas de aquí están hechos para funcionar sin eso.",
  "crisis_illness_t": "Enfermedad o baja médica",
  "crisis_illness_intro": "Cuando la salud reclama tu atención, las preocupaciones por el dinero lo hacen todo más pesado. Tu recuperación va primero — este plan evita que la parte económica añada más carga.",
  "crisis_illness_i1": "Protege primero lo esencial. La vivienda, la comida, los suministros y todo lo que necesites para tu cuidado van por delante de cualquier pago de deuda sin garantía.",
  "crisis_illness_i2": "Hazles saber a los acreedores que tu situación ha cambiado. No le debes a nadie tus datos médicos — solo que tus ingresos o tu capacidad han cambiado y que pides un acuerdo temporal por dificultad.",
  "crisis_illness_i3": "Solicita aquello a lo que tienes derecho. Puede que tengas derecho a una prestación por enfermedad o a otra ayuda. Los servicios verificados de tu país te indicarán el lugar correcto — y para la parte de salud, apóyate en los profesionales sanitarios.",
  "crisis_illness_s1": "Ajusta el presupuesto a lo esencial mientras tus ingresos sean menores, y revísalo a medida que tu situación cambie.",
  "crisis_illness_s2": "Pon por escrito cualquier acuerdo con un acreedor y guarda una copia — una cosa menos que llevar en la cabeza.",
  "crisis_illness_s3": "No pidas prestado para cubrir una deuda existente. Pide tiempo en su lugar; la mayoría de los acreedores prefiere esperar antes que llevarte más al límite.",
  "crisis_sep_t": "Separación o divorcio",
  "crisis_sep_intro": "Desenredar una vida compartida ya es bastante duro sin la niebla del dinero. Ve paso a paso, con claridad — no necesitas todas las respuestas esta semana.",
  "crisis_sep_i1": "Protege primero lo esencial, para ti y para quien dependa de ti. La vivienda, la comida y los suministros van por delante de la deuda sin garantía.",
  "crisis_sep_i2": "Contacta pronto con los acreedores por cualquier deuda conjunta. Pregunta cuáles son tus opciones y consigue cada cambio por escrito. Cuando una deuda esté a nombre de ambos, guarda registro de lo acordado.",
  "crisis_sep_i3": "Comprueba qué ayudas puedes solicitar al cambiar tu hogar. Los servicios verificados de tu país pueden decirte qué te corresponde — y para la parte legal de las deudas compartidas, el lugar correcto es la ayuda pública gratuita de deudas o un asesor cualificado.",
  "crisis_sep_s1": "Rehaz el presupuesto en torno a tus propios ingresos y gastos como hogar de una sola persona.",
  "crisis_sep_s2": "Donde puedas, separa las finanzas paso a paso, guardando registro escrito de cada acuerdo.",
  "crisis_sep_s3": "No tomes deuda nueva para suavizar la transición. Los acuerdos firmes y honestos te protegen mucho mejor que pedir prestado.",
  "crisis_emerg_t": "Una emergencia repentina",
  "crisis_emerg_intro": "Un gasto inesperado o un golpe pueden desviar el plan. No borra lo que has avanzado — solo necesita una pausa serena y un siguiente paso claro.",
  "crisis_emerg_i1": "Cubre primero lo verdaderamente esencial — seguridad, vivienda, comida, suministros. Una emergencia puntual no es el momento de poner el pago de una tarjeta por delante de mantener la luz encendida.",
  "crisis_emerg_i2": "Si la emergencia hace que se te pase un pago, avisa a ese acreedor ahora y pide una breve pausa en los pagos. Una pausa planificada siempre es mejor que un impago en silencio.",
  "crisis_emerg_i3": "Comprueba si hay alguna ayuda de emergencia a la que puedas recurrir. Los servicios verificados de tu país pueden orientarte hacia ayuda que quizá no sabías que existía.",
  "crisis_emerg_s1": "Una vez atendido el golpe inmediato, reconstruye tu colchón poco a poco — hasta una pequeña cantidad cada semana cuenta.",
  "crisis_emerg_s2": "Revisa de nuevo el presupuesto y ajusta el plan para las próximas semanas, no para todo el año de golpe.",
  "crisis_emerg_s3": "Evita el crédito caro para salvar el bache. Un acuerdo breve con un acreedor que ya tienes casi siempre te cuesta menos.",
  "ci_trend_title": "Tu colchón, semana a semana",
  "ci_trend_empty": "Tu tendencia se construye aquí. Registra un par de semanas y la verás tomar forma.",
  "ci_title": "¿Cómo fue esta semana?",
  "ci_lead": "Un registro rápido — sin juicios, sin racha que romper. Solo una marca de dónde estás esta semana.",
