  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Plans de crise",
  "crisis_title": "Quand la vie bascule soudain",
  "crisis_lead": "Un changement soudain n'efface pas les progrès déjà accomplis. Choisissez ce qui se rapproche le plus de votre situation — chaque plan commence par la ou les deux choses qui comptent le plus aujourd'hui, puis par comment retrouver un sol stable.",
  "crisis_immediate": "Maintenant",
  "crisis_stabilise": "Retrouvez un sol stable",
  "crisis_act_letter": "Rédigez une lettre à votre créancier",
  "crisis_act_support": "Trouvez de l'aide vérifiée près de chez vous",
  "crisis_act_budget": "Ouvrez le planificateur de budget",
  "crisis_safe_note": "Ceci est une information générale, pas un avis juridique ou médical. Pour tout ce qui est propre à votre situation, appuyez-vous sur les services gratuits de la rubrique Aide et, quand cela compte, sur un professionnel qualifié.",
  "crisis_jobloss_t": "Perte d'emploi",
  "crisis_jobloss_intro": "Perdre un revenu fait peur, mais vous avez plus de marge de manœuvre qu'il n'y paraît en ce moment. Rien ne doit être résolu aujourd'hui — seulement commencé.",
  "crisis_jobloss_i1": "Protégez d'abord l'essentiel. Avant toute dette non garantie, assurez-vous de couvrir le logement, la nourriture, les charges et le transport dont vous avez besoin pour chercher du travail. Cela passe avant les paiements de carte ou de prêt.",
  "crisis_jobloss_i2": "Prévenez vos créanciers avant de manquer un paiement. Un message court et honnête indiquant que vos revenus ont changé ouvre la porte à une pause ou à une mensualité plus basse — et c'est bien plus facile à arranger avant l'arrivée d'une mise en demeure.",
  "crisis_jobloss_i3": "Vérifiez ce à quoi vous avez droit. Il peut exister des aides à demander pendant votre recherche d'emploi. Les services vérifiés de votre pays peuvent vous dire exactement ce qui s'applique à vous.",
  "crisis_jobloss_s1": "Refaites le budget autour de votre nouveau revenu, plus bas — pour l'instant seulement l'essentiel, tout le reste en pause jusqu'à ce que les choses se stabilisent.",
  "crisis_jobloss_s2": "Obtenez par écrit tout arrangement temporaire avec un créancier, pour qu'un mois difficile ne se transforme pas en silence en défaut de paiement.",
  "crisis_jobloss_s3": "Ne contractez pas de nouvelle dette pour couvrir l'ancienne. Emprunter pour rembourser un prêteur ne fait que creuser le trou — les plans et les outils ici sont conçus pour fonctionner sans cela.",
  "crisis_illness_t": "Maladie ou arrêt maladie",
  "crisis_illness_intro": "Quand votre santé réclame votre attention, les soucis d'argent rendent tout plus lourd. Votre rétablissement passe d'abord — ce plan empêche le côté financier d'alourdir la charge.",
  "crisis_illness_i1": "Protégez d'abord l'essentiel. Le logement, la nourriture, les charges et tout ce dont vous avez besoin pour vos soins passent avant tout paiement de dette non garantie.",
  "crisis_illness_i2": "Faites savoir aux créanciers que votre situation a changé. Vous ne devez à personne vos données médicales — seulement que vos revenus ou vos capacités ont changé, et que vous demandez un arrangement temporaire pour difficulté.",
  "crisis_illness_i3": "Demandez ce à quoi vous avez droit. Vous pouvez avoir droit à des indemnités maladie ou à d'autres aides. Les services vérifiés de votre pays vous orienteront au bon endroit — et pour la santé, appuyez-vous sur les professionnels de santé.",
  "crisis_illness_s1": "Ramenez le budget à l'essentiel tant que vos revenus sont réduits, et révisez-le à mesure que votre situation évolue.",
  "crisis_illness_s2": "Mettez par écrit tout arrangement avec un créancier et gardez-en une copie — une chose de moins à garder en tête.",
  "crisis_illness_s3": "N'empruntez pas pour couvrir une dette existante. Demandez plutôt du temps ; la plupart des créanciers préfèrent attendre que de vous pousser davantage.",
  "crisis_sep_t": "Séparation ou divorce",
  "crisis_sep_intro": "Démêler une vie commune est déjà assez difficile sans le brouillard de l'argent. Avancez un pas clair à la fois — vous n'avez pas besoin de toutes les réponses cette semaine.",
  "crisis_sep_i1": "Protégez d'abord l'essentiel, pour vous et pour ceux qui dépendent de vous. Le logement, la nourriture et les charges passent avant la dette non garantie.",
  "crisis_sep_i2": "Contactez tôt les créanciers pour toute dette commune. Demandez quelles sont vos options et obtenez chaque changement par écrit. Lorsqu'une dette est aux deux noms, gardez une trace de ce qui est convenu.",
  "crisis_sep_i3": "Vérifiez les aides que vous pouvez demander quand votre foyer change. Les services vérifiés de votre pays peuvent vous dire ce qui s'applique — et pour le volet juridique des dettes communes, le bon interlocuteur est l'aide publique gratuite ou un conseiller qualifié.",
  "crisis_sep_s1": "Refaites le budget autour de vos propres revenus et dépenses, en tant que foyer d'une seule personne.",
  "crisis_sep_s2": "Là où vous le pouvez, séparez les finances étape par étape, en gardant une trace écrite de chaque arrangement.",
  "crisis_sep_s3": "Ne contractez pas de nouvelle dette pour adoucir la transition. Des arrangements fermes et honnêtes vous protègent bien mieux que l'emprunt.",
  "crisis_emerg_t": "Une urgence soudaine",
  "crisis_emerg_intro": "Une dépense imprévue ou un choc peut faire dévier le plan. Cela n'efface pas vos progrès — il faut seulement une pause calme et un prochain pas clair.",
  "crisis_emerg_i1": "Couvrez d'abord le vraiment essentiel — sécurité, logement, nourriture, charges. Une urgence ponctuelle n'est pas le moment de faire passer un paiement de carte avant le fait de garder la lumière allumée.",
  "crisis_emerg_i2": "Si l'urgence vous fait manquer un paiement, prévenez ce créancier maintenant et demandez une courte pause de paiement. Une pause planifiée vaut toujours mieux qu'un manquement silencieux.",
  "crisis_emerg_i3": "Vérifiez s'il existe une aide d'urgence à laquelle vous pouvez recourir. Les services vérifiés de votre pays peuvent vous orienter vers une aide dont vous ignoriez peut-être l'existence.",
  "crisis_emerg_s1": "Une fois le choc immédiat géré, reconstituez votre matelas peu à peu — même un petit montant chaque semaine compte.",
  "crisis_emerg_s2": "Revérifiez le budget et ajustez le plan pour les prochaines semaines, pas pour toute l'année d'un coup.",
  "crisis_emerg_s3": "Évitez l'emprunt coûteux pour combler le trou. Un court arrangement avec un créancier que vous avez déjà vous coûte presque toujours moins.",
  "ci_trend_title": "Votre matelas, semaine après semaine",
  "ci_trend_empty": "Votre tendance se construit ici. Notez deux ou trois semaines et vous la verrez prendre forme.",
  "ci_title": "Comment s’est passée cette semaine ?",
  "ci_lead": "Un point rapide — sans jugement, sans série à ne pas briser. Juste un repère de là où vous en êtes cette semaine.",
  "ci_buffer_lbl": "Argent qu'il vous est resté cette semaine",
  "ci_note_lbl": "Quelque chose à retenir de cette semaine ? (facultatif)",
  "ci_note_ph": "p. ex. Appelé la banque, obtenu une mensualité plus basse",
  "ci_save": "Noter cette semaine",
