  "tool_intro_dfd": "Ceci transforme vos chiffres réels en une date — le jour où vous pourriez avoir fini de rembourser. Puis il montre à quel point un petit versement en plus la rapprocherait.",
  "tool_intro_strat": "Il n'y a pas une seule 'bonne' façon de solder ses dettes — il y en a quelques-unes éprouvées. Ceci vous en montre deux, côte à côte, et laquelle convient à votre situation. Sans jargon, juste vos chiffres.",
  "tool_intro_budget": "Avant que quoi que ce soit n'aille à la dette, votre vie passe d'abord. Ceci détaille l'essentiel, puis vous montre honnêtement ce qu'il reste pour ce que vous devez.",
  "tool_intro_income": "Vous n'avez pas besoin de doubler vos revenus pour changer votre calendrier. Ceci montre combien de temps vous gagneriez pour chaque petit surplus que vous pouvez apporter.",
  "tool_intro_collect": "Toutes les dettes ne sont pas aussi urgentes, et les traiter toutes pareil épuise. Ceci trie les vôtres selon ce qui a vraiment besoin d'attention maintenant — pour que vous puissiez respirer.",
  "tool_intro_legal": "Vous avez plus de droits qu'on ne vous l'a sans doute dit. Ceci expose les protections là où vous vivez, en langage clair, pour que personne ne puisse vous mettre la pression avec des choses fausses.",
