  "strat_cmp_verdict_snow": "Avec vos chiffres, ces deux-là finissent au coude à coude. Boule de neige solde votre première dette en {first} mois — cette victoire précoce ne coûte qu'environ {extra} de plus au total. Si c'est l'élan qui vous porte, commencez ici.",
