  "mf_dl_h": "Conserva il tuo piano",
  "mf_dl_note": "Un unico file con il tuo piano, la data in cui l'hai creato e i servizi gratuiti nel tuo paese. Si apre su qualsiasi dispositivo, funziona senza internet ed è tuo.",
  "mf_dl_btn": "Scarica il mio piano",
