  "mf_x_created": "Creato il",
  "mf_x_plan_h": "Il tuo piano",
  "mf_x_repeat": "Non sostituiamo questi servizi. Siamo fatti per essere usati accanto a loro.",
  "mf_x_del90": "Il giorno 90 eliminiamo il tuo piano, le tue risposte, i tuoi documenti e tutto ciò che di personale contengono. Niente di tuo resta nel nostro servizio. Il tuo piano è tuo e funziona senza di noi.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Piani di crisi",
  "crisis_title": "Quando la vita cambia di colpo",
  "crisis_lead": "Un cambiamento improvviso non cancella i progressi che hai fatto. Scegli ciò che è più vicino alla tua situazione — ogni piano parte dall'una o due cose che oggi contano di più, poi da come rimettere piede su un terreno stabile.",
  "crisis_immediate": "Adesso",
  "crisis_stabilise": "Stabilizza il terreno",
  "crisis_act_letter": "Prepara una lettera al tuo creditore",
  "crisis_act_support": "Trova aiuto verificato vicino a te",
  "crisis_act_budget": "Apri il budget di crisi",
  "crisis_safe_note": "Questa è un'informazione generale, non consulenza legale o medica. Per tutto ciò che riguarda la tua situazione, appoggiati ai servizi gratuiti nella sezione Supporto e, quando conta, a un professionista qualificato.",
  "crisis_jobloss_t": "Perdita del lavoro",
  "crisis_jobloss_intro": "Perdere un reddito spaventa, ma hai più margine di movimento di quanto sembri in questo momento. Niente deve essere risolto oggi — solo iniziato.",
  "crisis_jobloss_i1": "Proteggi prima l'essenziale. Prima di qualsiasi debito non garantito, assicurati che siano coperti casa, cibo, utenze e i trasporti che ti servono per cercare lavoro. Vengono prima dei pagamenti di carte o prestiti.",
  "crisis_jobloss_i2": "Avvisa i tuoi creditori prima di saltare un pagamento. Un messaggio breve e sincero sul fatto che il tuo reddito è cambiato apre la porta a una pausa o a una rata più bassa — ed è molto più facile da concordare prima che arrivi un sollecito.",
  "crisis_jobloss_i3": "Controlla a cosa hai diritto. Potrebbero esserci sostegni che puoi richiedere mentre sei senza lavoro. I servizi verificati del tuo paese possono dirti con precisione cosa spetta a te.",
  "crisis_jobloss_s1": "Rifai il budget intorno al tuo nuovo reddito, più basso — per ora solo l'essenziale, tutto il resto in pausa finché le cose non si assestano.",
  "crisis_jobloss_s2": "Metti per iscritto qualsiasi accordo temporaneo con un creditore, così un mese difficile non si trasforma in silenzio in un'insolvenza.",
  "crisis_jobloss_s3": "Non contrarre nuovi debiti per coprire quelli vecchi. Chiedere prestiti per pagare un creditore non fa che approfondire la buca — i piani e gli strumenti qui sono fatti per funzionare senza.",
  "crisis_illness_t": "Malattia o congedo per malattia",
  "crisis_illness_intro": "Quando la salute chiede la tua attenzione, i pensieri sui soldi rendono tutto più pesante. La tua guarigione viene prima — questo piano evita che la parte economica aggiunga peso.",
  "crisis_illness_i1": "Proteggi prima l'essenziale. Casa, cibo, utenze e tutto ciò che ti serve per le cure vengono prima di qualsiasi pagamento di debito non garantito.",
  "crisis_illness_i2": "Fai sapere ai creditori che la tua situazione è cambiata. Non devi a nessuno i tuoi dati medici — solo che il tuo reddito o le tue capacità sono cambiate e che chiedi un accordo temporaneo per difficoltà.",
  "crisis_illness_i3": "Richiedi ciò a cui hai diritto. Potresti avere diritto a un'indennità di malattia o ad altri sostegni. I servizi verificati del tuo paese ti indirizzano al posto giusto — e per la salute, appoggiati ai professionisti sanitari.",
  "crisis_illness_s1": "Riduci il budget all'essenziale finché il tuo reddito è ridotto, e rivedilo man mano che la situazione cambia.",
  "crisis_illness_s2": "Metti per iscritto ogni accordo con un creditore e conservane una copia — una cosa in meno da tenere in testa.",
  "crisis_illness_s3": "Non chiedere prestiti per coprire un debito esistente. Chiedi tempo, piuttosto; la maggior parte dei creditori preferisce aspettare che spingerti oltre.",
  "crisis_sep_t": "Separazione o divorzio",
  "crisis_sep_intro": "Districare una vita condivisa è già abbastanza duro senza la nebbia del denaro. Vai un passo chiaro alla volta — non ti servono tutte le risposte questa settimana.",
  "crisis_sep_i1": "Proteggi prima l'essenziale, per te e per chi dipende da te. Casa, cibo e utenze vengono prima del debito non garantito.",
  "crisis_sep_i2": "Contatta presto i creditori per ogni debito comune. Chiedi quali sono le tue opzioni e ottieni ogni cambiamento per iscritto. Quando un debito è a nome di entrambi, tieni traccia di ciò che si concorda.",
  "crisis_sep_i3": "Controlla quali sostegni puoi richiedere quando cambia il tuo nucleo familiare. I servizi verificati del tuo paese possono dirti cosa si applica — e per la parte legale dei debiti condivisi, il posto giusto è l'aiuto pubblico gratuito o un consulente qualificato.",
  "crisis_sep_s1": "Rifai il budget intorno alle tue entrate e spese, come nucleo di una sola persona.",
  "crisis_sep_s2": "Dove puoi, separa le finanze passo dopo passo, tenendo traccia scritta di ogni accordo.",
  "crisis_sep_s3": "Non contrarre nuovi debiti per ammorbidire la transizione. Accordi solidi e onesti ti proteggono molto meglio del prestito.",
  "crisis_emerg_t": "Un'emergenza improvvisa",
  "crisis_emerg_intro": "Una spesa imprevista o un colpo possono far deviare il piano. Non cancella i tuoi progressi — serve solo una pausa serena e un prossimo passo chiaro.",
  "crisis_emerg_i1": "Copri prima ciò che è davvero essenziale — sicurezza, casa, cibo, utenze. Un'emergenza isolata non è il momento di mettere il pagamento di una carta davanti al tenere le luci accese.",
  "crisis_emerg_i2": "Se l'emergenza ti fa saltare un pagamento, avvisa quel creditore ora e chiedi una breve sospensione dei pagamenti. Una pausa pianificata è sempre meglio di un salto in silenzio.",
  "crisis_emerg_i3": "Controlla se c'è un aiuto d'emergenza a cui puoi ricorrere. I servizi verificati del tuo paese possono indirizzarti verso un aiuto che forse non sapevi esistesse.",
  "crisis_emerg_s1": "Una volta gestito il colpo immediato, ricostruisci il tuo cuscinetto poco a poco — anche una piccola somma ogni settimana conta.",
  "crisis_emerg_s2": "Ricontrolla il budget e adatta il piano per le prossime settimane, non per tutto l'anno in una volta.",
  "crisis_emerg_s3": "Evita il credito costoso per superare il momento. Un breve accordo con un creditore che hai già ti costa quasi sempre meno.",
  "ci_trend_title": "Il tuo cuscinetto, settimana dopo settimana",
  "ci_trend_empty": "Il tuo andamento si costruisce qui. Registra un paio di settimane e lo vedrai prendere forma.",
  "ci_title": "Com'è andata questa settimana?",
  "ci_lead": "Un aggiornamento veloce — nessun giudizio, nessuna serie da spezzare. Solo un segno di dove sei questa settimana.",
