  "tool_intro_strat": "Non c'è un solo modo 'giusto' per saldare i debiti — ce ne sono alcuni collaudati. Questo te ne mostra due, fianco a fianco, e quale si adatta alla tua situazione. Niente gergo, solo i tuoi numeri.",
  "tool_intro_budget": "Prima che qualcosa vada al debito, la tua vita viene prima. Questo elenca l'essenziale, poi ti mostra con onestà cosa resta da destinare a ciò che devi.",
  "tool_intro_income": "Non devi raddoppiare il tuo reddito per cambiare i tuoi tempi. Questo mostra quanto prima ti libereresti per ogni piccolo extra che riesci a portare.",
