  "h_proof_title": "Con parole loro — presto",
  "h_proof_body": "Siamo nuovi, e preferiamo non mostrarti nulla piuttosto che recensioni scritte da noi. Quando persone vere racconteranno com'è andata per loro, le loro parole troveranno spazio qui — con solo la parte del nome che scelgono di dare. Fino ad allora, il piano che costruiamo per te è l'unica prova che offriamo.",
  "h_faq_label": "Domande frequenti",
  "h_faq_q1": "È davvero gratis?",
  "h_faq_a1": "Sì. Il piano debiti di 90 giorni e tutti gli strumenti 90-Day Plan sono gratis — niente carta di pagamento, niente costi nascosti, nessun limite di tempo. 90-Day Companion (19€, pagamento unico) è un upgrade facoltativo.",
