  "h_cookie_text": "Usiamo Google Analytics e Microsoft Clarity per capire come i visitatori usano il nostro sito. Nessuna pubblicità né remarketing.",
  "h_cookie_privacy": "Informativa sulla privacy",
  "h_cookie_decline": "Rifiuta",
  "h_cookie_accept": "Accetta l'analisi",
  "sup_pub_title": "L'aiuto che esiste già nel tuo paese",
  "sup_pub_intro": "Sono organizzazioni nazionali, indipendenti da Debt-Free.World. Non c'è alcun rapporto commerciale in nessuna direzione: non ci pagano e non le paghiamo.",
  "sup_pub_repeat": "Non sostituiamo questi servizi. Siamo fatti per essere usati accanto a loro.",
  "sup_pub_country_label": "Il tuo paese",
  "sup_pub_country_choose": "— scegli —",
  "sup_pub_country_other": "Il mio paese non è in questa lista",
  "sup_pub_empty": "Quasi ogni paese ha organizzazioni che aiutano con i debiti senza farsi pagare — consulenza pubblica sui debiti, autorità dei consumatori ed enti di beneficenza. Quali esistano dipende da dove vivi, perciò questa lista aspetta il tuo paese invece di indovinarlo.",
  "sup_pub_verified": "Verificato",
