  "sup_pub_fees_note": "Quando un servizio è gratuito, lo dice la sua descrizione. Non lo affermiamo noi al posto suo.",
  "sup_pub_other_body": "Non abbiamo ancora organizzazioni verificate per quel paese, e non ne elenchiamo nessuna che non abbiamo controllato. Se scrivi a support@debt-free.world indicando il tuo paese, cercheremo il servizio nazionale e lo aggiungeremo una volta confermato.",
  "wtin_title": "Cosa Debt-Free.World non è",
  "wtin_lead": "Questa pagina esiste perché nessuno debba dedurlo dal marketing. Cinque cose che questo prodotto non fa, e tre che fa.",
  "wtin_not_label": "Cosa non fa questo prodotto",
  "wtin_not_1": "Non ti rappresenta davanti a nessuno. Né a un creditore, né a un tribunale, né a un'autorità. Niente viene depositato, inviato o firmato a tuo nome.",
  "wtin_not_2": "Non negozia con i tuoi creditori. Non c'è alcun contatto tra Debt-Free.World e chiunque tu debba pagare, in nessun momento.",
  "wtin_not_3": "Non gestisce il tuo denaro e non riceve pagamenti destinati ai creditori. I pagamenti ai creditori li fai tu, direttamente a loro. L'unico denaro che ci arriva è il 19€ del 90-Day Companion, se lo scegli.",
