  "wtin_not_5": "Non sostituisce la consulenza sui debiti né la consulenza finanziaria. Quei servizi sono regolamentati in molti paesi e questo no. Per questo le organizzazioni nazionali compaiono in ogni pagina.",
  "wtin_does_label": "Cosa fa invece",
  "wtin_does_1": "Raccoglie i tuoi numeri in un unico posto — ogni debito, ogni tasso, ogni data — e fa l'aritmetica che ne deriva.",
