  "wtin_does_3": "Mostra le organizzazioni nazionali che possono agire dove noi non possiamo, fin dalla prima pagina — non in una nota a piè di pagina alla fine.",
  "wtin_contact": "Domande su qualsiasi cosa in questa pagina: support@debt-free.world",
