  "wtin_faq_q": "Sostituite la consulenza gratuita sui debiti?",
  "wtin_faq_a": "No. Debt-Free.World non ti rappresenta davanti a nessuno, non negozia con i tuoi creditori, non gestisce il tuo denaro, non dà consulenza legale e non sostituisce la consulenza sui debiti né quella finanziaria.",
