  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Planos de crise",
  "crisis_title": "Quando a vida muda de repente",
  "crisis_lead": "Uma mudança repentina não apaga o que já avançaste. Escolhe o que estiver mais perto da tua situação — cada plano começa pela uma ou duas coisas que mais importam hoje e, depois, por como voltar a pisar terreno firme.",
  "crisis_immediate": "Agora mesmo",
  "crisis_stabilise": "Pisar terreno firme",
  "crisis_act_letter": "Redige uma carta ao teu credor",
  "crisis_act_support": "Encontra ajuda verificada onde estás",
  "crisis_act_budget": "Abre o planeador de orçamento",
  "crisis_safe_note": "Isto é orientação geral, não aconselhamento jurídico nem médico. Para o que for específico da tua situação, apoia-te nos serviços gratuitos em Apoio e, quando importar, num profissional qualificado.",
  "crisis_jobloss_t": "Perda de emprego",
  "crisis_jobloss_intro": "Perder um rendimento assusta, mas tens mais margem de manobra do que parece neste momento. Nada tem de ser resolvido hoje — apenas começado.",
  "crisis_jobloss_i1": "Protege primeiro o essencial. Antes de qualquer dívida sem garantia, garante que estão cobertos a habitação, a comida, as contas essenciais e o transporte de que precisas para procurar trabalho. Vêm antes dos pagamentos de cartões ou empréstimos.",
  "crisis_jobloss_i2": "Avisa os teus credores antes de falhares um pagamento. Uma mensagem breve e honesta de que o teu rendimento mudou abre a porta a uma pausa ou a uma prestação mais baixa — e é bem mais fácil de tratar antes de chegar uma carta de incumprimento.",
  "crisis_jobloss_i3": "Verifica a que tens direito. Pode haver apoios que possas pedir enquanto estás sem trabalho. Os serviços verificados do teu país podem dizer-te com exatidão o que se aplica a ti.",
  "crisis_jobloss_s1": "Refaz o orçamento em torno do teu novo rendimento, mais baixo — por agora só o essencial, tudo o resto em pausa até as coisas assentarem.",
  "crisis_jobloss_s2": "Consegue por escrito qualquer acordo temporário com um credor, para que um mês difícil não se transforme em silêncio num incumprimento.",
  "crisis_jobloss_s3": "Não contraias dívida nova para cobrir a antiga. Pedir emprestado para pagar a um credor só aprofunda o buraco — os planos e as ferramentas aqui foram feitos para funcionar sem isso.",
  "crisis_illness_t": "Doença ou baixa médica",
  "crisis_illness_intro": "Quando a saúde exige a tua atenção, as preocupações com o dinheiro tornam tudo mais pesado. A tua recuperação vem primeiro — este plano evita que a parte financeira acrescente peso.",
  "crisis_illness_i1": "Protege primeiro o essencial. A habitação, a comida, as contas essenciais e tudo o que precisas para os teus cuidados vêm antes de qualquer pagamento de dívida sem garantia.",
  "crisis_illness_i2": "Dá a conhecer aos credores que a tua situação mudou. Não deves a ninguém os teus dados médicos — apenas que o teu rendimento ou a tua capacidade mudaram e que pedes um acordo temporário por dificuldade.",
  "crisis_illness_i3": "Pede aquilo a que tens direito. Podes ter direito a subsídio de doença ou a outro apoio. Os serviços verificados do teu país encaminham-te para o sítio certo — e, na parte da saúde, apoia-te nos profissionais de saúde.",
  "crisis_illness_s1": "Ajusta o orçamento ao essencial enquanto o teu rendimento estiver reduzido, e revê-o à medida que a tua situação mudar.",
  "crisis_illness_s2": "Põe por escrito qualquer acordo com um credor e guarda uma cópia — menos uma coisa para trazer na cabeça.",
  "crisis_illness_s3": "Não peças emprestado para cobrir uma dívida existente. Pede tempo, em vez disso; a maioria dos credores prefere esperar a empurrar-te para mais aperto.",
  "crisis_sep_t": "Separação ou divórcio",
  "crisis_sep_intro": "Desenredar uma vida partilhada já é bastante difícil sem o nevoeiro do dinheiro. Vai um passo claro de cada vez — não precisas de todas as respostas esta semana.",
  "crisis_sep_i1": "Protege primeiro o essencial, para ti e para quem depende de ti. A habitação, a comida e as contas essenciais vêm antes da dívida sem garantia.",
  "crisis_sep_i2": "Contacta cedo os credores por qualquer dívida conjunta. Pergunta quais são as tuas opções e consegue cada alteração por escrito. Quando uma dívida estiver em nome dos dois, guarda registo do que for acordado.",
  "crisis_sep_i3": "Verifica que apoios podes pedir quando o teu agregado muda. Os serviços verificados do teu país podem dizer-te o que se aplica — e, na parte jurídica das dívidas partilhadas, o sítio certo é a ajuda pública gratuita de dívidas ou um consultor qualificado.",
  "crisis_sep_s1": "Refaz o orçamento em torno dos teus próprios rendimentos e despesas como um agregado de uma só pessoa.",
  "crisis_sep_s2": "Onde puderes, separa as finanças passo a passo, guardando registo escrito de cada acordo.",
  "crisis_sep_s3": "Não contraias dívida nova para suavizar a transição. Acordos firmes e honestos protegem-te muito melhor do que pedir emprestado.",
  "crisis_emerg_t": "Uma emergência repentina",
  "crisis_emerg_intro": "Uma despesa inesperada ou um choque podem desviar o plano. Não apaga o que avançaste — só precisa de uma pausa serena e de um próximo passo claro.",
  "crisis_emerg_i1": "Cobre primeiro o que é verdadeiramente essencial — segurança, habitação, comida, contas essenciais. Uma emergência pontual não é o momento de pôr o pagamento de um cartão à frente de manter a luz acesa.",
  "crisis_emerg_i2": "Se a emergência fizer com que falhes um pagamento, avisa esse credor agora e pede uma breve pausa nos pagamentos. Uma pausa planeada é sempre melhor do que uma falha em silêncio.",
  "crisis_emerg_i3": "Verifica se há algum apoio de emergência a que possas recorrer. Os serviços verificados do teu país podem encaminhar-te para ajuda que talvez não soubesses que existia.",
  "crisis_emerg_s1": "Depois de tratado o choque imediato, reconstrói a tua almofada aos poucos — até uma pequena quantia por semana conta.",
  "crisis_emerg_s2": "Revê de novo o orçamento e ajusta o plano para as próximas semanas, não para o ano inteiro de uma vez.",
  "crisis_emerg_s3": "Evita o crédito caro para superar o aperto. Um acordo breve com um credor que já tens custa-te quase sempre menos.",
  "ci_trend_title": "A tua almofada, semana a semana",
  "ci_trend_empty": "A tua tendência constrói-se aqui. Regista umas semanas e vais vê-la ganhar forma.",
  "ci_title": "Como correu esta semana?",
