  "tool_intro_dfd": "Isto transforma os teus números reais numa data — o dia em que poderias acabar de pagar. Depois mostra quanto mais cedo chegaria só com um pequeno pagamento extra.",
  "tool_intro_strat": "Não há uma única forma 'certa' de saldar dívidas — há algumas comprovadas. Isto mostra-te duas, lado a lado, e qual encaixa na tua situação. Sem jargão, só os teus números.",
  "tool_intro_budget": "Antes de qualquer coisa ir para a dívida, a tua vida vem primeiro. Isto detalha o essencial e depois mostra-te com honestidade o que sobra para o que deves.",
  "tool_intro_income": "Não precisas de duplicar o teu rendimento para mudar o teu calendário. Isto mostra quanto mais cedo te libertarias por cada pouco extra que consigas trazer.",
  "tool_intro_collect": "Nem todas as dívidas são igualmente urgentes, e tratá-las todas da mesma forma é exaustivo. Isto ordena as tuas conforme o que realmente precisa de atenção agora — para que possas respirar.",
  "tool_intro_legal": "Tens mais direitos do que provavelmente te disseram. Isto apresenta as proteções onde vives, em linguagem clara, para que ninguém te possa pressionar com coisas que não são verdade.",
