  "strat_cmp_verdict_snow": "Com os teus números, estas duas terminam muito perto. Bola de neve liquida a tua primeira dívida em {first} meses — essa vitória cedo custa só cerca de {extra} mais no total. Se é o embalo que te mantém, começa por aqui.",
