  "h_sales_p": "Não precisas de formação financeira nem de rendimentos altos para começar — só dos teus números reais e dois minutos. Totalmente grátis, sem nada a arriscar.",
  "h_sales_btn": "Gerar o meu plano agora",
  "h_sales_fine": "Sem subscrição. Sem custos ocultos. Só clareza.",
  "h_proof_title": "Pelas suas próprias palavras — em breve",
  "h_proof_body": "Somos novos, e preferimos não te mostrar nada a mostrar-te avaliações escritas por nós. Quando pessoas reais contarem como correu para elas, as suas palavras aparecerão aqui — apenas com a parte do nome que escolherem dar. Até lá, o plano que construímos para ti é a única prova que oferecemos.",
  "h_faq_label": "Perguntas frequentes",
  "h_faq_q1": "É mesmo grátis?",
  "h_faq_a1": "Sim. O plano de dívidas de 90 dias e todas as ferramentas 90-Day Plan são grátis — sem cartão de pagamento, sem custos ocultos, sem limite de tempo. O 90-Day Companion (19€, pagamento único) é uma melhoria opcional.",
  "h_faq_q2": "Preciso de cartão de pagamento?",
