  "h_cookie_text": "Usamos o Google Analytics e o Microsoft Clarity para perceber como os visitantes usam o nosso site. Sem publicidade nem remarketing.",
  "h_cookie_privacy": "Política de privacidade",
  "h_cookie_decline": "Recusar",
  "h_cookie_accept": "Aceitar a análise",
  "sup_pub_title": "A ajuda que já existe no teu país",
  "sup_pub_intro": "São organizações nacionais, independentes de Debt-Free.World. Não há relação comercial em nenhum sentido: nem elas nos pagam nem nós lhes pagamos.",
  "sup_pub_repeat": "Não substituímos estes serviços. Fomos feitos para ser usados a par deles.",
  "sup_pub_country_label": "O teu país",
  "sup_pub_country_choose": "— escolhe —",
  "sup_pub_country_other": "O meu país não está nesta lista",
  "sup_pub_empty": "Quase todos os países têm organizações que ajudam com as dívidas sem cobrar por isso — aconselhamento público de dívidas, autoridades de consumo e instituições de solidariedade. Quais existem depende de onde vives, por isso esta lista espera pelo teu país em vez de o adivinhar.",
  "sup_pub_verified": "Verificado",
  "sup_pub_verified_note": "Cada organização aqui foi verificada com a sua própria fonte nacional. Nada nesta lista é gerado.",
  "sup_pub_fees_note": "Quando um serviço é gratuito, a sua descrição di-lo. Não o afirmamos em seu nome.",
  "sup_pub_other_body": "Ainda não temos organizações verificadas para esse país, e não incluímos nenhuma que não tenhamos verificado. Se escreveres para support@debt-free.world e indicares o teu país, procuramos o serviço nacional e acrescentamo-lo assim que estiver confirmado.",
  "wtin_title": "O que Debt-Free.World não é",
  "wtin_lead": "Esta página existe para que ninguém tenha de o deduzir do marketing. Cinco coisas que este produto não faz, e três que faz.",
  "wtin_not_label": "O que este produto não faz",
  "wtin_not_1": "Não te representa perante ninguém. Nem perante um credor, nem um tribunal, nem uma autoridade. Nada é apresentado, enviado ou assinado em teu nome.",
  "wtin_not_2": "Não negoceia com os teus credores. Não há qualquer contacto entre Debt-Free.World e ninguém a quem devas dinheiro, em momento algum.",
  "wtin_not_3": "Não gere o teu dinheiro nem recebe pagamentos destinados aos credores. Os pagamentos aos credores fá-los tu, diretamente a eles. O único dinheiro que nos chega é o 19€ do 90-Day Companion, se o escolheres.",
  "wtin_not_4": "Não dá aconselhamento jurídico. Pode dizer o que significa um termo e qual costuma ser uma consequência; não pode dizer qual é a tua posição jurídica.",
  "wtin_not_5": "Não substitui o aconselhamento de dívidas nem o aconselhamento financeiro. Esses serviços são regulados em muitos países e este não é. É por isso que as organizações nacionais aparecem em cada página.",
  "wtin_does_label": "O que faz em vez disso",
  "wtin_does_1": "Reúne os teus próprios números num só lugar — cada dívida, cada taxa, cada data — e faz a aritmética que decorre deles.",
  "wtin_does_2": "Apresenta as rotas que existem na tua situação e ao que leva cada uma, lado a lado. Que rota seguir decides tu.",
  "wtin_does_3": "Mostra as organizações nacionais que podem agir onde nós não podemos, desde a primeira página — não numa nota de rodapé no fim.",
  "wtin_contact": "Dúvidas sobre qualquer coisa desta página: support@debt-free.world",
  "wtin_foot_link": "O que isto não é",
  "wtin_faq_q": "Substituem o aconselhamento gratuito de dívidas?",
  "wtin_faq_a": "Não. Debt-Free.World não te representa perante ninguém, não negoceia com os teus credores, não gere o teu dinheiro, não dá aconselhamento jurídico e não substitui o aconselhamento de dívidas nem o aconselhamento financeiro.",
