  "mf_x_del90": "W 90. dniu usuwamy Twój plan, Twoje odpowiedzi, Twoje dokumenty i wszystko, co w nich osobiste. W naszym serwisie nie zostaje nic Twojego. Twój plan należy do Ciebie i działa bez nas.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "Gdy życie nagle się zmienia",
  "crisis_lead": "Nagła zmiana nie przekreśla Twoich dotychczasowych postępów. Wybierz to, co najbliższe Twojej sytuacji — każdy plan zaczyna się od jednej czy dwóch rzeczy najważniejszych dziś, a potem od tego, jak odzyskać grunt pod nogami.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Napisz pismo do wierzyciela",
  "crisis_act_support": "Znajdź zweryfikowaną pomoc tam, gdzie jesteś",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "To ogólne wskazówki, nie porada prawna ani medyczna. W sprawach dotyczących Twojej konkretnej sytuacji oprzyj się na bezpłatnych usługach w sekcji Wsparcie, a gdy to istotne, na wykwalifikowanym specjaliście.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "Utrata dochodu przeraża, ale masz więcej pola manewru, niż teraz się wydaje. Nic nie musi zostać rozwiązane dziś — wystarczy zacząć.",
  "crisis_jobloss_i1": "Najpierw zabezpiecz to, co niezbędne. Przed jakimkolwiek długiem niezabezpieczonym upewnij się, że masz pokryte mieszkanie, jedzenie, prąd oraz transport potrzebny do szukania pracy. To idzie przed spłatą kart i pożyczek.",
  "crisis_jobloss_i2": "Powiedz wierzycielom, zanim spóźnisz się z płatnością. Krótka, szczera wiadomość o tym, że Twój dochód się zmienił, otwiera drzwi do pauzy lub niższej raty — a znacznie łatwiej to ustalić, zanim przyjdzie pismo o zaległości.",
  "crisis_jobloss_i3": "Sprawdź, co Ci przysługuje. Może istnieć wsparcie, o które możesz się ubiegać, będąc między jedną a drugą pracą. Zweryfikowane służby w Twoim kraju powiedzą Ci dokładnie, co dotyczy właśnie Ciebie.",
  "crisis_jobloss_s1": "Zbuduj budżet na nowo wokół nowego, niższego dochodu — na razie tylko to, co niezbędne, reszta wstrzymana, aż sytuacja się uspokoi.",
  "crisis_jobloss_s2": "Każde tymczasowe ustalenie z wierzycielem miej na piśmie, żeby trudny miesiąc nie zamienił się po cichu w zaległość.",
  "crisis_jobloss_s3": "Nie bierz nowego długu na pokrycie starego. Pożyczanie, by spłacić pożyczkodawcę, tylko pogłębia dołek — plany i narzędzia tutaj są stworzone tak, by działać bez tego.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "Gdy zdrowie potrzebuje Twojej uwagi, zmartwienia o pieniądze wszystko obciążają jeszcze bardziej. Twój powrót do zdrowia jest najważniejszy — ten plan pilnuje, by strona finansowa nie dokładała się do ciężaru.",
  "crisis_illness_i1": "Najpierw zabezpiecz to, co niezbędne. Mieszkanie, jedzenie, prąd i to, czego potrzebujesz do swojej opieki, idą przed jakąkolwiek spłatą długu niezabezpieczonego.",
  "crisis_illness_i2": "Daj wierzycielom znać, że Twoja sytuacja się zmieniła. Nikomu nie jesteś winien swoich danych medycznych — tylko tego, że zmienił się Twój dochód lub możliwości i że prosisz o tymczasowe rozwiązanie na czas trudności.",
  "crisis_illness_i3": "Ubiegaj się o to, co Ci przysługuje. Może przysługiwać Ci zasiłek chorobowy lub inne wsparcie. Zweryfikowane służby w Twoim kraju wskażą Ci właściwe miejsce — a w sprawach zdrowia oprzyj się na pracownikach medycznych.",
  "crisis_illness_s1": "Ogranicz budżet do tego, co niezbędne, póki dochód jest niższy, i wracaj do niego w miarę zmian sytuacji.",
  "crisis_illness_s2": "Każde ustalenie z wierzycielem miej na piśmie i zachowaj kopię — o jedną rzecz mniej do trzymania w głowie.",
  "crisis_illness_s3": "Nie pożyczaj, by pokryć istniejący dług. Zamiast tego poproś o czas; większość wierzycieli woli poczekać, niż naciskać na Ciebie mocniej.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Rozplątywanie wspólnego życia jest wystarczająco trudne bez mgły wokół pieniędzy. Rób to krok po kroku, wyraźnie — nie potrzebujesz wszystkich odpowiedzi w tym tygodniu.",
  "crisis_sep_i1": "Najpierw zabezpiecz to, co niezbędne — dla siebie i dla każdego, kto jest od Ciebie zależny. Mieszkanie, jedzenie i prąd idą przed długiem niezabezpieczonym.",
  "crisis_sep_i2": "Skontaktuj się z wierzycielami wcześnie w sprawie wspólnych długów. Zapytaj o swoje opcje i każdą zmianę miej na piśmie. Gdy dług jest na oba nazwiska, prowadź zapis tego, co zostało ustalone.",
  "crisis_sep_i3": "Sprawdź, o jakie wsparcie możesz się ubiegać, gdy zmienia się Twoje gospodarstwo domowe. Zweryfikowane służby w Twoim kraju powiedzą Ci, co ma zastosowanie — a w prawnej stronie wspólnych długów właściwym miejscem jest krajowa bezpłatna pomoc dłużnikom lub wykwalifikowany doradca.",
  "crisis_sep_s1": "Zbuduj budżet na nowo wokół własnego dochodu i kosztów jako jednoosobowe gospodarstwo domowe.",
  "crisis_sep_s2": "Tam, gdzie możesz, rozdzielaj finanse krok po kroku, prowadząc pisemny zapis każdego ustalenia.",
  "crisis_sep_s3": "Nie bierz nowego długu, by złagodzić przejście. Stabilne, uczciwe ustalenia chronią Cię znacznie lepiej niż pożyczanie.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "Nieoczekiwany wydatek lub wstrząs może wytrącić plan z torów. Nie wymazuje to Twoich dotychczasowych postępów — potrzeba tylko spokojnej pauzy i jednego wyraźnego kolejnego kroku.",
  "crisis_emerg_i1": "Najpierw pokryj to, co naprawdę niezbędne — bezpieczeństwo, mieszkanie, jedzenie, prąd. Jednorazowa nagła sytuacja to nie moment, by stawiać spłatę karty przed utrzymaniem światła w domu.",
  "crisis_emerg_i2": "Jeśli nagła sytuacja oznacza, że spóźnisz się z płatnością, powiedz o tym wierzycielowi teraz i poproś o krótką przerwę w spłacie. Zaplanowana pauza jest zawsze lepsza niż ciche opóźnienie.",
  "crisis_emerg_i3": "Sprawdź, czy jest jakieś awaryjne wsparcie, z którego możesz skorzystać. Zweryfikowane służby w Twoim kraju mogą wskazać Ci pomoc, o której możesz nie wiedzieć.",
  "crisis_emerg_s1": "Gdy pierwszy wstrząs jest już opanowany, powoli odbudowuj poduszkę bezpieczeństwa — liczy się nawet mała kwota co tydzień.",
  "crisis_emerg_s2": "Sprawdź budżet ponownie i dostosuj plan na najbliższe tygodnie, a nie od razu na cały rok.",
  "crisis_emerg_s3": "Unikaj kosztownego pożyczania, by załatać lukę. Krótkie ustalenie z wierzycielem, którego już masz, prawie zawsze kosztuje Cię mniej.",
  "ci_trend_title": "Your buffer, week by week",
  "ci_trend_empty": "Twój trend buduje się tutaj. Zapisz kilka tygodni, a zobaczysz, jak nabiera kształtu.",
  "ci_title": "How did this week go?",
  "ci_lead": "Szybki zapis — bez oceniania, bez serii do przerwania. Po prostu znacznik tego, gdzie jesteś w tym tygodniu.",
  "ci_buffer_lbl": "Pieniądze, które zostały Ci w tym tygodniu",
