  "dfd_result_k": "Szacowana data wyjścia z długów",
  "dfd_months": "około {m} miesięcy",
  "dfd_extra": "Dodatkowa wpłata co miesiąc",
  "dfd_note": "Przy {monthly}/miesiąc spłacasz {total} długu. Nawet niewielki dodatek co miesiąc przybliża tę datę.",
  "dfd_saved": "To około {amt} mniej odsetek",
  "dfd_saved_floor": "Co najmniej {amt} mniej odsetek — pewnie więcej, gdy uzupełnisz wszystkie oprocentowania",
  "dfd_date_approx": "Bez uwzględnienia odsetek — realna data będzie zapewne późniejsza",
  "dfd_rate_why": "Ta data pomija odsetki, bo nie zapisano jeszcze żadnego oprocentowania. To właśnie odsetki zwykle sprawiają, że niewielka nadpłata ma taką moc — dodaj swoje oprocentowanie, by zobaczyć rzeczywistą datę i ile odsetek spłaca każda dodatkowa wpłata.",
  "dfd_rate_partial": "Niektóre długi nie mają zapisanego oprocentowania, więc liczą się tu jako 0%. Rzeczywiste liczby są lepsze niż pokazane — dodaj brakujące oprocentowania, by je zobaczyć.",
  "dfd_rate_cta": "Edytuj swój plan",
  "dfd_stabilise": "Twoje koszty obecnie przewyższają wpływy, więc nie ma jeszcze daty spłaty. Pierwszym celem jest oddech — zacznij od Budżetu kryzysowego.",
  "dfd_buffer_first": "Zanim nadwyżka pójdzie na dług: poduszka {gap} sprawia, że niespodziewany rachunek nie zamieni się w nowy dług.",
  "strat_snow": "Kula śnieżna",
  "strat_aval": "Lawina",
  "strat_first": "Spłać to najpierw",
  "strat_snow_note": "Najmniejsze saldo najpierw. Szybkie zwycięstwa budują rozpęd — skuteczne, gdy najtrudniejsze jest samo zaczęcie.",
  "strat_aval_note": "Najwyższe oprocentowanie najpierw. Najtańsze w dłuższej perspektywie — skuteczne, gdy drogi dług Cię wykańcza.",
  "strat_empty": "Dodaj swoje długi podczas onboardingu, aby porównać strategie obok siebie.",
  "strat_unknown": "oprocentowanie nieznane",
  "strat_snow_why": "U Ciebie zaczyna się to od {target} — Twojego najmniejszego salda.",
  "strat_aval_why": "U Ciebie zaczyna się to od długu {target} — najwyższego oprocentowania, jakie masz.",
  "tool_intro_dfd": "To zamienia Twoje rzeczywiste liczby w jedną datę — dzień, w którym możesz być wolny. Potem pokazuje, o ile wcześniej przybliżyłaby ją nawet niewielka dodatkowa wpłata.",
  "tool_intro_strat": "Nie ma jednego „właściwego” sposobu na spłatę długu — jest kilka sprawdzonych. To pokazuje dwa z nich obok siebie i który pasuje do Twojej sytuacji. Bez żargonu, tylko Twoje liczby.",
  "tool_intro_budget": "Zanim cokolwiek pójdzie na dług, najpierw jest Twoje życie. To rozpisuje, co niezbędne, a potem uczciwie pokazuje, ile zostaje na spłatę tego, co jesteś winien.",
  "tool_intro_income": "Nie musisz podwajać dochodu, by zmienić swój harmonogram. To pokazuje, o ile wcześniej byłbyś wolny za każdy dodatkowy grosz, który zdołasz zarobić.",
  "tool_intro_collect": "Nie każdy dług jest równie pilny, a traktowanie wszystkich tak samo jest wyczerpujące. To porządkuje Twoje według tego, co naprawdę wymaga uwagi teraz — żebyś mógł odetchnąć.",
  "tool_intro_legal": "Masz więcej praw, niż prawdopodobnie Ci powiedziano. To przedstawia ochronę obowiązującą tam, gdzie mieszkasz, prostym językiem, żeby nikt nie mógł naciskać na Ciebie rzeczami, które nie są prawdą.",
  "nav_g_debtfree_sub": "Wszystko, czego potrzebujesz, by jasno zobaczyć swoją sytuację i zaplanować wyjście.",
  "nav_g_tools_sub": "Sześć kalkulatorów. Każdy odpowiada na jedno realne pytanie o Twoje pieniądze.",
  "nav_g_learn_sub": "Krótkie, szczere teksty — bez wypełniacza, nic do kupienia.",
  "nav_g_recovery_sub": "Gdy poczujesz gotowość, głębsze narzędzia do stawiania oporu i odbudowy.",
  "strat_cmp_title": "Twoje dwie ścieżki obok siebie",
  "strat_cmp_snow": "Snowball",
  "strat_cmp_aval": "Avalanche",
  "strat_cmp_months": "{m} months",
  "strat_cmp_interest": "Interest you'd pay",
  "strat_cmp_first": "Pierwszy dług znika w {m} miesięcy",
  "strat_cmp_verdict_aval": "Przy Twoich liczbach Lawina oszczędza Ci około {save} i spłaca wszystko mniej więcej {months} miesięcy wcześniej. Jeśli patrzenie na spadający koszt całkowity utrzymuje Cię w ruchu, zacznij tutaj.",
  "strat_cmp_verdict_snow": "Przy Twoich liczbach te dwie kończą się blisko siebie. Kula śnieżna spłaca Twój pierwszy dług w {first} miesięcy — to wczesne zwycięstwo kosztuje w sumie tylko około {extra} więcej. Jeśli to rozpęd utrzymuje Cię w ruchu, zacznij tutaj.",
  "strat_cmp_approx": "Szacunek kierunkowy: zakłada, że każda wolna część Twojego budżetu idzie na długi po kolei. Twoja rzeczywista kolejność płatności i ewentualne płatności minimalne mogą to zmienić.",
  "strat_cmp_needsurplus": "Gdy co miesiąc zostaje nadwyżka, to pokaże Ci obie ścieżki i tę, która uwalnia Cię wcześniej. Na razie kolejność poniżej wciąż jest mądrym miejscem na start.",
  "budget_in": "Wpływy",
  "budget_housing": "Mieszkanie",
  "budget_other": "Inne niezbędne",
  "budget_left": "Zostaje na dług i oszczędności",
  "budget_shortfall": "Miesięczny niedobór",
  "budget_note": "W kryzysie najpierw to, co niezbędne — mieszkanie, jedzenie, prąd, transport. To, co zostaje, to Twoja zdolność spłaty. Jeśli jest ujemna, to nie porażka: to sygnał, by skorzystać z bezpłatnego wsparcia w Twoim planie.",
  "budget_life": "Room for life",
  "budget_free": "Free for your debt",
  "budget_life_note": "Zostawianie miejsca na życie sprawia, że to się utrzyma — dług dostaje to, co naprawdę zbywa.",
  "income_k": "Nowa data wyjścia z długów",
  "income_add": "Dodatkowy dochód co miesiąc",
  "income_sooner": "Około {m} miesięcy wcześniej.",
  "income_note": "Dodatkowa fucha, sprzedaż czegoś nieużywanego, mała podwyżka — dodatkowy dochód to najszybsza dźwignia, którą kontrolujesz.",
  "income_nostart": "Gdy będziesz mieć miesięczną nadwyżkę, dodatkowy dochód skróci tutaj Twój harmonogram.",
  "income_base": "W obecnej sytuacji: {date}",
  "collect_note": "Długi w windykacji lub w sądzie idą pierwsze — mają wagę prawną. Następne są długi wysoko oprocentowane, bo rosną najszybciej.",
  "collect_empty": "Nie zapisano jeszcze żadnych długów.",
  "legal_rights": "Twoja ochrona",
  "legal_support": "Gdzie szukać pomocy",
  "legal_warn": "To ogólne informacje, nie porada prawna. W Twojej sytuacji skontaktuj się z jedną z bezpłatnych, wykwalifikowanych usług poniżej.",
  "legal_signpost": "Nie musisz mierzyć się z tym sam — jest tu dla Ciebie bezpłatna, poufna pomoc, która nigdy nic nie kosztuje.",
  "legal_help_title": "Free help where you are",
  "legal_free": "Free",
  "collect_signpost": "Jeśli dług jest w windykacji lub sądzie, bezpłatna pomoc może wkroczyć po Twojej stronie — otwórz Przewodnik po ochronie prawnej.",
  "h_aria_menu": "Menu",
