  "h_hero_eyebrow": "90-DAY PLAN · Zawsze bezpłatnie",
  "h_hero_h1": "Zasługujesz na to, by zobaczyć dokładnie, gdzie jesteś ze swoimi długami — jasność, jakiej nikt inny nie daje Ci <span class=\"g\">za darmo</span>.",
  "h_promise": "To nie jest plan taki sam dla wszystkich. Jest zbudowany pod Twoją sytuację i Twoje dokładne liczby — i nikt tutaj nie ocenia, jak do tego doszło.",
  "h_cta_build": "Zbuduj mój 90-Day Plan",
  "h_cta_note": "Zajmuje około 2 minut. Bez karty płatniczej, bez subskrypcji. Zawsze bezpłatnie.",
  "h_trust_1_n": "Bezpłatne",
  "h_trust_1_l": "Zawsze. Bez sztuczek.",
  "h_trust_2_n": "90",
  "h_trust_2_l": "Dniowy plan działania, wokół Twoich liczb.",
  "h_trust_3_n": "Lokalne",
  "h_trust_3_l": "Wsparcie w Twoim kraju.",
  "h_trust_4_n": "42",
  "h_trust_4_l": "Objętych krajów.",
  "h_eco_label": "Pełna droga",
  "h_eco_title": "Prawdziwe wyjście z długów to więcej niż jeden plan.",
  "h_eco_q1": "To droga — od zrozumienia, gdzie dziś stoisz, przez aktywne wychodzenie z długów, aż po zarabianie więcej i budowanie czegoś trwałego.",
  "h_eco_q2": "<strong>Nikt nie każe Ci widzieć całych schodów.</strong> Debt-Free.World idzie tą drogą z Tobą, etap po etapie — zaczynając od tego, który nic nie kosztuje.",
  "h_eco_p1_label": "Etap 01 · 90-Day Plan",
  "h_eco_p1_h": "Zrozum",
  "h_eco_p1_p": "Cała Twoja sytuacja, jasno odwzorowana.",
  "h_eco_p1_tag": "Tu zaczynasz",
