  "dfd_saved": "To je zhruba {amt} méně na úrocích",
  "dfd_saved_floor": "Nejméně {amt} méně na úrocích — nejspíš víc, až budou vyplněné všechny úroky",
  "dfd_date_approx": "Za předpokladu nulového úroku — tvé skutečné datum je nejspíš pozdější",
  "dfd_rate_why": "Toto datum vynechává úroky, protože zatím není uložená žádná úroková sazba. Právě úroky obvykle dělají malý přídavek tak účinným — přidej svou sazbu, ať vidíš skutečné datum a kolik úroků každá platba navíc umaže.",
  "dfd_rate_partial": "Některé dluhy nemají uloženou úrokovou sazbu, takže se tu počítají jako 0 %. Skutečná čísla jsou lepší, než ukazujeme — přidej chybějící sazby, ať je vidíš.",
  "dfd_rate_cta": "Uprav svůj plán",
  "dfd_stabilise": "Tvé náklady momentálně převyšují příjmy, takže datum splacení zatím neexistuje. Prvním cílem je nadechnout se — začni Krizovým rozpočtem.",
  "dfd_buffer_first": "Než přídavek půjde na dluh: rezerva {gap} znamená, že nečekaný účet se nezmění v nový dluh.",
  "strat_snow": "Sněhová koule",
  "strat_aval": "Lavina",
  "strat_first": "Splať tohle první",
  "strat_snow_note": "Nejmenší zůstatek první. Rychlá vítězství dávají rozjezd — silné, když je nejtěžší vůbec začít.",
  "strat_aval_note": "Nejvyšší úrok první. Z dlouhodobého hlediska nejlevnější — silné, když tě drahý dluh vyčerpává.",
  "strat_empty": "Přidej své dluhy během onboardingu a porovnej strategie vedle sebe.",
  "strat_unknown": "úrok neznámý",
  "strat_snow_why": "U tebe to začíná u {target} — tvého nejmenšího zůstatku.",
  "strat_aval_why": "U tebe to začíná dluhem {target} — nejvyšší sazbou, kterou máš.",
  "tool_intro_dfd": "Tohle promění tvá skutečná čísla v jedno datum — den, kdy můžeš být volný. Pak ukáže, o kolik dřív by ho přiblížila i malá platba navíc.",
  "tool_intro_strat": "Neexistuje jeden „správný“ způsob, jak splatit dluh — je jich několik osvědčených. Tohle ti ukáže dva vedle sebe a který sedí tvé situaci. Žádný žargon, jen tvá čísla.",
  "tool_intro_budget": "Než cokoli půjde na dluh, tvůj život je na prvním místě. Tohle rozepíše, co je nezbytné, a pak ti poctivě ukáže, kolik zbývá na to, co dlužíš.",
  "tool_intro_income": "Nemusíš zdvojnásobit příjem, abys změnil svůj časový plán. Tohle ukáže, o kolik dřív bys byl volný za každou trošku navíc, kterou dokážeš vydělat.",
  "tool_intro_collect": "Ne každý dluh je stejně naléhavý a brát je všechny stejně je vyčerpávající. Tohle ty tvé seřadí podle toho, co teď opravdu potřebuje pozornost — aby ses mohl nadechnout.",
  "tool_intro_legal": "Máš víc práv, než ti nejspíš řekli. Tohle srozumitelně vysvětlí ochranu tam, kde žiješ, aby na tebe nikdo nemohl tlačit věcmi, které nejsou pravda.",
  "nav_g_debtfree_sub": "Vše, co potřebuješ, abys jasně viděl svou situaci a naplánoval cestu ven.",
  "nav_g_tools_sub": "Šest kalkulaček. Každá odpoví na jednu skutečnou otázku o tvých penězích.",
  "nav_g_learn_sub": "Krátká, upřímná čtení — žádná vata, nic na prodej.",
  "nav_g_recovery_sub": "Až budeš připravený, hlubší nástroje k obraně a k obnově.",
  "strat_cmp_title": "Tvé dvě cesty vedle sebe",
