  "strat_cmp_verdict_aval": "Při tvých číslech ti Lavina ušetří zhruba {save} a splatí všechno přibližně o {months} měsíců dřív. Pokud tě žene sledovat, jak celkové náklady klesají, začni tady.",
  "strat_cmp_verdict_snow": "Při tvých číslech tyhle dvě skončí blízko sebe. Sněhová koule splatí tvůj první dluh za {first} měsíců — to rané vítězství stojí celkově jen zhruba {extra} navíc. Pokud tě žene rozjezd, začni tady.",
  "strat_cmp_approx": "Orientační odhad: předpokládá, že každá volná část tvého rozpočtu jde na dluhy po pořádku. Tvé skutečné pořadí plateb a případné minimální splátky to můžou posunout.",
  "strat_cmp_needsurplus": "Jakmile ti každý měsíc něco zbude, tohle ti ukáže obě cesty i tu, která tě osvobodí dřív. Zatím je pořadí níže pořád chytré místo, kde začít.",
