  "mf_dl_h": "Hoia oma plaan alles",
  "mf_dl_note": "Üks fail, milles on su plaan, selle koostamise kuupäev ja tasuta teenused su riigis. See avaneb igas seadmes, töötab ilma internetita ja kuulub sulle.",
  "mf_dl_btn": "Laadi mu plaan alla",
  "mf_dl_ok": "Salvestatud. Nüüd on see sinu.",
  "mf_dl_err": "Me ei suutnud praegu su faili koostada. Proovi hetke pärast uuesti — midagi pole kadunud.",
  "mf_x_created": "Koostatud",
  "mf_x_plan_h": "Sinu plaan",
  "mf_x_repeat": "Me ei asenda neid teenuseid. Oleme tehtud selleks, et meid nende kõrval kasutada.",
  "mf_x_del90": "90. päeval kustutame su plaani, su vastused, su dokumendid ja kõik isikliku, mis nende sees on. Meie teenusesse ei jää sinust midagi. Su plaan on sinu oma ja töötab ka ilma meieta.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "Kui elu ootamatult muutub",
  "crisis_lead": "Ootamatu muutus ei kustuta seda, mille oled juba saavutanud. Vali see, mis on su olukorrale kõige lähemal — iga plaan algab ühest või kahest asjast, mis täna kõige rohkem loevad, ja liigub sealt edasi selleni, kuidas saada jalgealune taas kindlaks.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Koosta kiri võlausaldajale",
  "crisis_act_support": "Leia kinnitatud abi seal, kus sa oled",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "See on üldine juhis, mitte õigus- ega meditsiininõu. Kõiges, mis puudutab just sinu olukorda, toetu Tugi-osa tasuta teenustele ja, kui see on oluline, pädevale spetsialistile.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "Sissetuleku kaotamine on hirmutav, aga liikumisruumi on rohkem, kui praegu tundub. Midagi ei pea täna ära lahendama — ainult alustama.",
  "crisis_jobloss_i1": "Kaitse esmalt hädavajalikku. Enne ühtegi tagatiseta võlga veendu, et eluase, toit, kommunaalkulud ja töö leidmiseks vajalik transport on kaetud. Need käivad kaardi- ja laenumaksete ees.",
  "crisis_jobloss_i2": "Räägi võlausaldajatele enne, kui makse hilineb. Lühike ja aus sõnum sellest, et su sissetulek on muutunud, avab ukse maksepausile või väiksemale maksele — ja seda on palju lihtsam kokku leppida enne, kui võlgnevusteade saabub.",
  "crisis_jobloss_i3": "Uuri välja, millele sul on õigus. Töökohtade vahel olles võib olla tuge, mida saad taotleda. Su riigi kinnitatud teenused oskavad öelda täpselt, mis sinu kohta kehtib.",
  "crisis_jobloss_s1": "Ehita eelarve uuesti üles oma uue, väiksema sissetuleku ümber — praegu ainult hädavajalik, kõik muu pausile, kuni olukord rahuneb.",
  "crisis_jobloss_s2": "Võta iga ajutine kokkulepe võlausaldajaga kirjalikult, et raske kuu ei muutuks vaikselt maksehäireks.",
  "crisis_jobloss_s3": "Ära võta uut võlga vana katteks. Laenamine laenuandjale maksmiseks ainult süvendab auku — siinsed plaanid ja tööriistad on tehtud toimima ilma selleta.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "Kui su tervis vajab tähelepanu, muudavad rahamured kõik veelgi raskemaks. Sinu paranemine tuleb esimesena — see plaan hoiab ära, et rahaline pool koormat juurde lisaks.",
  "crisis_illness_i1": "Kaitse esmalt hädavajalikku. Eluase, toit, kommunaalkulud ja kõik, mida oma ravi jaoks vajad, käivad iga tagatiseta võla makse ees.",
  "crisis_illness_i2": "Anna võlausaldajatele teada, et su olukord on muutunud. Sa ei võlgne kellelegi oma terviseandmeid — ainult seda, et su sissetulek või töövõime on muutunud ja et palud ajutist makseraskuste kokkulepet.",
  "crisis_illness_i3": "Taotle seda, millele sul on õigus. Võib olla haigushüvitis või muu tugi, mille tingimustele sa vastad. Su riigi kinnitatud teenused juhatavad sind õigesse kohta — ja tervise poole pealt toetu palun meditsiinitöötajatele.",
  "crisis_illness_s1": "Kärbi eelarve hädavajalikuni, kuni su sissetulek on väiksem, ja vaata see olukorra muutudes uuesti üle.",
  "crisis_illness_s2": "Pane iga kokkulepe võlausaldajaga kirja ja hoia koopia alles — üks asi vähem peas hoida.",
  "crisis_illness_s3": "Ära laena olemasoleva võla katteks. Palu selle asemel aega; enamik võlausaldajaid ootab palju meelsamini, kui surub sind veelgi kitsamasse seisu.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Ühise elu lahtiharutamine on juba niigi raske, ilma et rahaasjad seda uduseks teeksid. Võta üks selge samm korraga — sul pole vaja sel nädalal kõiki vastuseid.",
  "crisis_sep_i1": "Kaitse esmalt hädavajalikku, endale ja kõigile, kes sinust sõltuvad. Eluase, toit ja kommunaalkulud käivad tagatiseta võla ees.",
  "crisis_sep_i2": "Võta ühiste võlgade asjus võlausaldajatega varakult ühendust. Küsi, millised on su võimalused, ja võta iga muudatus kirjalikult. Kui võlg on mõlema nimel, pea arvestust selle üle, milles on kokku lepitud.",
  "crisis_sep_i3": "Uuri välja, millist tuge saad taotleda, kui su leibkond muutub. Su riigi kinnitatud teenused oskavad öelda, mis kehtib — ja ühiste võlgade juriidilise poole pealt on õige koht riiklik tasuta võlaabi või pädev nõustaja.",
  "crisis_sep_s1": "Ehita eelarve uuesti üles oma enda sissetuleku ja kulude ümber, ühe inimese leibkonnana.",
  "crisis_sep_s2": "Kus saad, lahuta rahaasjad samm-sammult ja pea iga kokkuleppe kohta kirjalikku arvestust.",
  "crisis_sep_s3": "Ära võta üleminekut pehmendamaks uut võlga. Stabiilsed, ausad kokkulepped kaitsevad sind palju paremini kui laenamine.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "Ootamatu kulu või vapustus võib plaani viltu lüüa. See ei kustuta seda, mille oled juba saavutanud — vaja on vaid rahulikku pausi ja üht selget järgmist sammu.",
  "crisis_emerg_i1": "Kata esmalt tõeliselt hädavajalik — turvalisus, eluase, toit, kommunaalkulud. Ühekordne hädaolukord ei ole hetk, mil panna kaardimakse ettepoole sellest, et tuled jääksid põlema.",
  "crisis_emerg_i2": "Kui hädaolukord tähendab, et mõni makse jääb tegemata, anna sellele võlausaldajale kohe teada ja palu lühikest maksepuhkust. Kavandatud paus on alati parem kui vaikiv vahelejätmine.",
  "crisis_emerg_i3": "Uuri, millist hädaabi sa kasutada saad. Su riigi kinnitatud teenused oskavad juhatada abi juurde, mille olemasolust sa ehk ei teagi.",
  "crisis_emerg_s1": "Kui vahetu vapustus on lahendatud, ehita puhver tasapisi uuesti üles — loeb isegi väike summa igal nädalal.",
  "crisis_emerg_s2": "Vaata eelarve uuesti üle ja kohanda plaani tulevateks nädalateks, mitte kohe terveks aastaks.",
  "crisis_emerg_s3": "Väldi augu täitmiseks kallist laenu. Lühike kokkulepe võlausaldajaga, kes sul juba on, maksab peaaegu alati vähem.",
  "ci_trend_title": "Your buffer, week by week",
  "ci_trend_empty": "Su trend kujuneb siia. Kirjuta paar nädalat üles ja näed, kuidas see kuju võtab.",
  "ci_title": "How did this week go?",
  "ci_lead": "Kiire sissekanne — ilma hukkamõistuta, ilma seeriata, mida katkestada. Lihtsalt märk sellest, kus sa sel nädalal oled.",
  "ci_buffer_lbl": "Raha, mis sel nädalal üle jäi",
