  "dfd_saved": "See on umbes {amt} vähem intressi",
  "dfd_saved_floor": "Vähemalt {amt} vähem intressi — tõenäoliselt rohkem, kui kõik intressimäärad on täidetud",
  "dfd_date_approx": "Eeldusel, et intressi pole — su tegelik kuupäev on tõenäoliselt hilisem",
  "dfd_rate_why": "See kuupäev jätab intressi arvestamata, sest ühtegi intressimäära pole veel salvestatud. Just intress teeb väikesegi lisamakse nii mõjusaks — lisa oma intressimäär, et näha tegelikku kuupäeva ja seda, kui palju intressi iga lisamakse ära tasub.",
  "dfd_rate_partial": "Mõnel võlal pole intressimäära salvestatud, seega arvestatakse neid siin 0%-na. Tegelikud arvud on paremad kui näidatud — lisa puuduvad intressimäärad, et neid näha.",
