  "strat_aval_why": "Sinu puhul algab see su {target} võlast — kõrgeim intress, mis sul on.",
  "tool_intro_dfd": "See muudab su päris numbrid üheks kuupäevaks — päevaks, mil võiksid vaba olla. Seejärel näitab, kui palju varem tooks selle juba väikegi lisamakse.",
  "tool_intro_strat": "Võlgade tasumiseks ei ole üht „õiget“ viisi — on mõned tõestatud viisid. See näitab sulle kahte kõrvuti ja seda, kumb sobib su olukorraga. Ilma erialažargoonita, ainult su numbrid.",
  "tool_intro_budget": "Enne kui midagi läheb võla peale, tuleb su elu esimesena. See paneb paika, mis on hädavajalik, ja näitab siis ausalt, mis jääb selle katteks, mida sa võlgned.",
  "tool_intro_income": "Sa ei pea oma ajakava muutmiseks sissetulekut kahekordistama. See näitab, kui palju varem oleksid vaba iga väikesegi lisa eest, mille suudad juurde tuua.",
  "tool_intro_collect": "Kõik võlad ei ole ühtviisi kiireloomulised ja kõigi kohtlemine ühtemoodi on kurnav. See järjestab sinu omad selle järgi, mis vajab praegu tõesti tähelepanu — et saaksid hingata.",
  "tool_intro_legal": "Sul on rohkem õigusi, kui sulle on ilmselt räägitud. See paneb lihtsas keeles kirja kaitse, mis kehtib seal, kus sa elad, et keegi ei saaks sind survestada asjadega, mis pole tõsi.",
  "nav_g_debtfree_sub": "Kõik, mida vajad, et näha oma olukorda selgelt ja planeerida oma tee välja.",
  "nav_g_tools_sub": "Kuus kalkulaatorit. Igaüks vastab ühele päris küsimusele su raha kohta.",
  "nav_g_learn_sub": "Lühikesed, ausad lugemispalad — ilma täitesisuta, midagi pole vaja osta.",
  "nav_g_recovery_sub": "Kui oled valmis, sügavamad tööriistad vastu astumiseks ja uuesti ülesehitamiseks.",
