  "h_sales_p": "Alustamiseks ei vaja sa rahandusharidust ega kõrget sissetulekut — vaid oma päris numbreid ja kaks minutit. Täiesti tasuta, ilma midagi kaotamata.",
  "h_sales_btn": "Loo mu plaan kohe",
  "h_sales_fine": "Ilma tellimuseta. Ilma peidetud tasudeta. Ainult selgus.",
  "h_proof_title": "Nende endi sõnadega — varsti",
  "h_proof_body": "Oleme uued ja näitame sulle pigem tühjust kui arvustusi, mille ise kirjutasime. Kui päris inimesed jagavad, kuidas see neil läks, leiavad nende sõnad siin oma koha — vaid selle osa nimest, mille nad ise anda soovivad. Seni on ainus tõend, mida pakume, plaan, mille sulle ehitame.",
  "h_faq_label": "Korduvad küsimused",
  "h_faq_q1": "Kas see on tõesti tasuta?",
  "h_faq_a1": "Jah. 90-päevane võlaplaan ja kõik 90-Day Plan tööriistad on tasuta — ilma maksekaardita, ilma peidetud kuludeta, ilma ajapiiranguta. 90-Day Companion (19€, ühekordne) on valikuline täiendus.",
  "h_faq_q2": "Kas mul on vaja maksekaarti?",
  "h_faq_a2": "Ei. Tasuta plaan maksekaarti ei nõua. Ainult 90-Day Companion (19€ ühekordne) nõuab makset — Stripe'i kaudu, turvaline kassa.",
  "h_faq_q3": "Kas keegi helistab mulle?",
  "h_faq_a3": "Ei. Me ei helista kunagi. Su plaan toimetatakse e-postiga. Kogu suhtlus toimub su enda tingimustel.",
