  "h_faq_a4": "Su andmeid kasutatakse ainult plaani loomiseks ja oluliste uuenduste saatmiseks. Me ei müü andmeid kunagi.",
  "h_faq_q5": "Millised riigid on toetatud?",
  "h_faq_a5": "Kohalik tugi ja seaduslikud õigused kohandatud su riigi järgi — liides täna inglise ja soome keeles, lisakeeled tulekul.",
