  /* ── Free path 19.8 · signup-free (sf_*) + free plan export (mf_*) ── */
  "sf_doc_title": "Saņemt manu bezmaksas plānu — Debt-Free.World",
  "sf_doc_desc": "Izveido savu 90-Day Plan kontu. Bez maksājumu kartes. Bez abonementa. Tavs personalizētais plāns skaidrībai par parādiem, bez maksas — un glabāts 90 dienas.",
  "sf_h1": "Tava skaidrība sākas šeit.",
  "sf_sub": "Ievadi savu e-pastu, un tu uzreiz nonāksi pie sava plāna veidošanas. Bez maksājumu kartes. Bez abonementa. Lielākā daļa pabeidz mazāk nekā 5 minūtēs — velti tam tik daudz laika, cik tev vajag.",
