  "sf_foot_legal": "Privātums un noteikumi",
  "mf_dl_h": "Saglabā savu plānu",
  "mf_dl_note": "Viens fails ar tavu plānu, tā izveides datumu un bezmaksas pakalpojumiem tavā valstī. Tas atveras jebkurā ierīcē, darbojas bez interneta un pieder tev.",
