  "mf_x_created": "Izveidots",
  "mf_x_plan_h": "Tavs plāns",
  "mf_x_repeat": "Mēs neaizstājam šos pakalpojumus. Esam veidoti tā, lai mūs izmantotu tiem līdzās.",
  "mf_x_del90": "90. dienā mēs dzēšam tavu plānu, tavas atbildes, tavus dokumentus un visu personisko, kas tajos ir. Nekas no tava nepaliek mūsu pakalpojumā. Tavs plāns ir tavs un darbojas arī bez mums.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "Kad dzīve pēkšņi mainās",
  "crisis_lead": "Pēkšņas pārmaiņas neizdzēš tavu līdzšinējo progresu. Izvēlies to, kas ir vistuvāk tavai situācijai — katrs plāns sākas ar vienu vai divām lietām, kas šodien ir vissvarīgākās, un tad ar to, kā nostiprināt zemi zem kājām.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Sagatavot vēstuli kreditoram",
  "crisis_act_support": "Atrast pārbaudītu palīdzību tur, kur esi",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "Šie ir vispārīgi norādījumi, nevis juridiska vai medicīniska konsultācija. Visā, kas attiecas tieši uz tavu situāciju, balsties uz bezmaksas pakalpojumiem sadaļā Atbalsts un, kur tas ir svarīgi, uz kvalificētu speciālistu.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "Ienākumu zaudēšana biedē, bet tev ir vairāk rīcības brīvības, nekā šobrīd šķiet. Šodien nekas nav jāatrisina — tikai jāsāk.",
  "crisis_jobloss_i1": "Vispirms nodrošini pašu nepieciešamāko. Pirms jebkura nenodrošinātā parāda pārliecinies, ka ir segts mājoklis, pārtika, komunālie pakalpojumi un transports, kas tev vajadzīgs darba meklējumos. Tas nāk pirms kartes vai aizdevuma maksājumiem.",
  "crisis_jobloss_i2": "Pastāsti kreditoriem, pirms nokavē maksājumu. Īsa, godīga ziņa par to, ka tavi ienākumi ir mainījušies, paver durvis uz pauzi vai mazāku maksājumu — un to ir daudz vieglāk sarunāt, pirms pienāk vēstule par kavētu maksājumu.",
  "crisis_jobloss_i3": "Noskaidro, kas tev pienākas. Iespējams, ir atbalsts, ko vari pieprasīt laikā starp diviem darbiem. Pārbaudītie pakalpojumi tavā valstī var pateikt tieši to, kas attiecas uz tevi.",
  "crisis_jobloss_s1": "Pārbūvē budžetu ap saviem jaunajiem, mazākajiem ienākumiem — pagaidām tikai pats nepieciešamākais, viss pārējais apturēts, līdz situācija nostabilizējas.",
  "crisis_jobloss_s2": "Jebkuru pagaidu vienošanos ar kreditoru noformē rakstiski, lai grūts mēnesis klusi nepārvērstos par saistību neizpildi.",
  "crisis_jobloss_s3": "Neuzņemies jaunu parādu, lai segtu veco. Aizņemties, lai samaksātu aizdevējam, nozīmē tikai padziļināt bedri — plāni un rīki šeit ir veidoti tā, lai darbotos bez tā.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "Kad tava veselība prasa uzmanību, raizes par naudu padara visu smagāku. Tava atveseļošanās ir pirmajā vietā — šis plāns rūpējas, lai finanšu puse nepieliktu vēl vairāk sloga.",
  "crisis_illness_i1": "Vispirms nodrošini pašu nepieciešamāko. Mājoklis, pārtika, komunālie pakalpojumi un viss, kas vajadzīgs tavai aprūpei, nāk pirms jebkura nenodrošinātā parāda maksājuma.",
  "crisis_illness_i2": "Dari kreditoriem zināmu, ka tava situācija ir mainījusies. Tev nevienam nav jāatklāj sava medicīniskā informācija — tikai tas, ka tavi ienākumi vai spējas ir mainījušās un ka tu lūdz pagaidu vienošanos par atvieglojumiem.",
  "crisis_illness_i3": "Pieprasi to, kas tev pienākas. Iespējams, tev pienākas slimības nauda vai cits atbalsts. Pārbaudītie pakalpojumi tavā valstī norādīs tev pareizo vietu — un veselības jautājumos, lūdzu, balsties uz mediķiem.",
  "crisis_illness_s1": "Kamēr tavi ienākumi ir samazināti, sašaurini budžetu līdz pašam nepieciešamākajam un pārskati to, situācijai mainoties.",
  "crisis_illness_s2": "Jebkuru vienošanos ar kreditoru noformē rakstiski un saglabā kopiju — par vienu lietu mazāk, kas jāpatur prātā.",
  "crisis_illness_s3": "Neaizņemies, lai segtu esošo parādu. Tā vietā lūdz laiku; vairums kreditoru daudz labprātāk pagaidīs, nekā spiedīs tevi tālāk.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Kopīgas dzīves atšķetināšana ir pietiekami grūta arī bez naudas miglas. Ej pa vienam skaidram solim — tev nav vajadzīgas visas atbildes jau šonedēļ.",
  "crisis_sep_i1": "Vispirms nodrošini pašu nepieciešamāko sev un ikvienam, kas ir no tevis atkarīgs. Mājoklis, pārtika un komunālie pakalpojumi nāk pirms nenodrošinātā parāda.",
  "crisis_sep_i2": "Par jebkuriem kopīgiem parādiem sazinies ar kreditoriem savlaicīgi. Pajautā, kādas ir tavas iespējas, un katru izmaiņu noformē rakstiski. Ja parāds ir uz abiem vārdiem, saglabā pierakstus par to, kas ir norunāts.",
  "crisis_sep_i3": "Noskaidro, kādu atbalstu vari pieprasīt, mainoties tavai mājsaimniecībai. Pārbaudītie pakalpojumi tavā valstī var pateikt, kas uz tevi attiecas — bet kopīgo parādu juridiskajā pusē pareizā vieta, kur vērsties, ir nacionālā bezmaksas parādu palīdzība vai kvalificēts konsultants.",
  "crisis_sep_s1": "Pārbūvē budžetu ap saviem ienākumiem un izmaksām kā vienas personas mājsaimniecībā.",
  "crisis_sep_s2": "Kur vari, nodali finanses soli pa solim, saglabājot rakstiskus pierakstus par katru vienošanos.",
  "crisis_sep_s3": "Neuzņemies jaunu parādu, lai atvieglotu pāreju. Stabilas, godīgas vienošanās aizsargā tevi daudz labāk nekā aizņemšanās.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "Negaidītas izmaksas vai trieciens var novirzīt plānu no sliedēm. Tas neizdzēš tavu līdzšinējo progresu — vajadzīga tikai mierīga pauze un viens skaidrs nākamais solis.",
  "crisis_emerg_i1": "Vispirms sedz pašu nepieciešamāko — drošību, mājokli, pārtiku, komunālos pakalpojumus. Vienreizēja ārkārtas situācija nav brīdis, kad kartes maksājumu likt augstāk par to, lai mājās degtu gaisma.",
  "crisis_emerg_i2": "Ja ārkārtas situācijas dēļ tu nokavēsi maksājumu, pasaki to attiecīgajam kreditoram jau tagad un lūdz īsas maksājumu brīvdienas. Plānota pauze vienmēr ir labāka nekā kluss kavējums.",
  "crisis_emerg_i3": "Noskaidro, vai ir kāds ārkārtas atbalsts, ko vari izmantot. Pārbaudītie pakalpojumi tavā valstī var norādīt uz palīdzību, par kuras esamību tu varbūt nezini.",
  "crisis_emerg_s1": "Kad pirmais trieciens ir pārvarēts, lēnām atjauno savu drošības spilvenu — svarīga ir pat neliela summa katru nedēļu.",
  "crisis_emerg_s2": "Pārskati budžetu un pielāgo plānu tuvākajām nedēļām, nevis uzreiz visam gadam.",
  "crisis_emerg_s3": "Izvairies no dārgas aizņemšanās, lai nosegtu iztrūkumu. Īsa vienošanās ar kreditoru, kas tev jau ir, gandrīz vienmēr izmaksā mazāk.",
  "ci_trend_title": "Your buffer, week by week",
  "ci_trend_empty": "Šeit veidosies tava tendence. Ieraksti pāris nedēļas, un redzēsi, kā tā iegūst formu.",
  "ci_title": "How did this week go?",
  "ci_lead": "Ātrs pieraksts — bez nosodījuma, bez sērijas, ko pārtraukt. Vienkārši atzīme par to, kur esi šonedēļ.",
  "ci_buffer_lbl": "Nauda, kas tev šonedēļ palika pāri",
