  "dfd_saved_floor": "Vismaz {amt} mazāk procentos — visticamāk vairāk, kad būs ievadītas visas procentu likmes",
  "dfd_date_approx": "Pieņemot, ka procentu nav — tavs īstais datums visdrīzāk būs vēlāks",
  "dfd_rate_why": "Šis datums neņem vērā procentus, jo pagaidām nav saglabāta neviena procentu likme. Tieši procenti parasti padara nelielu papildu maksājumu tik iedarbīgu — pievieno savu likmi, lai redzētu īsto datumu un to, cik daudz procentu nokārto katrs papildu maksājums.",
  "dfd_rate_partial": "Dažiem parādiem nav saglabāta procentu likme, tāpēc šeit tie tiek rēķināti kā 0%. Patiesie skaitļi ir labāki nekā parādītie — pievieno trūkstošās likmes, lai tos redzētu.",
  "dfd_rate_cta": "Rediģēt savu plānu",
  "dfd_stabilise": "Tavas izmaksas pašlaik pārsniedz ienākumus, tāpēc atmaksas datuma vēl nav. Pirmais mērķis ir elpas vieta — sāc ar Krīzes budžetu.",
  "dfd_buffer_first": "Pirms papildu nauda aiziet parādam: {gap} liels spilvens nozīmē, ka negaidīts rēķins nepārvērtīsies jaunā parādā.",
