  "strat_unknown": "procentu likme nezināma",
  "strat_snow_why": "Tavā gadījumā tas sākas ar {target} — tavu mazāko atlikumu.",
  "strat_aval_why": "Tavā gadījumā tas sākas ar tavu {target} parādu — augstāko likmi, kāda tev ir.",
  "tool_intro_dfd": "Tas pārvērš tavus patiesos skaitļus vienā datumā — dienā, kad vari būt brīvs. Pēc tam tas parāda, cik daudz agrāk to pietuvinātu pat neliels papildu maksājums.",
  "tool_intro_strat": "Nav viena „pareizā“ veida, kā nokārtot parādus — ir vairāki pārbaudīti. Tas parāda tev divus blakus un to, kurš der tavai situācijai. Bez žargona, tikai tavi skaitļi.",
  "tool_intro_budget": "Pirms kaut kas aiziet parādam, pirmajā vietā ir tava dzīve. Tas izklāsta, kas ir nepieciešamākais, un tad godīgi parāda, cik paliek tam, ko esi parādā.",
  "tool_intro_income": "Tev nav jādubulto ienākumi, lai mainītu savu grafiku. Tas parāda, cik daudz agrāk būtu brīvs ar katru papildu ienākumu, ko spēj radīt.",
  "tool_intro_collect": "Ne katrs parāds ir vienlīdz steidzams, un izturēties pret visiem vienādi ir nogurdinoši. Tas sakārto tavējos pēc tā, kam patiešām tagad nepieciešama uzmanība — lai tu varētu atvilkt elpu.",
  "tool_intro_legal": "Tev ir vairāk tiesību, nekā tev, visticamāk, ir stāstīts. Tas vienkāršā valodā izklāsta aizsardzību, kas ir spēkā tur, kur dzīvo, lai neviens nevarētu tevi spiest ar lietām, kas nav patiesas.",
  "nav_g_debtfree_sub": "Viss, kas vajadzīgs, lai skaidri redzētu savu situāciju un ieplānotu ceļu ārā.",
  "nav_g_tools_sub": "Seši kalkulatori. Katrs atbild uz vienu īstu jautājumu par tavu naudu.",
  "nav_g_learn_sub": "Īsi, godīgi raksti — bez liekvārdības, nekā, ko pirkt.",
  "nav_g_recovery_sub": "Kad esi gatavs, dziļāki rīki, lai pretotos un atjaunotos.",
