  "strat_cmp_verdict_snow": "Ar taviem skaitļiem šie divi finišē tuvu viens otram. Sniega bumba nokārto tavu pirmo parādu {first} mēnešos — šī agrīnā uzvara kopumā izmaksā tikai apmēram {extra} vairāk. Ja tevi uztur gaitā spars, sāc ar šo.",
  "strat_cmp_approx": "Orientējošs novērtējums: tajā pieņemts, ka katra brīvā tava budžeta daļa pēc kārtas aiziet taviem parādiem. Tava patiesā maksājumu secība un iespējamie minimālie maksājumi to var izmainīt.",
  "strat_cmp_needsurplus": "Kad katru mēnesi paliks nauda pāri, tas parādīs abus ceļus un to, kurš tevi atbrīvo ātrāk. Pagaidām zemāk redzamā secība joprojām ir gudra vieta, ar ko sākt.",
