  "h_pf_eyebrow": "90-DAY PLAN · 0€ mūžīgi",
  "h_pf_title": "Tavs pilnīgais sākumpunkts.",
  "h_pf_lead": "Lielākā daļa cilvēku pavada mēnešus, minot, ko darīt ar parādu — izvairoties no vēstulēm, izvairoties no skaitļiem, izvairoties no visas tēmas. Tas aizstāj minēšanu ar pārliecību, apmēram divās minūtēs, bez maksas.",
