  "h_pf_price": "19€ vienreiz · bez abonementa",
  "h_pf_side_title": "Zināt plānu un dzīvot pēc tā ir divas dažādas lietas.",
  "h_pf_side_p": "90-Day Companion ir 90 dienu pavadonis, kas pārvērš tavu plānu ikdienas darbībā — veidots brīžiem, caur kuriem tavs bezmaksas plāns nevar tevi izvest.",
  "h_pf_feat1": "Gatavas vēstuļu veidnes kreditoriem",
  "h_pf_feat3": "Patiess atbalsts grūtos brīžos",
  "h_pf_link": "Skaties, kā darbojas 90-Day Companion →",
  "h_sales_title": "Beidz to nest viens. Iegūsti skaidru plānu jau šodien.",
  "h_sales_p": "Lai sāktu, tev nav vajadzīga finanšu izglītība vai augsti ienākumi — tikai tavi patiesie skaitļi un divas minūtes. Pilnīgi bez maksas, neko neriskējot.",
  "h_sales_btn": "Ģenerēt manu plānu tagad",
  "h_sales_fine": "Bez abonementa. Bez slēptām maksām. Tikai skaidrība.",
  "h_proof_title": "Viņu pašu vārdiem — drīz",
  "h_proof_body": "Mēs esam jauni un labāk parādīsim tev neko, nekā parādīsim atsauksmes, ko paši uzrakstījām. Kad īsti cilvēki dalīsies, kā viņiem gāja, viņu vārdi atradīs šeit savu vietu — tikai ar to vārda daļu, ko viņi paši vēlas dot. Līdz tam vienīgais pierādījums, ko piedāvājam, ir plāns, ko tev izveidosim.",
  "h_faq_label": "Bieži uzdotie jautājumi",
  "h_faq_q1": "Vai tas tiešām ir bez maksas?",
  "h_faq_a1": "Jā. 90 dienu parādu plāns un visi 90-Day Plan rīki ir bez maksas — bez maksājumu kartes, bez slēptām izmaksām, bez laika ierobežojuma. 90-Day Companion (19€, vienreizējs) ir izvēles papildinājums.",
  "h_faq_q2": "Vai man vajadzīga maksājumu karte?",
  "h_faq_a2": "Nē. Bezmaksas plānam maksājumu karte nav vajadzīga. Tikai 90-Day Companion (19€ vienreizējs) prasa maksājumu — caur Stripe, droša kase.",
  "h_faq_q3": "Vai man kāds zvanīs?",
  "h_faq_a3": "Nē. Mēs nekad nezvanām. Tavs plāns tiek piegādāts e-pastā. Visa saziņa notiek pēc taviem noteikumiem.",
  "h_faq_q4": "Kā jūs izmantojat manus datus?",
  "h_faq_a4": "Tavi dati tiek izmantoti tikai plāna izveidei un būtisku atjauninājumu sūtīšanai. Mēs nekad nepārdodam datus.",
  "h_faq_q5": "Kuras valstis tiek atbalstītas?",
  "h_faq_a5": "Vietējais atbalsts un likumīgās tiesības pielāgotas tavai valstij — saskarne šodien angļu un somu valodā, vairāk valodu drīzumā.",
  "h_faq_more": "Skatīt visus jautājumus →",
  "h_final_q": "Vai tas viens parāds joprojām nav atrisināts?",
  "h_final_btn": "Izveidot manu plānu, bez maksas",
