  "dfd_saved_floor": "Bent {amt} mažiau palūkanų — tikriausiai daugiau, kai bus įvestos visos palūkanų normos",
  "dfd_date_approx": "Darant prielaidą, kad palūkanų nėra — tavo tikroji data tikriausiai vėlesnė",
  "dfd_rate_why": "Ši data neįskaičiuoja palūkanų, nes dar neišsaugota jokia palūkanų norma. Būtent palūkanos paprastai daro nedidelį priedą tokį galingą — įvesk savo palūkanų normą, kad pamatytum tikrąją datą ir kiek palūkanų padengia kiekvienas papildomas mokėjimas.",
  "dfd_rate_partial": "Kai kurioms skoloms neišsaugota palūkanų norma, todėl čia jos skaičiuojamos kaip 0 %. Tikrieji skaičiai geresni, nei rodoma — įvesk trūkstamas normas, kad juos pamatytum.",
  "dfd_rate_cta": "Redaguoti savo planą",
  "dfd_stabilise": "Tavo išlaidos šiuo metu viršija pajamas, todėl grąžinimo datos dar nėra. Pirmasis tikslas yra atokvėpis — pradėk nuo Krizės biudžeto.",
  "dfd_buffer_first": "Prieš atiduodant priedą skolai: {gap} pagalvė reiškia, kad netikėta sąskaita nevirs nauja skola.",
  "strat_snow": "Sniego gniūžtė",
  "strat_aval": "Lavina",
  "strat_first": "Padenk šią pirmiausia",
  "strat_snow_note": "Mažiausias likutis pirmiausia. Greiti laimėjimai kuria pagreitį — galinga, kai sunkiausia apskritai pradėti.",
  "strat_aval_note": "Didžiausios palūkanos pirmiausia. Ilgainiui pigiausia — galinga, kai brangi skola tave sekina.",
  "strat_empty": "Pridėk savo skolas registracijos metu, kad palygintum strategijas greta.",
  "strat_unknown": "palūkanos nežinomos",
  "strat_snow_why": "Tau tai prasideda nuo {target} — tavo mažiausio likučio.",
  "strat_aval_why": "Tau tai prasideda nuo tavo {target} skolos — didžiausių palūkanų, kokias turi.",
  "tool_intro_dfd": "Tai paverčia tavo tikrus skaičius viena data — diena, kai galėtum būti laisvas. Tada parodo, kiek anksčiau ją priartintų net nedidelis papildomas mokėjimas.",
  "tool_intro_strat": "Nėra vieno „teisingo“ būdo grąžinti skolą — yra keli išbandyti. Čia matai du greta ir tai, kuris tinka tavo padėčiai. Jokio žargono, tik tavo skaičiai.",
  "tool_intro_budget": "Prieš skiriant ką nors skolai, tavo gyvenimas eina pirma. Čia išdėstoma, kas būtina, o tada sąžiningai parodoma, kiek lieka tam, ką esi skolingas.",
  "tool_intro_income": "Tau nereikia dvigubinti pajamų, kad pakeistum savo grafiką. Čia matai, kiek anksčiau būtum laisvas už kiekvieną papildomą sumą, kurią pavyks užsidirbti.",
  "tool_intro_collect": "Ne kiekviena skola vienodai skubi, o vienodas elgesys su jomis visomis sekina. Čia tavosios surikiuojamos pagal tai, kam iš tikrųjų dabar reikia dėmesio — kad galėtum atsikvėpti.",
  "tool_intro_legal": "Turi daugiau teisių, nei tau tikriausiai pasakė. Čia paprasta kalba išdėstoma, kokia apsauga galioja ten, kur gyveni, kad niekas negalėtų tavęs spausti tuo, kas netiesa.",
  "nav_g_debtfree_sub": "Viskas, ko reikia, kad aiškiai matytum savo padėtį ir suplanuotum išeitį.",
  "nav_g_tools_sub": "Šešios skaičiuoklės. Kiekviena atsako į vieną tikrą klausimą apie tavo pinigus.",
  "nav_g_learn_sub": "Trumpi, sąžiningi tekstai — jokio užpildo, nieko parduodamo.",
  "nav_g_recovery_sub": "Kai būsi pasiruošęs, gilesni įrankiai priešintis ir atsikurti.",
  "strat_cmp_title": "Du tavo keliai greta",
  "strat_cmp_snow": "Snowball",
  "strat_cmp_aval": "Avalanche",
