  "strat_cmp_verdict_aval": "Pagal tavo skaičius Lavina sutaupo tau apie {save} ir viską padengia maždaug {months} mėn. anksčiau. Jei tave veda pirmyn tai, kad matai krintančią bendrą kainą, pradėk nuo čia.",
  "strat_cmp_verdict_snow": "Pagal tavo skaičius šie du baigia beveik kartu. Sniego gniūžtė padengia tavo pirmą skolą per {first} mėn. — ta ankstyva pergalė iš viso kainuoja tik apie {extra} daugiau. Jei tave veda pirmyn pagreitis, pradėk nuo čia.",
  "strat_cmp_approx": "Apytikslis įvertinimas: daroma prielaida, kad kiekviena laisva biudžeto dalis eina skoloms iš eilės. Tavo tikra mokėjimų eilė ir minimalios įmokos gali tai pakeisti.",
  "strat_cmp_needsurplus": "Kai kas mėnesį liks pinigų, čia matysi abu kelius ir tai, kuris išlaisvina anksčiau. Kol kas žemiau esanti eilė vis tiek yra protinga vieta pradėti.",
