  "h_faq_label": "Dažni klausimai",
  "h_faq_q1": "Ar tai tikrai nemokama?",
  "h_faq_a1": "Taip. 90 dienų skolų planas ir visi 90-Day Plan įrankiai yra nemokami — be mokėjimo kortelės, be paslėptų išlaidų, be laiko apribojimo. 90-Day Companion (19€, vienkartinis) yra pasirenkamas papildymas.",
