  "sup_pub_country_label": "Tavo šalis",
  "sup_pub_country_choose": "— pasirink —",
  "sup_pub_country_other": "Mano šalies šiame sąraše nėra",
  "sup_pub_empty": "Beveik kiekvienoje šalyje yra organizacijų, kurios padeda su skolomis už tai neimdamos mokesčio — viešasis skolų konsultavimas, vartotojų institucijos ir labdaros organizacijos. Kurios iš jų yra, priklauso nuo to, kur gyveni, todėl šis sąrašas laukia tavo šalies, o ne ją spėlioja.",
  "sup_pub_verified": "Patikrinta",
  "sup_pub_verified_note": "Kiekviena čia esanti organizacija patikrinta pagal jos pačios nacionalinį šaltinį. Niekas šiame sąraše nėra sugeneruota.",
  "sup_pub_fees_note": "Kai paslauga yra nemokama, tai nurodyta jos aprašyme. Mes to neteigiame jų vardu.",
  "sup_pub_other_body": "Tai šaliai dar neturime patikrintų organizacijų, o nepatikrintos neįtraukiame. Jei parašysi adresu support@debt-free.world ir nurodysi savo šalį, ieškosime nacionalinės paslaugos ir ją pridėsime, kai tik ji bus patvirtinta.",
  "wtin_title": "Kas Debt-Free.World nėra",
  "wtin_lead": "Šis puslapis yra tam, kad niekam nereikėtų to atsekti iš rinkodaros. Penki dalykai, kurių šis produktas nedaro, ir trys, kuriuos daro.",
  "wtin_not_label": "Ko šis produktas nedaro",
  "wtin_not_1": "Jis niekam tavęs neatstovauja. Nei kreditoriui, nei teismui, nei institucijai. Tavo vardu niekas neteikiama, nesiunčiama ir nepasirašoma.",
  "wtin_not_2": "Jis nesidera su tavo kreditoriais. Tarp Debt-Free.World ir bet ko, kam esi skolingas pinigų, niekada nėra jokio kontakto.",
  "wtin_not_3": "Jis netvarko tavo pinigų ir nepriima mokėjimų, skirtų kreditoriams. Mokėjimus kreditoriams atlieki tu pats, tiesiogiai jiems. Vieninteliai pinigai, kurie kada nors mus pasiekia, yra 19€ už 90-Day Companion, jei jį pasirinksi.",
  "wtin_not_4": "Jis neteikia teisinių konsultacijų. Jis gali pasakyti, ką reiškia sąvoka ir kokia paprastai būna pasekmė; jis negali pasakyti, kokia yra tavo teisinė padėtis.",
  "wtin_not_5": "Jis nepakeičia skolų konsultavimo ar finansinio konsultavimo. Šios paslaugos daugelyje šalių yra licencijuojamos, o ši nėra. Dėl to nacionalinės organizacijos rodomos kiekviename puslapyje.",
  "wtin_does_label": "Ką jis daro vietoj to",
  "wtin_does_1": "Jis sudeda tavo paties skaičius į vieną vietą — kiekvieną skolą, kiekvieną palūkanų normą, kiekvieną datą — ir atlieka iš jų išplaukiančius skaičiavimus.",
  "wtin_does_2": "Jis greta išdėsto kelius, kurie tavo padėtyje egzistuoja, ir tai, kur kiekvienas veda. Kurį kelią pasirinkti, sprendi tu.",
  "wtin_does_3": "Jis rodo nacionalines organizacijas, kurios gali veikti ten, kur mes negalime, nuo pat pirmo puslapio — ne išnašoje pabaigoje.",
  "wtin_contact": "Klausimai dėl bet ko šiame puslapyje: support@debt-free.world",
  "wtin_foot_link": "Kas tai nėra",
  "wtin_faq_q": "Ar pakeičiate nemokamą skolų konsultavimą?",
  "wtin_faq_a": "Ne. Debt-Free.World niekam tavęs neatstovauja, nesidera su tavo kreditoriais, netvarko tavo pinigų, neteikia teisinių konsultacijų ir nepakeičia skolų konsultavimo ar finansinio konsultavimo."
