  "mf_x_del90": "A 90. napon töröljük a tervedet, a válaszaidat, a dokumentumaidat és mindent, ami személyes bennük. A szolgáltatásunkban semmi sem marad abból, ami a tiéd. A terved a tiéd, és nélkülünk is működik.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "Amikor az élet hirtelen megváltozik",
  "crisis_lead": "A hirtelen változás nem törli el az eddigi haladásodat. Válaszd azt, ami a helyzetedhez legközelebb áll — minden terv azzal az egy-két dologgal kezdődik, ami ma a legfontosabb, majd azzal, hogyan találj újra biztos talajt.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Fogalmazz levelet a hitelezőnek",
  "crisis_act_support": "Találj ellenőrzött segítséget a környékeden",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "Ez általános tájékoztatás, nem jogi vagy orvosi tanács. Bármiben, ami kifejezetten a te helyzetedre vonatkozik, támaszkodj a Támogatás rovat ingyenes szolgáltatásaira, és ahol számít, egy szakképzett szakemberre.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "A jövedelem elvesztése ijesztő, de több mozgástered van, mint amennyinek most tűnik. Ma semmit sem kell megoldani — csak elkezdeni.",
  "crisis_jobloss_i1": "Előbb a létszükségleteket védd meg. Bármilyen fedezetlen adósság előtt győződj meg róla, hogy a lakhatás, az élelem, az áram és a munkakereséshez szükséges közlekedés fedezve van. Ezek a kártya- és hiteltörlesztések elé kerülnek.",
  "crisis_jobloss_i2": "Szólj a hitelezőidnek, mielőtt lemaradnál egy törlesztéssel. Egy rövid, őszinte üzenet arról, hogy megváltozott a jövedelmed, ajtót nyit egy szünetre vagy alacsonyabb részletre — és sokkal könnyebb elrendezni, mielőtt megérkezik a felszólító levél.",
  "crisis_jobloss_i3": "Nézd meg, mi jár neked. Lehet, hogy van támogatás, amit igényelhetsz, amíg állások között vagy. Az országod ellenőrzött szolgáltatásai pontosan megmondják, mi vonatkozik rád.",
  "crisis_jobloss_s1": "Építsd újra a költségvetést az új, alacsonyabb jövedelmed köré — egyelőre csak a létszükségletek, minden más szünetel, amíg a helyzet le nem csillapodik.",
  "crisis_jobloss_s2": "Minden ideiglenes megállapodást a hitelezővel írásban rögzíts, hogy egy nehéz hónapból ne váljon csendben mulasztás.",
  "crisis_jobloss_s3": "Ne végy fel új adósságot a régi fedezésére. Ha kölcsönből fizetsz egy hitelezőt, azzal csak mélyíted a gödröt — az itteni tervek és eszközök úgy készültek, hogy enélkül működjenek.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "Amikor az egészséged figyelmet kíván, a pénzgondok mindent nehezebbé tesznek. A gyógyulásod az első — ez a terv arra ügyel, hogy az anyagi oldal ne tetézze a terhet.",
  "crisis_illness_i1": "Előbb a létszükségleteket védd meg. A lakhatás, az élelem, az áram és mindaz, amire a gondozásodhoz szükséged van, bármilyen fedezetlen adósság törlesztése elé kerül.",
  "crisis_illness_i2": "Tudasd a hitelezőkkel, hogy megváltozott a helyzeted. Senkinek sem tartozol az orvosi adataiddal — csupán annyival, hogy megváltozott a jövedelmed vagy a teherbírásod, és hogy ideiglenes, nehéz helyzetre szóló megállapodást kérsz.",
  "crisis_illness_i3": "Igényeld, ami jár neked. Lehet, hogy táppénz vagy más támogatás jár. Az országod ellenőrzött szolgáltatásai a megfelelő helyre irányítanak — az egészség oldalán pedig kérlek, támaszkodj orvosi szakemberekre.",
  "crisis_illness_s1": "Szűkítsd a költségvetést a létszükségletekre, amíg csökkent a jövedelmed, és térj vissza rá, ahogy a helyzeted változik.",
  "crisis_illness_s2": "Minden hitelezői megállapodást rögzíts írásban, és tarts meg egy másolatot — eggyel kevesebb dolog, amit fejben kell tartanod.",
  "crisis_illness_s3": "Ne végy fel kölcsönt a meglévő adósság fedezésére. Kérj inkább időt; a legtöbb hitelező sokkal szívesebben vár, mint hogy tovább szorongasson.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Egy közös élet szétszálazása magában is elég nehéz a pénzköd nélkül. Csináld egyszerre egy tiszta lépéssel — nincs szükséged minden válaszra ezen a héten.",
  "crisis_sep_i1": "Előbb a létszükségleteket védd meg — magadért és mindenkiért, aki tőled függ. A lakhatás, az élelem és az áram a fedezetlen adósság elé kerül.",
  "crisis_sep_i2": "A közös adósságok ügyében vedd fel korán a kapcsolatot a hitelezőkkel. Kérdezd meg, milyen lehetőségeid vannak, és minden változást rögzíts írásban. Ahol az adósság mindkét névre szól, vezess feljegyzést a megállapodottakról.",
  "crisis_sep_i3": "Nézd meg, milyen támogatást igényelhetsz, ahogy a háztartásod változik. Az országod ellenőrzött szolgáltatásai megmondják, mi vonatkozik rád — a közös adósságok jogi oldalán pedig az ingyenes állami adósságsegítség vagy egy szakképzett tanácsadó a megfelelő hely.",
  "crisis_sep_s1": "Építsd újra a költségvetést a saját jövedelmed és költségeid köré, egyszemélyes háztartásként.",
  "crisis_sep_s2": "Ahol tudod, válaszd szét a pénzügyeket lépésről lépésre, minden megállapodásról írásos feljegyzést vezetve.",
  "crisis_sep_s3": "Ne végy fel új adósságot az átmenet megkönnyítésére. A kiegyensúlyozott, őszinte megállapodások sokkal jobban megvédenek, mint a kölcsön.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "Egy váratlan kiadás vagy sokk félrelökheti a tervet. Ez nem törli el az eddigi haladásodat — csak egy nyugodt szünetet és egy tiszta következő lépést kíván.",
  "crisis_emerg_i1": "Előbb fedezd az igazán létfontosat — biztonság, lakhatás, élelem, áram. Egy egyszeri vészhelyzet nem az a pillanat, amikor a kártyatörlesztést a világítás fenntartása elé teszed.",
  "crisis_emerg_i2": "Ha a vészhelyzet miatt lemaradsz egy törlesztéssel, szólj most annak a hitelezőnek, és kérj rövid törlesztési szünetet. Egy betervezett szünet mindig jobb, mint egy csendes elmaradás.",
  "crisis_emerg_i3": "Nézd meg, van-e vészhelyzeti támogatás, amelyet igénybe vehetsz. Az országod ellenőrzött szolgáltatásai olyan segítséghez irányíthatnak, amelyről talán nem is tudsz.",
  "crisis_emerg_s1": "Amint az azonnali sokkot kezelted, lassan építsd újra a tartalékodat — még egy kis összeg is számít hetente.",
  "crisis_emerg_s2": "Nézd át újra a költségvetést, és igazítsd a tervet a következő hetekre — ne mindjárt az egész évre.",
  "crisis_emerg_s3": "Kerüld a drága kölcsönt a hézag áthidalására. Egy rövid megállapodás egy hitelezővel, akid már van, szinte mindig kevesebbe kerül.",
  "ci_trend_title": "Your buffer, week by week",
  "ci_trend_empty": "A trended itt épül fel. Rögzíts pár hetet, és látni fogod, ahogy alakot ölt.",
  "ci_title": "How did this week go?",
  "ci_lead": "Egy gyors számvetés — semmi ítélkezés, nincs megszakítandó sorozat. Csak egy jelölés arról, hol tartasz ezen a héten.",
  "ci_buffer_lbl": "Ami pénzed a héten megmaradt",
