  "dfd_extra": "Havi extra befizetés",
  "dfd_note": "Havi {monthly} mellett {total} adósságot törlesztesz. Ha havonta akár keveset is hozzáteszel, közelebb hozod ezt a napot.",
  "dfd_saved": "Ez körülbelül {amt} megspórolt kamat",
  "dfd_saved_floor": "Legalább {amt} megspórolt kamat — valószínűleg több, ha minden kamat ki van töltve",
  "dfd_date_approx": "Kamat nélkül számolva — a valós dátumod valószínűleg későbbi",
  "dfd_rate_why": "Ez a dátum figyelmen kívül hagyja a kamatot, mert még nincs mentve kamatláb. Általában épp a kamat teszi ilyen erőssé a kis rátörlesztést — add meg a kamatlábad, hogy lásd a valós dátumot, és mennyi kamatot tüntet el minden plusz befizetés.",
  "dfd_rate_partial": "Néhány adósságnál nincs mentve kamatláb, ezért itt 0%-ként számítanak. A valós számok jobbak a mutatottnál — add meg a hiányzó kamatlábakat, hogy lásd őket.",
  "dfd_rate_cta": "Szerkeszd a terved",
  "dfd_stabilise": "A kiadásaid jelenleg meghaladják a bevételeidet, így még nincs törlesztési dátum. Az első cél a levegővétel — kezdd a Krízisköltségvetés-tervezővel.",
  "dfd_buffer_first": "Mielőtt a többlet az adósságra menne: egy {gap} tartalék azt jelenti, hogy egy váratlan számla nem válik új adóssággá.",
  "strat_snow": "Hólabda",
  "strat_aval": "Lavina",
  "strat_first": "Ezt töröld először",
  "strat_snow_note": "Legkisebb tartozás először. A gyors győzelmek lendületet adnak — erős, amikor az elkezdés a legnehezebb.",
  "strat_aval_note": "Legmagasabb kamat először. Hosszú távon ez kerül a legkevesebbe — erős, amikor a drága adósság szív ki.",
  "strat_empty": "Add hozzá az adósságaidat a regisztráció során, hogy egymás mellett hasonlíthasd össze a stratégiákat.",
  "strat_unknown": "ismeretlen kamat",
  "strat_snow_why": "Nálad ez a legkisebb tartozásoddal kezdődik: {target}.",
  "strat_aval_why": "Nálad ez a legmagasabb kamatú tartozásoddal kezdődik: {target}.",
  "tool_intro_dfd": "Ez a valós számaidat egyetlen dátummá alakítja — a nappá, amikor szabad lehetsz. Aztán megmutatja, mennyivel korábbra hozná ezt akár egy kis rátörlesztés is.",
  "tool_intro_strat": "Nincs egyetlen „helyes” mód az adósság törlesztésére — van néhány bevált. Ez kettőt mutat egymás mellett, és hogy melyik illik a helyzetedhez. Semmi szakzsargon, csak a te számaid.",
  "tool_intro_budget": "Mielőtt bármi az adósságra menne, az életed az első. Ez felsorolja, mi létszükséglet, majd őszintén megmutatja, mennyi marad arra, amivel tartozol.",
  "tool_intro_income": "Nem kell megdupláznod a jövedelmed ahhoz, hogy változtass az ütemterveden. Ez megmutatja, mennyivel hamarabb lennél szabad minden pluszért, amit be tudsz hozni.",
  "tool_intro_collect": "Nem minden adósság egyformán sürgős, és mindet ugyanúgy kezelni kimerítő. Ez a tieidet aszerint rendezi, mi kíván most valóban figyelmet — hogy fellélegezhess.",
  "tool_intro_legal": "Több jogod van, mint amennyiről valószínűleg beszéltek neked. Ez közérthető nyelven mutatja be a védelmet ott, ahol élsz, hogy senki ne gyakorolhasson rád nyomást olyasmivel, ami nem igaz.",
  "nav_g_debtfree_sub": "Minden, ami kell, hogy tisztán lásd a helyzeted és megtervezd a kiutat.",
  "nav_g_tools_sub": "Hat kalkulátor. Mindegyik egy valódi kérdésre válaszol a pénzedről.",
  "nav_g_learn_sub": "Rövid, őszinte olvasmányok — semmi töltelék, semmi eladó.",
  "nav_g_recovery_sub": "Amikor készen állsz, mélyebb eszközök a visszavágáshoz és az újjáépítéshez.",
  "strat_cmp_title": "A két utad egymás mellett",
  "strat_cmp_snow": "Snowball",
  "strat_cmp_aval": "Avalanche",
  "strat_cmp_months": "{m} months",
  "strat_cmp_interest": "Interest you'd pay",
  "strat_cmp_first": "Az első adósság {m} hónap alatt eltűnik",
  "strat_cmp_verdict_aval": "A te számaidnál a Lavina körülbelül {save} megtakarítást hoz, és nagyjából {months} hónappal hamarabb tisztáz mindent. Ha az visz előre, hogy látod csökkenni a teljes költséget, itt kezdj.",
  "strat_cmp_verdict_snow": "A te számaidnál ez a kettő közel egyszerre zárul. A Hólabda {first} hónap alatt tisztázza az első adósságodat — ez a korai győzelem összesen csak nagyjából {extra} többletbe kerül. Ha a lendület visz előre, itt kezdj.",
  "strat_cmp_approx": "Irányadó becslés: azt feltételezi, hogy a költségvetésed minden szabad része sorban az adósságokra megy. A tényleges fizetési sorrended és az esetleges minimumtörlesztések ezt eltolhatják.",
  "strat_cmp_needsurplus": "Amint minden hónapban marad pénz, ez megmutatja mindkét utat, és azt, melyik szabadít fel hamarabb. Egyelőre az alábbi sorrend még mindig okos hely a kezdéshez.",
