  "budget_housing": "Lakhatás",
  "budget_other": "Egyéb létszükségletek",
  "budget_left": "Adósságra és megtakarításra marad",
  "budget_shortfall": "Havi hiány",
  "budget_note": "Krízisben a létszükségletek jönnek először — lakhatás, élelem, áram, közlekedés. Ami marad, az a törlesztőképességed. Ha negatív, az nem kudarc: jelzés, hogy használd a tervedben lévő ingyenes segítséget.",
  "budget_life": "Room for life",
