  "income_nostart": "Amint havi többleted lesz, az extra bevétel itt lerövidíti az ütemtervedet.",
  "income_base": "A jelenlegi helyzet szerint: {date}",
  "collect_note": "A behajtásban vagy bíróságon lévő adósságok mennek először — jogi súlyuk van. A magas kamatú adósság jön ezután, mert ez nő a leggyorsabban.",
