  "h_hero_h1": "Megérdemled, hogy pontosan lásd, hol tartasz az adósságaiddal — olyan tisztánlátást, amilyet más nem ad neked <span class=\"g\">ingyen</span>.",
  "h_promise": "Ez nem egy olyan terv, amit mindenkire ráhúzunk. A te helyzetedre és a te pontos számaidra épül — és itt senki sem ítélkezik afölött, hogyan jutottál idáig.",
