  "h_eco_p5_h": "Alkoss",
  "h_eco_p5_p": "A következő fejezeted, ha szeretnél egyet.",
  "h_eco_p5_tag": "Érkezik 2029",
  "h_pf_eyebrow": "90-DAY PLAN · 0€ örökre",
  "h_pf_title": "A teljes kiindulópontod.",
  "h_pf_lead": "A legtöbb ember hónapokat tölt azzal, hogy találgatja, mit kezdjen az adóssággal — kerüli a leveleket, kerüli a számokat, kerüli az egész témát. Ez a találgatást bizonyossággá váltja, kb. két perc alatt, ingyen.",
  "h_pf_li1_feat": "Személyre szabott terv a valós számaidból",
  "h_pf_li1_mean": "— nem olyan tanács, ami bárkire ráillene",
  "h_pf_li2_feat": "A pontos adósságmentes napod, és mi mozgatja",
