  "mf_x_del90": "În ziua 90 ștergem planul tău, răspunsurile tale, documentele tale și tot ce este personal în ele. În serviciul nostru nu rămâne nimic din ce este al tău. Planul tău este al tău și funcționează fără noi.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Planuri de criză",
  "crisis_title": "Când viața se schimbă brusc",
  "crisis_lead": "O schimbare bruscă nu șterge progresul pe care l-ai făcut. Alege ce e mai aproape de situația ta — fiecare plan începe cu unul sau două lucruri care contează cel mai mult azi, apoi cu cum să calci din nou pe teren solid.",
  "crisis_immediate": "Chiar acum",
  "crisis_stabilise": "Revino pe teren solid",
  "crisis_act_letter": "Redactează o scrisoare către creditor",
  "crisis_act_support": "Găsește ajutor verificat acolo unde ești",
  "crisis_act_budget": "Deschide planificatorul de buget",
  "crisis_safe_note": "Aceasta este o îndrumare generală, nu un sfat juridic sau medical. Pentru ce ține de situația ta, sprijină-te pe serviciile gratuite din secțiunea Sprijin și, când contează, pe un profesionist calificat.",
  "crisis_jobloss_t": "Pierderea locului de muncă",
  "crisis_jobloss_intro": "Pierderea unui venit sperie, dar ai mai mult loc de mișcare decât pare acum. Nimic nu trebuie rezolvat azi — doar început.",
  "crisis_jobloss_i1": "Protejează întâi strictul necesar. Înainte de orice datorie negarantată, asigură-te că sunt acoperite locuința, mâncarea, utilitățile și transportul de care ai nevoie ca să cauți de lucru. Ele vin înaintea plăților la carduri sau credite.",
  "crisis_jobloss_i2": "Anunță-ți creditorii înainte să întârzii o plată. Un mesaj scurt și sincer, că venitul tău s-a schimbat, deschide ușa spre o pauză sau o rată mai mică — și e mult mai ușor de aranjat înainte să sosească o notificare de restanță.",
  "crisis_jobloss_i3": "Verifică la ce ai dreptul. Pot exista ajutoare pe care le poți cere cât timp ești fără loc de muncă. Serviciile verificate din țara ta îți pot spune exact ce ți se aplică.",
  "crisis_jobloss_s1": "Reface bugetul în jurul noului tău venit, mai mic — deocamdată doar strictul necesar, restul în pauză până se așază lucrurile.",
  "crisis_jobloss_s2": "Obține în scris orice înțelegere temporară cu un creditor, ca o lună grea să nu se transforme pe tăcute într-o restanță.",
  "crisis_jobloss_s3": "Nu lua datorii noi ca să le acoperi pe cele vechi. A te împrumuta ca să plătești un creditor doar adâncește groapa — planurile și instrumentele de aici sunt făcute să funcționeze fără asta.",
  "crisis_illness_t": "Boală sau concediu medical",
  "crisis_illness_intro": "Când sănătatea îți cere atenția, grijile legate de bani fac totul mai greu. Recuperarea ta vine prima — planul acesta ține partea financiară departe de povară.",
  "crisis_illness_i1": "Protejează întâi strictul necesar. Locuința, mâncarea, utilitățile și tot ce îți trebuie pentru îngrijire vin înaintea oricărei plăți de datorie negarantată.",
  "crisis_illness_i2": "Anunță creditorii că situația ta s-a schimbat. Nu datorezi nimănui datele tale medicale — doar faptul că venitul sau capacitatea ta s-au schimbat și că ceri o înțelegere temporară pentru dificultate.",
  "crisis_illness_i3": "Cere ceea ce ți se cuvine. S-ar putea să ai dreptul la indemnizație de boală sau la alt ajutor. Serviciile verificate din țara ta te îndrumă spre locul potrivit — iar pentru sănătate, sprijină-te pe profesioniștii medicali.",
  "crisis_illness_s1": "Redu bugetul la strictul necesar cât timp venitul e mai mic și revizuiește-l pe măsură ce situația se schimbă.",
  "crisis_illness_s2": "Pune în scris orice înțelegere cu un creditor și păstrează o copie — un lucru mai puțin de ținut în minte.",
  "crisis_illness_s3": "Nu te împrumuta ca să acoperi o datorie existentă. Cere mai degrabă timp; majoritatea creditorilor preferă să aștepte decât să te împingă și mai mult.",
  "crisis_sep_t": "Separare sau divorț",
  "crisis_sep_intro": "Descâlcirea unei vieți împărțite e deja destul de grea fără ceața banilor. Mergi câte un pas clar pe rând — nu ai nevoie de toate răspunsurile săptămâna asta.",
  "crisis_sep_i1": "Protejează întâi strictul necesar, pentru tine și pentru cei care depind de tine. Locuința, mâncarea și utilitățile vin înaintea datoriei negarantate.",
  "crisis_sep_i2": "Contactează din timp creditorii pentru orice datorie comună. Întreabă care îți sunt opțiunile și obține fiecare schimbare în scris. Când o datorie e pe numele amândurora, ține evidența a ceea ce se convine.",
  "crisis_sep_i3": "Verifică ce ajutoare poți cere când gospodăria ta se schimbă. Serviciile verificate din țara ta îți pot spune ce ți se aplică — iar pentru partea juridică a datoriilor comune, locul potrivit este ajutorul public gratuit sau un consilier calificat.",
  "crisis_sep_s1": "Reface bugetul în jurul propriilor tale venituri și cheltuieli, ca gospodărie de o singură persoană.",
  "crisis_sep_s2": "Acolo unde poți, separă finanțele pas cu pas, păstrând evidența scrisă a fiecărei înțelegeri.",
  "crisis_sep_s3": "Nu lua datorii noi ca să atenuezi tranziția. Înțelegerile ferme și oneste te protejează mult mai bine decât împrumutul.",
  "crisis_emerg_t": "O urgență neașteptată",
  "crisis_emerg_intro": "O cheltuială neașteptată sau un șoc pot da planul peste cap. Nu șterge progresul tău — are nevoie doar de o pauză calmă și de un pas următor clar.",
  "crisis_emerg_i1": "Acoperă întâi ce e cu adevărat esențial — siguranță, locuință, mâncare, utilități. O urgență izolată nu e momentul să pui plata unui card înaintea faptului de a ține lumina aprinsă.",
  "crisis_emerg_i2": "Dacă urgența te face să întârzii o plată, anunță acel creditor acum și cere o scurtă pauză la plăți. O pauză planificată e mereu mai bună decât o restanță pe tăcute.",
  "crisis_emerg_i3": "Verifică dacă există vreun ajutor de urgență la care poți apela. Serviciile verificate din țara ta te pot îndruma spre un ajutor despre care poate nu știai că există.",
  "crisis_emerg_s1": "După ce ai gestionat șocul imediat, reconstruiește-ți perna încet — chiar și o sumă mică pe săptămână contează.",
  "crisis_emerg_s2": "Verifică din nou bugetul și ajustează planul pentru săptămânile ce vin, nu pentru tot anul deodată.",
  "crisis_emerg_s3": "Evită creditul scump ca să treci peste gol. O înțelegere scurtă cu un creditor pe care îl ai deja te costă aproape întotdeauna mai puțin.",
  "ci_trend_title": "Perna ta, săptămână de săptămână",
  "ci_trend_empty": "Tendința ta se construiește aici. Notează câteva săptămâni și o vei vedea prinzând formă.",
