  "h_pf_li1_mean": "— nu sfaturi care s-ar potrivi oricui",
  "h_pf_li2_feat": "Data ta exactă fără datorii și ce o mișcă",
  "h_pf_li2_mean": "— ca finalul să nu mai fie o presupunere",
  "h_pf_li3_feat": "Care datorii au consecințe reale — și de ce",
