  "mf_x_del90": "90. dana brišemo tvoj plan, tvoje odgovore, tvoje dokumente i sve osobno u njima. U našoj usluzi ne ostaje ništa tvoje. Tvoj plan je tvoj i radi bez nas.",
  /* ── Pass 3 · Crisis Plans · Weekly Check-in · Document Archive ── */
  "crisis_eyebrow": "Crisis plans",
  "crisis_title": "Kad se život iznenada promijeni",
  "crisis_lead": "Nagla promjena ne poništava napredak koji si postigao. Odaberi ono što je najbliže tvojoj situaciji — svaki plan počinje s jednom ili dvije stvari koje danas najviše znače, a zatim s tim kako povratiti tlo pod nogama.",
  "crisis_immediate": "Right now",
  "crisis_stabilise": "Steady the ground",
  "crisis_act_letter": "Sastavi pismo vjerovniku",
  "crisis_act_support": "Pronađi provjerenu pomoć ondje gdje jesi",
  "crisis_act_budget": "Open the budget planner",
  "crisis_safe_note": "Ovo je opća uputa, ne pravni ni medicinski savjet. Za sve što se tiče tvoje konkretne situacije, osloni se na besplatne službe u odjeljku Podrška, a gdje je važno, na stručnu osobu.",
  "crisis_jobloss_t": "Job loss",
  "crisis_jobloss_intro": "Gubitak prihoda je zastrašujuć, ali imaš više prostora za pokret nego što se sada čini. Ništa se ne mora riješiti danas — samo započeti.",
  "crisis_jobloss_i1": "Prvo zaštiti ono nužno. Prije bilo kakvog neosiguranog duga pobrini se da su pokriveni stanovanje, hrana, struja i prijevoz koji ti treba za traženje posla. To dolazi prije otplate kartica i kredita.",
  "crisis_jobloss_i2": "Reci vjerovnicima prije nego što propustiš plaćanje. Kratka, iskrena poruka da ti se promijenio prihod otvara vrata pauzi ili nižoj rati — a puno je lakše dogovoriti prije nego što stigne opomena zbog zaostatka.",
  "crisis_jobloss_i3": "Provjeri na što imaš pravo. Možda postoji podrška koju možeš zatražiti dok si između poslova. Provjerene službe u tvojoj zemlji reći će ti točno što se odnosi na tebe.",
  "crisis_jobloss_s1": "Iznova posloži proračun oko svog novog, nižeg prihoda — zasad samo ono nužno, sve ostalo na pauzi dok se stvari ne slegnu.",
  "crisis_jobloss_s2": "Svaki privremeni dogovor s vjerovnikom imaj u pisanom obliku, da se težak mjesec ne pretvori tiho u neplaćanje.",
  "crisis_jobloss_s3": "Ne uzimaj novi dug da pokriješ stari. Posuđivanje da bi platio zajmodavca samo produbljuje rupu — planovi i alati ovdje napravljeni su da rade bez toga.",
  "crisis_illness_t": "Illness or sick leave",
  "crisis_illness_intro": "Kad ti zdravlje traži pažnju, brige oko novca sve čine težim. Tvoj oporavak je na prvom mjestu — ovaj plan pazi da financijska strana ne dodaje teret.",
  "crisis_illness_i1": "Prvo zaštiti ono nužno. Stanovanje, hrana, struja i sve što ti treba za tvoju skrb dolaze prije bilo kakve otplate neosiguranog duga.",
  "crisis_illness_i2": "Daj vjerovnicima do znanja da ti se situacija promijenila. Nikome ne duguješ svoje medicinske podatke — samo to da ti se promijenio prihod ili sposobnost i da tražiš privremeni dogovor zbog otežanih okolnosti.",
  "crisis_illness_i3": "Zatraži ono na što imaš pravo. Možda ti pripada naknada za bolovanje ili druga podrška. Provjerene službe u tvojoj zemlji uputit će te na pravo mjesto — a za zdravstvenu stranu, molim te, osloni se na medicinske stručnjake.",
  "crisis_illness_s1": "Svedi proračun na ono nužno dok ti je prihod smanjen i vraćaj mu se kako se situacija mijenja.",
  "crisis_illness_s2": "Svaki dogovor s vjerovnikom imaj u pisanom obliku i sačuvaj kopiju — jedna briga manje za držati u glavi.",
  "crisis_illness_s3": "Ne posuđuj da pokriješ postojeći dug. Umjesto toga zatraži vrijeme; većina vjerovnika radije će pričekati nego te dalje pritiskati.",
  "crisis_sep_t": "Separation or divorce",
  "crisis_sep_intro": "Razmrsivanje zajedničkog života dovoljno je teško i bez magle oko novca. Idi korak po korak, jasno — ne trebaju ti svi odgovori ovaj tjedan.",
  "crisis_sep_i1": "Prvo zaštiti ono nužno — za sebe i za svakoga tko ovisi o tebi. Stanovanje, hrana i struja dolaze prije neosiguranog duga.",
  "crisis_sep_i2": "Oko zajedničkih dugova javi se vjerovnicima rano. Pitaj koje su ti mogućnosti i svaku promjenu imaj u pisanom obliku. Gdje je dug na oba imena, vodi zabilješku o dogovorenom.",
  "crisis_sep_i3": "Provjeri koju podršku možeš zatražiti dok ti se kućanstvo mijenja. Provjerene službe u tvojoj zemlji reći će ti što se primjenjuje — a za pravnu stranu zajedničkih dugova pravo je mjesto besplatna državna pomoć dužnicima ili stručni savjetnik.",
  "crisis_sep_s1": "Iznova posloži proračun oko vlastitog prihoda i troškova, kao jednočlano kućanstvo.",
  "crisis_sep_s2": "Gdje možeš, razdvajaj financije korak po korak, vodeći pisane zabilješke o svakom dogovoru.",
  "crisis_sep_s3": "Ne uzimaj novi dug da olakšaš prijelaz. Postojani, pošteni dogovori štite te daleko bolje nego posuđivanje.",
  "crisis_emerg_t": "A sudden emergency",
  "crisis_emerg_intro": "Neočekivan trošak ili šok može izbaciti plan iz kolosijeka. To ne briše napredak koji si postigao — treba samo miran predah i jedan jasan sljedeći korak.",
  "crisis_emerg_i1": "Prvo pokrij ono uistinu nužno — sigurnost, stanovanje, hrana, struja. Jednokratna hitna situacija nije trenutak da otplatu kartice staviš ispred toga da kod kuće ima struje.",
  "crisis_emerg_i2": "Ako zbog hitne situacije propustiš plaćanje, reci to tom vjerovniku odmah i zatraži kratku pauzu u otplati. Planirana pauza uvijek je bolja od tihog propusta.",
  "crisis_emerg_i3": "Provjeri ima li kakve hitne podrške koju možeš iskoristiti. Provjerene službe u tvojoj zemlji mogu te uputiti na pomoć za koju možda i ne znaš da postoji.",
  "crisis_emerg_s1": "Kad je prvi šok zbrinut, polako obnavljaj svoj jastuk — čak i mali iznos svakog tjedna se broji.",
  "crisis_emerg_s2": "Ponovno provjeri proračun i prilagodi plan za nadolazeće tjedne, ne odmah za cijelu godinu.",
  "crisis_emerg_s3": "Izbjegavaj skupo posuđivanje za premošćivanje rupe. Kratak dogovor s vjerovnikom kojeg već imaš gotovo te uvijek košta manje.",
  "ci_trend_title": "Your buffer, week by week",
