  "dfd_rate_why": "Ovaj datum izostavlja kamate jer još nije spremljena nijedna kamatna stopa. Upravo kamate obično čine malu doplatu tako moćnom — dodaj svoju stopu da vidiš stvarni datum i koliko kamata briše svaka dodatna uplata.",
