  "tool_intro_dfd": "Ovo tvoje stvarne brojeve pretvara u jedan datum — dan kad možeš biti slobodan. Zatim pokazuje koliko bi ga ranije približila i mala dodatna uplata.",
  "tool_intro_strat": "Ne postoji jedan „ispravan” način otplate duga — postoji nekoliko provjerenih. Ovo ti pokazuje dva, jedan uz drugi, i koji odgovara tvojoj situaciji. Bez žargona, samo tvoji brojevi.",
  "tool_intro_budget": "Prije nego išta ode na dug, tvoj život je na prvom mjestu. Ovo raspisuje što je nužno, a zatim ti pošteno pokazuje koliko ostaje za ono što duguješ.",
  "tool_intro_income": "Ne moraš udvostručiti prihod da promijeniš svoj vremenski okvir. Ovo pokazuje koliko bi prije bio slobodan za svaki dodatni djelić koji uspiješ zaraditi.",
  "tool_intro_collect": "Nije svaki dug jednako hitan, a jednako postupati sa svima iscrpljujuće je. Ovo tvoje razvrstava prema onome što sada uistinu treba pažnju — da možeš odahnuti.",
  "tool_intro_legal": "Imaš više prava nego što su ti vjerojatno rekli. Ovo jednostavnim jezikom izlaže zaštite ondje gdje živiš, da te nitko ne može pritiskati neistinama.",
  "nav_g_debtfree_sub": "Sve što ti treba da jasno vidiš svoju situaciju i isplaniraš izlaz.",
  "nav_g_tools_sub": "Šest kalkulatora. Svaki odgovara na jedno stvarno pitanje o tvom novcu.",
  "nav_g_learn_sub": "Kratki, iskreni tekstovi — bez ispune, ništa za kupiti.",
  "nav_g_recovery_sub": "Kad budeš spreman, dublji alati za uzvraćanje i obnovu.",
