  "strat_cmp_verdict_aval": "Pri tvojim brojevima Lavina ti štedi otprilike {save} i sve otplaćuje otprilike {months} mjeseci ranije. Ako te drži to što gledaš kako ukupni trošak pada, počni ovdje.",
  "strat_cmp_verdict_snow": "Pri tvojim brojevima ove dvije završavaju blizu jedna drugoj. Snježna gruda otplaćuje tvoj prvi dug za {first} mjeseci — ta rana pobjeda ukupno košta tek otprilike {extra} više. Ako te drži zalet, počni ovdje.",
  "strat_cmp_approx": "Okvirna procjena: pretpostavlja da svaki slobodni dio tvog proračuna ide na dugove redom. Tvoj stvarni redoslijed plaćanja i eventualne minimalne uplate to mogu pomaknuti.",
